import { useState, useCallback, useEffect } from 'react';
import type { NoteItem } from '../components/NotesTimeline';

interface UseNotesOptions {
  operationType: string;
  operationId: number | null;
  userId: number;
}

export function useNotes({ operationType, operationId, userId }: UseNotesOptions) {
  const [notes, setNotes] = useState<NoteItem[]>([]);
  const [loading, setLoading] = useState(false);

  const fetchNotes = useCallback(async () => {
    if (!operationId) return;
    setLoading(true);
    try {
      const result = await window.api.invoke('notes:list', { operationType, operationId });
      setNotes(result as NoteItem[]);
    } catch {
      setNotes([]);
    } finally {
      setLoading(false);
    }
  }, [operationType, operationId]);

  const addNote = useCallback(async (content: string) => {
    if (!operationId) return;
    const newNote = await window.api.invoke('notes:add', {
      operationType,
      operationId,
      content,
      userId,
    });
    setNotes((prev) => [...prev, newNote as NoteItem]);
  }, [operationType, operationId, userId]);

  useEffect(() => {
    fetchNotes();
  }, [fetchNotes]);

  return { notes, loading, addNote, fetchNotes };
}

import { ipcMain } from 'electron';
import { getDb } from '../database/connection';

export function registerSettingsHandlers() {
  // Get all settings
  ipcMain.handle('settings:getAll', async () => {
    const db = getDb();
    const rows = db.prepare('SELECT Key, Value FROM settings').all() as any[];
    const settings: Record<string, string> = {};
    for (const row of rows) {
      settings[row.Key] = row.Value;
    }
    return settings;
  });

  // Get single setting
  ipcMain.handle('settings:get', async (_event, key: string) => {
    const db = getDb();
    const row = db.prepare('SELECT Value FROM settings WHERE Key = ?').get(key) as any;
    return row?.Value ?? null;
  });

  // Set setting
  ipcMain.handle('settings:set', async (_event, key: string, value: string) => {
    const db = getDb();
    db.prepare('INSERT OR REPLACE INTO settings (Key, Value) VALUES (?, ?)').run(key, value);
    return { success: true };
  });

  // Set multiple settings
  ipcMain.handle('settings:setMany', async (_event, settings: Record<string, string>) => {
    const db = getDb();
    const stmt = db.prepare('INSERT OR REPLACE INTO settings (Key, Value) VALUES (?, ?)');
    const tx = db.transaction(() => {
      for (const [key, value] of Object.entries(settings)) {
        stmt.run(key, value);
      }
    });
    tx();
    return { success: true };
  });
}

