  useEffect(() => { fetchData(); }, []);

  const openCreate = () => {
    setEditing(null);
    setForm({ Name: '', Phone: '', Position: '', Department: '', BaseSalary: '', Allowances: '', HireDate: new Date().toISOString().split('T')[0], Notes: '', IsActive: 1 });
    setShowModal(true);
  };

  const openEdit = (emp: any) => {
    setEditing(emp);
    setForm({ Name: emp.Name, Phone: emp.Phone || '', Position: emp.Position || '', Department: emp.Department || '', BaseSalary: emp.BaseSalary?.toString() || '', Allowances: emp.Allowances?.toString() || '', HireDate: emp.HireDate || '', Notes: emp.Notes || '', IsActive: emp.IsActive });
    setShowModal(true);
  };

  const handleSave = async () => {
    if (!form.Name) { showToast('error', 'يرجى إدخال اسم الموظف'); return; }
    const data = { ...form, BaseSalary: parseFloat(form.BaseSalary) || 0, Allowances: parseFloat(form.Allowances) || 0 };
    if (editing) {
      await window.api.invoke('employees:update', editing.EmployeeID, data);
      showToast('success', 'تم تحديث الموظف');
    } else {
      await window.api.invoke('employees:create', data);
      showToast('success', 'تم إضافة الموظف');
    }
    setShowModal(false);
    fetchData();
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-bold text-slate-800 dark:text-white">الموظفين</h1>
        <Button onClick={openCreate} icon={<Plus size={16} />}>موظف جديد</Button>
      </div>

      <DataTable
        columns={[
          { key: 'Name', title: 'الاسم', render: (row) => <span className="font-medium">{row.Name}</span> },
          { key: 'Position', title: 'الوظيفة', render: (row) => row.Position || '—' },
          { key: 'Department', title: 'القسم', render: (row) => row.Department || '—' },
          { key: 'BaseSalary', title: 'الراتب الأساسي', render: (row) => `${row.BaseSalary?.toFixed(2) || '0'}` },
          { key: 'Balance', title: 'الرصيد', render: (row) => <span className={row.Balance > 0 ? 'text-green-600 font-medium' : 'text-slate-500'}>{row.Balance?.toFixed(2) || '0'}</span> },
          {
            key: 'actions', title: 'إجراءات',
            render: (row) => (
              <div className="flex gap-2">
                <button onClick={() => openEdit(row)} className="text-xs text-primary-600 hover:underline flex items-center gap-1"><Edit size={12} /> تعديل</button>
                <button className="text-xs text-slate-500 hover:text-primary-600 flex items-center gap-1"><FileText size={12} /> كشف حساب</button>
              </div>
            ),
          },
        ]}
        data={employees}
        keyField="EmployeeID"
        emptyMessage="لا يوجد موظفون"
      />

      <Modal isOpen={showModal} onClose={() => setShowModal(false)} title={editing ? 'تعديل موظف' : 'موظف جديد'}
        footer={<><Button variant="secondary" onClick={() => setShowModal(false)}>إلغاء</Button><Button onClick={handleSave}>حفظ</Button></>}
      >
        <div className="grid grid-cols-2 gap-4">
          <Input label="الاسم" value={form.Name} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setForm({ ...form, Name: e.target.value })} />
          <Input label="رقم الهاتف" value={form.Phone} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setForm({ ...form, Phone: e.target.value })} />
          <Input label="الوظيفة" value={form.Position} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setForm({ ...form, Position: e.target.value })} />
          <Input label="القسم" value={form.Department} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setForm({ ...form, Department: e.target.value })} />
          <Input label="الراتب الأساسي" type="number" value={form.BaseSalary} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setForm({ ...form, BaseSalary: e.target.value })} />
          <Input label="البدلات" type="number" value={form.Allowances} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setForm({ ...form, Allowances: e.target.value })} />
          <Input label="تاريخ التعيين" type="date" value={form.HireDate} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setForm({ ...form, HireDate: e.target.value })} />
        </div>
      </Modal>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Plus, Edit, Wallet, CreditCard, Smartphone } from 'lucide-react';
import { Button } from '../../components/ui/Button';
import { Input, Select } from '../../components/ui/Input';
import { Modal } from '../../components/ui/Modal';
import { Badge } from '../../components/ui/Badge';
import { DataTable } from '../../components/shared/DataTable';
import { useToastStore } from '../../components/ui/Toast';

export function AssetsPage() {
  const { showToast } = useToastStore();
  const [tab, setTab] = useState<'cash' | 'payment'>('cash');
  const [cashAccounts, setCashAccounts] = useState<any[]>([]);
  const [paymentMethods, setPaymentMethods] = useState<any[]>([]);
  const [showModal, setShowModal] = useState(false);
  const [editing, setEditing] = useState<any>(null);

  // Cash account form
  const [cashForm, setCashForm] = useState({ AccountName: '', AccountType: 'safe', Balance: '', BankName: '', AccountNumber: '', IsActive: 1 });
  // Payment method form
  const [pmForm, setPmForm] = useState({ MethodName: '', MethodType: 'pos_machine', Provider: '', PhoneNumber: '', IsActive: 1 });

  const fetchData = async () => {
    const [ca, pm] = await Promise.all([
      window.api.invoke('cashAccounts:list'),
      window.api.invoke('paymentMethods:list'),
    ]);
    setCashAccounts(ca);
    setPaymentMethods(pm);
  };

  useEffect(() => { fetchData(); }, []);

  const openCreateCash = () => {
    setEditing(null);
    setCashForm({ AccountName: '', AccountType: 'safe', Balance: '', BankName: '', AccountNumber: '', IsActive: 1 });
    setShowModal(true);
  };

  const openEditCash = (ca: any) => {
    setEditing(ca);
    setCashForm({ AccountName: ca.AccountName, AccountType: ca.AccountType, Balance: '', BankName: ca.BankName || '', AccountNumber: ca.AccountNumber || '', IsActive: ca.IsActive });
    setShowModal(true);
  };

  const openCreatePm = () => {
    setEditing({ isPayment: true });
    setPmForm({ MethodName: '', MethodType: 'pos_machine', Provider: '', PhoneNumber: '', IsActive: 1 });
    setShowModal(true);
  };

  const openEditPm = (pm: any) => {
    setEditing({ ...pm, isPayment: true });
    setPmForm({ MethodName: pm.MethodName, MethodType: pm.MethodType, Provider: pm.Provider || '', PhoneNumber: pm.PhoneNumber || '', IsActive: pm.IsActive });
    setShowModal(true);
  };

  const handleSaveCash = async () => {
    if (!cashForm.AccountName) { showToast('error', 'يرجى إدخال اسم الحساب'); return; }
    const data = { ...cashForm, Balance: parseFloat(cashForm.Balance) || 0 };
    if (editing) {
      await window.api.invoke('cashAccounts:update', editing.CashAccountID, data);
      showToast('success', 'تم تحديث الحساب');
    } else {
      await window.api.invoke('cashAccounts:create', data);
      showToast('success', 'تم إضافة الحساب');
    }
    setShowModal(false);
    fetchData();
  };

  const handleSavePm = async () => {
    if (!pmForm.MethodName) { showToast('error', 'يرجى إدخال اسم طريقة الدفع'); return; }
    if (editing?.PaymentMethodID) {
      await window.api.invoke('paymentMethods:update', editing.PaymentMethodID, pmForm);
      showToast('success', 'تم التحديث');
    } else {
      await window.api.invoke('paymentMethods:create', pmForm);
      showToast('success', 'تم الإضافة');
    }
    setShowModal(false);
    fetchData();
  };

  return (
    <div className="space-y-4">
      <h1 className="text-2xl font-bold text-slate-800 dark:text-white">الأصول النقدية</h1>

      {/* Tabs */}
      <div className="flex gap-2">
        <button onClick={() => setTab('cash')} className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-medium transition-colors ${tab === 'cash' ? 'bg-primary-600 text-white' : 'bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-300'}`}>
          <Wallet size={16} /> البنوك والخزائن
        </button>
        <button onClick={() => setTab('payment')} className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-medium transition-colors ${tab === 'payment' ? 'bg-primary-600 text-white' : 'bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-300'}`}>
          <CreditCard size={16} /> ماكينات وأنظمة الدفع
        </button>
      </div>

      {tab === 'cash' && (
        <div className="space-y-4">
          <div className="flex justify-end">
            <Button onClick={openCreateCash} icon={<Plus size={16} />}>حساب جديد</Button>
          </div>
          <DataTable
            columns={[
              { key: 'AccountName', title: 'الاسم', render: (row) => <span className="font-medium">{row.AccountName}</span> },
              { key: 'AccountType', title: 'النوع', render: (row) => <Badge variant={row.AccountType === 'safe' ? 'blue' : 'purple'}>{row.AccountType === 'safe' ? 'خزنة' : 'بنك'}</Badge> },
              { key: 'Balance', title: 'الرصيد', render: (row) => <span className="font-bold text-green-600">{row.Balance?.toFixed(2)}</span> },
              { key: 'BankName', title: 'البنك', render: (row) => row.BankName || '—' },
              { key: 'AccountNumber', title: 'رقم الحساب', render: (row) => row.AccountNumber || '—' },
              { key: 'actions', title: '', render: (row) => <button onClick={() => openEditCash(row)} className="text-xs text-primary-600 hover:underline flex items-center gap-1"><Edit size={12} /> تعديل</button> },
            ]}
            data={cashAccounts}
            keyField="CashAccountID"
            emptyMessage="لا توجد حسابات"
          />
        </div>
      )}

      {tab === 'payment' && (
        <div className="space-y-4">
          <div className="flex justify-end">
            <Button onClick={openCreatePm} icon={<Plus size={16} />}>طريقة دفع جديدة</Button>
          </div>
          <DataTable
            columns={[
              { key: 'MethodName', title: 'الاسم', render: (row) => <span className="font-medium">{row.MethodName}</span> },
              { key: 'MethodType', title: 'النوع', render: (row) => <Badge variant={row.MethodType === 'pos_machine' ? 'blue' : row.MethodType === 'digital_wallet' ? 'green' : 'purple'}>{row.MethodType === 'pos_machine' ? 'ماكينة' : row.MethodType === 'digital_wallet' ? 'محفظة' : 'تحويل'}</Badge> },
              { key: 'Provider', title: 'المزوّد', render: (row) => row.Provider || '—' },
              { key: 'PhoneNumber', title: 'رقم المحفظة', render: (row) => row.PhoneNumber || '—' },
              { key: 'Balance', title: 'الرصيد', render: (row) => <span className="font-bold text-green-600">{row.Balance?.toFixed(2)}</span> },
              { key: 'actions', title: '', render: (row) => <button onClick={() => openEditPm(row)} className="text-xs text-primary-600 hover:underline flex items-center gap-1"><Edit size={12} /> تعديل</button> },
            ]}
            data={paymentMethods}
            keyField="PaymentMethodID"
            emptyMessage="لا توجد طرق دفع"
          />
        </div>
      )}

      {/* Modal */}
      <Modal isOpen={showModal} onClose={() => setShowModal(false)} title={editing?.isPayment ? (editing?.PaymentMethodID ? 'تعديل طريقة دفع' : 'طريقة دفع جديدة') : (editing ? 'تعديل حساب' : 'حساب جديد')}
        footer={<><Button variant="secondary" onClick={() => setShowModal(false)}>إلغاء</Button><Button onClick={editing?.isPayment ? handleSavePm : handleSaveCash}>حفظ</Button></>}
      >
        {editing?.isPayment ? (
          <div className="grid grid-cols-2 gap-4">
            <Input label="الاسم" value={pmForm.MethodName} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setPmForm({ ...pmForm, MethodName: e.target.value })} />
            <Select label="النوع" value={pmForm.MethodType} onChange={(e) => setPmForm({ ...pmForm, MethodType: e.target.value })}>
              <option value="pos_machine">ماكينة دفع</option>
              <option value="digital_wallet">محفظة إلكترونية</option>
              <option value="transfer">تحويل</option>
            </Select>
            <Input label="المزوّد" value={pmForm.Provider} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setPmForm({ ...pmForm, Provider: e.target.value })} hint="فودافون، أورانج، اتصالات، إنستا باي..." />
            <Input label="رقم المحفظة" value={pmForm.PhoneNumber} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setPmForm({ ...pmForm, PhoneNumber: e.target.value })} />
          </div>
        ) : (
          <div className="grid grid-cols-2 gap-4">
            <Input label="اسم الحساب" value={cashForm.AccountName} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setCashForm({ ...cashForm, AccountName: e.target.value })} />
            <Select label="النوع" value={cashForm.AccountType} onChange={(e) => setCashForm({ ...cashForm, AccountType: e.target.value })}>
              <option value="safe">خزنة</option>
              <option value="bank">بنك</option>
            </Select>
            {cashForm.AccountType === 'bank' && (
              <>
                <Input label="اسم البنك" value={cashForm.BankName} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setCashForm({ ...cashForm, BankName: e.target.value })} />
                <Input label="رقم الحساب" value={cashForm.AccountNumber} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setCashForm({ ...cashForm, AccountNumber: e.target.value })} />
              </>
            )}
            {!editing && <Input label="الرصيد الافتتاحي" type="number" value={cashForm.Balance} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setCashForm({ ...cashForm, Balance: e.target.value })} />}
          </div>
        )}
      </Modal>
    </div>
  );
}

