import { ipcMain } from 'electron';
import { getDb } from '../database/connection';

export function registerInventoryHandlers() {
  // ===== WAREHOUSES =====
  ipcMain.handle('warehouses:list', async () => {
    const db = getDb();
    return db.prepare('SELECT * FROM warehouses WHERE IsActive = 1 ORDER BY WarehouseName ASC').all();
  });

  ipcMain.handle('warehouses:create', async (_event, data: { WarehouseName: string; WarehouseType: string }) => {
    const db = getDb();
    const result = db.prepare('INSERT INTO warehouses (WarehouseName, WarehouseType, IsActive) VALUES (?, ?, 1)').run(data.WarehouseName, data.WarehouseType || 'main');
    return { success: true, id: result.lastInsertRowid };
  });

  ipcMain.handle('warehouses:update', async (_event, id: number, data: { WarehouseName: string; WarehouseType: string }) => {
    const db = getDb();
    db.prepare('UPDATE warehouses SET WarehouseName = ?, WarehouseType = ? WHERE WarehouseID = ?').run(data.WarehouseName, data.WarehouseType, id);
    return { success: true };
  });

  ipcMain.handle('warehouses:delete', async (_event, id: number) => {
    const db = getDb();
    db.prepare('UPDATE warehouses SET IsActive = 0 WHERE WarehouseID = ?').run(id);
    return { success: true };
  });

  // ===== CATEGORIES =====
  ipcMain.handle('categories:list', async () => {
    const db = getDb();
    return db.prepare('SELECT * FROM categories ORDER BY CategoryName ASC').all();
  });

  ipcMain.handle('categories:create', async (_event, name: string, parentId?: number) => {
    const db = getDb();
    const result = db.prepare('INSERT INTO categories (CategoryName, ParentID) VALUES (?, ?)').run(name, parentId ?? null);
    return { success: true, id: result.lastInsertRowid };
  });

  // ===== ITEMS =====
  ipcMain.handle('items:list', async (_event, filters?: { search?: string; type?: string; isActive?: number }) => {
    const db = getDb();
    let query = `
      SELECT i.*, c.CategoryName,
        (SELECT COUNT(*) FROM item_serials s WHERE s.ItemID = i.ItemID AND s.Status = 'available') as AvailableSerials,
        (SELECT SUM(Quantity) FROM stock_quantities sq WHERE sq.ItemID = i.ItemID) as TotalStock
      FROM items i
      LEFT JOIN categories c ON i.CategoryID = c.CategoryID
      WHERE 1=1
    `;
    const params: any[] = [];
    if (filters?.search) {
      query += ' AND (i.ItemName LIKE ? OR i.Barcode LIKE ?)';
      params.push(`%${filters.search}%`, `%${filters.search}%`);
    }
    if (filters?.type && filters.type !== 'all') {
      query += ' AND i.ItemType = ?';
      params.push(filters.type);
    }
    if (filters?.isActive !== undefined) {
      query += ' AND i.IsActive = ?';
      params.push(filters.isActive);
    }
    query += ' ORDER BY i.ItemName ASC';
    return db.prepare(query).all(...params);
  });

  ipcMain.handle('items:get', async (_event, id: number) => {
    const db = getDb();
    return db.prepare('SELECT * FROM items WHERE ItemID = ?').get(id);
  });

  ipcMain.handle('items:create', async (_event, data: any) => {
    const db = getDb();
    const result = db.prepare(`
      INSERT INTO items (ItemName, CategoryID, Barcode, ItemType, IsSerialized, SalePrice, CostPrice, IsActive, MinStock, Unit)
      VALUES (@ItemName, @CategoryID, @Barcode, @ItemType, @IsSerialized, @SalePrice, @CostPrice, 1, @MinStock, @Unit)
    `).run(data);
    return { success: true, id: result.lastInsertRowid };
  });

  ipcMain.handle('items:update', async (_event, id: number, data: any) => {
    const db = getDb();
    db.prepare(`
      UPDATE items SET
        ItemName = @ItemName, CategoryID = @CategoryID, Barcode = @Barcode,
        ItemType = @ItemType, IsSerialized = @IsSerialized,
        SalePrice = @SalePrice, CostPrice = @CostPrice, IsActive = @IsActive, MinStock = @MinStock, Unit = @Unit
      WHERE ItemID = ?
    `).run({ ...data, id });
    return { success: true };
  });

  ipcMain.handle('items:delete', async (_event, id: number) => {
    const db = getDb();
    db.prepare('UPDATE items SET IsActive = 0 WHERE ItemID = ?').run(id);
    return { success: true };
  });

  // ===== ITEM SERIALS (IMEI) =====
  ipcMain.handle('serials:list', async (_event, itemId?: number, status?: string) => {
    const db = getDb();
    let query = `
      SELECT s.*, i.ItemName, w.WarehouseName
      FROM item_serials s
      JOIN items i ON s.ItemID = i.ItemID
      JOIN warehouses w ON s.WarehouseID = w.WarehouseID
      WHERE 1=1
    `;
    const params: any[] = [];
    if (itemId) { query += ' AND s.ItemID = ?'; params.push(itemId); }
    if (status && status !== 'all') { query += ' AND s.Status = ?'; params.push(status); }
    query += ' ORDER BY s.SerialID DESC';
    return db.prepare(query).all(...params);
  });

  ipcMain.handle('serials:add', async (_event, data: { ItemID: number; IMEI: string; WarehouseID: number; CostPrice?: number }) => {
    const db = getDb();
    const existing = db.prepare('SELECT SerialID FROM item_serials WHERE IMEI = ?').get(data.IMEI);
    if (existing) return { success: false, message: 'رقم IMEI موجود بالفعل' };
    const result = db.prepare(`
      INSERT INTO item_serials (ItemID, IMEI, Status, CostPrice, WarehouseID)
      VALUES (?, ?, 'available', ?, ?)
    `).run(data.ItemID, data.IMEI, data.CostPrice ?? 0, data.WarehouseID);
    return { success: true, id: result.lastInsertRowid };
  });

  ipcMain.handle('serials:getAvailable', async (_event, itemId: number, warehouseId?: number) => {
    const db = getDb();
    let query = 'SELECT * FROM item_serials WHERE ItemID = ? AND Status = ?';
    const params: any[] = [itemId, 'available'];
    if (warehouseId) { query += ' AND WarehouseID = ?'; params.push(warehouseId); }
    return db.prepare(query).all(...params);
  });

  // ===== STOCK QUANTITIES =====
  ipcMain.handle('stock:list', async (_event, warehouseId?: number) => {
    const db = getDb();
    let query = `
      SELECT sq.*, i.ItemName, i.Barcode, i.ItemType, w.WarehouseName
      FROM stock_quantities sq
      JOIN items i ON sq.ItemID = i.ItemID
      JOIN warehouses w ON sq.WarehouseID = w.WarehouseID
      WHERE i.IsActive = 1
    `;
    const params: any[] = [];
    if (warehouseId) { query += ' AND sq.WarehouseID = ?'; params.push(warehouseId); }
    query += ' ORDER BY i.ItemName ASC';
    return db.prepare(query).all(...params);
  });

  // ===== WAREHOUSE TRANSFERS =====
  ipcMain.handle('transfers:list', async () => {
    const db = getDb();
    return db.prepare(`
      SELECT t.*, fw.WarehouseName as FromWarehouse, tw.WarehouseName as ToWarehouse
      FROM warehouse_transfers t
      JOIN warehouses fw ON t.FromWarehouseID = fw.WarehouseID
      JOIN warehouses tw ON t.ToWarehouseID = tw.WarehouseID
      ORDER BY t.Date DESC
    `).all();
  });

  ipcMain.handle('transfers:create', async (_event, data: {
    FromWarehouseID: number; ToWarehouseID: number;
    items: { ItemID: number; SerialID?: number; Quantity: number; UnitCost?: number }[];
    userId: number;
  }) => {
    const db = getDb();
    const dateStr = new Date().toISOString().split('T')[0];
    const numResult = db.prepare("SELECT COUNT(*) as count FROM warehouse_transfers WHERE Date = ?").get(dateStr) as any;
    const transferNumber = `TR-${dateStr.replace(/-/g, '')}-${(numResult.count + 1).toString().padStart(4, '0')}`;

    const tx = db.transaction(() => {
      const result = db.prepare(`
        INSERT INTO warehouse_transfers (TransferNumber, Date, FromWarehouseID, ToWarehouseID, Status, UserID)
        VALUES (?, ?, ?, ?, 'completed', ?)
      `).run(transferNumber, dateStr, data.FromWarehouseID, data.ToWarehouseID, data.userId);

      const transferId = result.lastInsertRowid;

      for (const item of data.items) {
        db.prepare(`
          INSERT INTO warehouse_transfer_details (TransferID, ItemID, SerialID, Quantity, UnitCost)
          VALUES (?, ?, ?, ?, ?)
        `).run(transferId, item.ItemID, item.SerialID ?? null, item.Quantity, item.UnitCost ?? null);

        // Deduct from source warehouse
        const existingFrom = db.prepare('SELECT ID, Quantity FROM stock_quantities WHERE ItemID = ? AND WarehouseID = ?').get(item.ItemID, data.FromWarehouseID) as any;
        if (existingFrom) {
          db.prepare('UPDATE stock_quantities SET Quantity = Quantity - ? WHERE ID = ?').run(item.Quantity, existingFrom.ID);
        }

        // Add to destination warehouse
        const existingTo = db.prepare('SELECT ID, Quantity FROM stock_quantities WHERE ItemID = ? AND WarehouseID = ?').get(item.ItemID, data.ToWarehouseID) as any;
        if (existingTo) {
          db.prepare('UPDATE stock_quantities SET Quantity = Quantity + ? WHERE ID = ?').run(item.Quantity, existingTo.ID);
        } else {
          db.prepare('INSERT INTO stock_quantities (ItemID, WarehouseID, Quantity, CostPrice) VALUES (?, ?, ?, ?)').run(item.ItemID, data.ToWarehouseID, item.Quantity, item.UnitCost ?? 0);
        }

        // If serial item, move the serial
        if (item.SerialID) {
          db.prepare('UPDATE item_serials SET WarehouseID = ? WHERE SerialID = ?').run(data.ToWarehouseID, item.SerialID);
        }
      }
    });
    tx();
    return { success: true, transferNumber };
  });
}

import { ipcMain } from 'electron';
import { getDb } from '../database/connection';

export function registerSalesHandlers() {
  // ===== SALES =====
  ipcMain.handle('sales:list', async (_event, filters?: { fromDate?: string; toDate?: string; customerId?: number }) => {
    const db = getDb();
    let query = `
      SELECT s.*, c.Name as CustomerName, u.Username
      FROM sales s
      LEFT JOIN customers c ON s.CustomerID = c.CustomerID
      JOIN users u ON s.UserID = u.UserID
      WHERE 1=1
    `;
    const params: any[] = [];
    if (filters?.fromDate) { query += ' AND s.Date >= ?'; params.push(filters.fromDate); }
    if (filters?.toDate) { query += ' AND s.Date <= ?'; params.push(filters.toDate); }
    if (filters?.customerId) { query += ' AND s.CustomerID = ?'; params.push(filters.customerId); }
    query += ' ORDER BY s.Date DESC, s.SaleID DESC';
    return db.prepare(query).all(...params);
  });

  ipcMain.handle('sales:get', async (_event, saleId: number) => {
    const db = getDb();
    const sale = db.prepare(`
      SELECT s.*, c.Name as CustomerName, c.Phone as CustomerPhone, c.Email as CustomerEmail, c.Address as CustomerAddress, c.Balance as CustomerBalance, c.Status as CustomerStatus
      FROM sales s
      LEFT JOIN customers c ON s.CustomerID = c.CustomerID
      WHERE s.SaleID = ?
    `).get(saleId);
    const details = db.prepare(`
      SELECT sd.*, i.ItemName, i.ItemType
      FROM sale_details sd
      JOIN items i ON sd.ItemID = i.ItemID
      WHERE sd.SaleID = ?
    `).all(saleId);
    return { sale, details };
  });

  ipcMain.handle('sales:create', async (_event, data: {
    CustomerID?: number; CustomerName?: string; CustomerPhone?: string;
    items: { ItemID: number; SerialID?: number; IMEI?: string; Quantity: number; UnitPrice: number; UnitCost?: number; IsWarranty?: number; WarrantyMonths?: number }[];
    Discount: number; TaxRate: number; TaxAmount: number;
    PaymentMethod: string; PaidAmount: number;
    CashAccountID?: number; PaymentMethodID?: number;
    Notes?: string; userId: number; fiscalYearId: number;
  }) => {
    const db = getDb();

    // Check if customer is suspended
    if (data.CustomerID) {
      const customer = db.prepare('SELECT Status FROM customers WHERE CustomerID = ?').get(data.CustomerID) as any;
      if (customer?.Status === 'suspended') {
        return { success: false, message: 'العميل محظور - لا يمكن إتمام عملية البيع' };
      }
    }

    const subtotal = data.items.reduce((sum, item) => sum + (item.Quantity * item.UnitPrice), 0);
    const totalAmount = subtotal - data.Discount + data.TaxAmount;
    const remaining = totalAmount - data.PaidAmount;

    const dateStr = new Date().toISOString().split('T')[0];
    const numResult = db.prepare("SELECT COUNT(*) as count FROM sales WHERE Date = ?").get(dateStr) as any;
    const saleNumber = `SAL-${dateStr.replace(/-/g, '')}-${(numResult.count + 1).toString().padStart(4, '0')}`;

    const tx = db.transaction(() => {
      // Create sale
      const result = db.prepare(`
        INSERT INTO sales (SaleNumber, FiscalYearID, Date, CustomerID, CustomerName, CustomerPhone,
          Subtotal, Discount, TaxRate, TaxAmount, TotalAmount, PaidAmount, RemainingAmount,
          PaymentMethod, CashAccountID, PaymentMethodID, Status, UserID, Notes)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
      `).run(
        saleNumber, data.fiscalYearId, dateStr,
        data.CustomerID ?? null, data.CustomerName ?? null, data.CustomerPhone ?? null,
        subtotal, data.Discount, data.TaxRate, data.TaxAmount, totalAmount,
        data.PaidAmount, remaining, data.PaymentMethod,
        data.CashAccountID ?? null, data.PaymentMethodID ?? null,
        remaining > 0 ? (data.PaidAmount > 0 ? 'partial' : 'unpaid') : 'completed',
        data.userId, data.Notes ?? null
      );

      const saleId = result.lastInsertRowid;

      // Add sale details and update stock
      for (const item of data.items) {
        db.prepare(`
          INSERT INTO sale_details (SaleID, ItemID, SerialID, IMEI, Quantity, UnitPrice, UnitCost, Total, IsWarranty, WarrantyMonths)
          VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        `).run(
          saleId, item.ItemID, item.SerialID ?? null, item.IMEI ?? null,
          item.Quantity, item.UnitPrice, item.UnitCost ?? null,
          item.Quantity * item.UnitPrice,
          item.IsWarranty ?? 0, item.WarrantyMonths ?? null
        );

        // Mark serial as sold
        if (item.SerialID) {
          db.prepare("UPDATE item_serials SET Status = 'sold' WHERE SerialID = ?").run(item.SerialID);
        }

        // Deduct from stock (for non-serialized items)
        if (!item.SerialID) {
          const stock = db.prepare('SELECT ID, Quantity FROM stock_quantities WHERE ItemID = ?').get(item.ItemID) as any;
          if (stock) {
            db.prepare('UPDATE stock_quantities SET Quantity = Quantity - ? WHERE ID = ?').run(item.Quantity, stock.ID);
          }
        }
      }

      // Update customer balance
      if (data.CustomerID && remaining > 0) {
        db.prepare('UPDATE customers SET Balance = Balance + ? WHERE CustomerID = ?').run(remaining, data.CustomerID);
      }

      // Update cash account balance
      if (data.CashAccountID && data.PaidAmount > 0) {
        db.prepare('UPDATE cash_accounts SET Balance = Balance + ? WHERE CashAccountID = ?').run(data.PaidAmount, data.CashAccountID);
      }

      // Update payment method balance
      if (data.PaymentMethodID && data.PaidAmount > 0) {
        db.prepare('UPDATE payment_methods SET Balance = Balance + ? WHERE PaymentMethodID = ?').run(data.PaidAmount, data.PaymentMethodID);
      }
    });

    tx();
    return { success: true, saleNumber };
  });

  // ===== SALE RETURNS =====
  ipcMain.handle('saleReturns:list', async () => {
    const db = getDb();
    return db.prepare(`
      SELECT r.*, s.SaleNumber, s.CustomerName, c.Name as CustomerName
      FROM sale_returns r
      JOIN sales s ON r.SaleID = s.SaleID
      LEFT JOIN customers c ON s.CustomerID = c.CustomerID
      ORDER BY r.Date DESC
    `).all();
  });

  ipcMain.handle('saleReturns:create', async (_event, data: {
    SaleID: number; items: { ItemID: number; SerialID?: number; Quantity: number; UnitPrice: number }[];
    Reason?: string; CashAccountID?: number; userId: number;
  }) => {
    const db = getDb();
    const totalAmount = data.items.reduce((sum, item) => sum + (item.Quantity * item.UnitPrice), 0);
    const dateStr = new Date().toISOString().split('T')[0];
    const numResult = db.prepare("SELECT COUNT(*) as count FROM sale_returns WHERE Date = ?").get(dateStr) as any;
    const returnNumber = `SR-${dateStr.replace(/-/g, '')}-${(numResult.count + 1).toString().padStart(4, '0')}`;

    const tx = db.transaction(() => {
      const result = db.prepare(`
        INSERT INTO sale_returns (ReturnNumber, SaleID, Date, TotalAmount, Reason, UserID, CashAccountID)
        VALUES (?, ?, ?, ?, ?, ?, ?)
      `).run(returnNumber, data.SaleID, dateStr, totalAmount, data.Reason ?? null, data.userId, data.CashAccountID ?? null);

      const returnId = result.lastInsertRowid;

      for (const item of data.items) {
        db.prepare(`
          INSERT INTO sale_return_details (ReturnID, ItemID, SerialID, Quantity, UnitPrice, Total)
          VALUES (?, ?, ?, ?, ?, ?)
        `).run(returnId, item.ItemID, item.SerialID ?? null, item.Quantity, item.UnitPrice, item.Quantity * item.UnitPrice);

        // Restore serial status
        if (item.SerialID) {
          db.prepare("UPDATE item_serials SET Status = 'available' WHERE SerialID = ?").run(item.SerialID);
        }

        // Restore stock quantity
        if (!item.SerialID) {
          const stock = db.prepare('SELECT ID, Quantity FROM stock_quantities WHERE ItemID = ?').get(item.ItemID) as any;
          if (stock) {
            db.prepare('UPDATE stock_quantities SET Quantity = Quantity + ? WHERE ID = ?').run(item.Quantity, stock.ID);
          }
        }
      }

      // Refund from cash account
      if (data.CashAccountID) {
        db.prepare('UPDATE cash_accounts SET Balance = Balance - ? WHERE CashAccountID = ?').run(totalAmount, data.CashAccountID);
      }

      // Reduce customer balance
      const sale = db.prepare('SELECT CustomerID FROM sales WHERE SaleID = ?').get(data.SaleID) as any;
      if (sale?.CustomerID) {
        db.prepare('UPDATE customers SET Balance = Balance - ? WHERE CustomerID = ?').run(totalAmount, sale.CustomerID);
      }
    });

    tx();
    return { success: true, returnNumber };
  });
}

