export function registerPurchasesHandlers() {
  ipcMain.handle('purchases:list', async (_event, filters?: { fromDate?: string; toDate?: string; supplierId?: number }) => {
    const db = getDb();
    let query = `
      SELECT p.*, sup.Name as SupplierName, u.Username
      FROM purchases p
      JOIN suppliers sup ON p.SupplierID = sup.SupplierID
      JOIN users u ON p.UserID = u.UserID
      WHERE 1=1
    `;
    const params: any[] = [];
    if (filters?.fromDate) { query += ' AND p.Date >= ?'; params.push(filters.fromDate); }
    if (filters?.toDate) { query += ' AND p.Date <= ?'; params.push(filters.toDate); }
    if (filters?.supplierId) { query += ' AND p.SupplierID = ?'; params.push(filters.supplierId); }
    query += ' ORDER BY p.Date DESC, p.PurchaseID DESC';
    return db.prepare(query).all(...params);
  });

  ipcMain.handle('purchases:get', async (_event, purchaseId: number) => {
    const db = getDb();
    const purchase = db.prepare(`
      SELECT p.*, sup.Name as SupplierName, sup.Phone as SupplierPhone, sup.Balance as SupplierBalance, sup.Status as SupplierStatus
      FROM purchases p
      JOIN suppliers sup ON p.SupplierID = sup.SupplierID
      WHERE p.PurchaseID = ?
    `).get(purchaseId);
    const details = db.prepare(`
      SELECT pd.*, i.ItemName, i.ItemType
      FROM purchase_details pd
      JOIN items i ON pd.ItemID = i.ItemID
      WHERE pd.PurchaseID = ?
    `).all(purchaseId);
    return { purchase, details };
  });

  ipcMain.handle('purchases:create', async (_event, data: {
    SupplierID: number;
    items: { ItemID: number; IMEI?: string; Quantity: number; UnitCost: number; UnitPrice?: number; WarehouseID: number }[];
    Discount: number; TaxAmount: number;
    PaymentMethod: string; PaidAmount: number;
    CashAccountID?: number; PaymentMethodID?: number;
    Notes?: string; userId: number; fiscalYearId: number;
  }) => {
    const db = getDb();

    // Check if supplier is suspended
    const supplier = db.prepare('SELECT Status FROM suppliers WHERE SupplierID = ?').get(data.SupplierID) as any;
    if (supplier?.Status === 'suspended') {
      return { success: false, message: 'المورد موقوف - لا يمكن إتمام عملية الشراء' };
    }

    const subtotal = data.items.reduce((sum, item) => sum + (item.Quantity * item.UnitCost), 0);
    const totalAmount = subtotal - data.Discount + data.TaxAmount;
    const remaining = totalAmount - data.PaidAmount;

    const dateStr = new Date().toISOString().split('T')[0];
    const numResult = db.prepare("SELECT COUNT(*) as count FROM purchases WHERE Date = ?").get(dateStr) as any;
    const purchaseNumber = `PUR-${dateStr.replace(/-/g, '')}-${(numResult.count + 1).toString().padStart(4, '0')}`;

    const tx = db.transaction(() => {
      const result = db.prepare(`
        INSERT INTO purchases (PurchaseNumber, FiscalYearID, Date, SupplierID, Subtotal, Discount, TaxAmount,
          TotalAmount, PaidAmount, RemainingAmount, PaymentMethod, CashAccountID, PaymentMethodID, Status, UserID, Notes)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
      `).run(
        purchaseNumber, data.fiscalYearId, dateStr, data.SupplierID,
        subtotal, data.Discount, data.TaxAmount, totalAmount,
        data.PaidAmount, remaining, data.PaymentMethod,
        data.CashAccountID ?? null, data.PaymentMethodID ?? null,
        remaining > 0 ? (data.PaidAmount > 0 ? 'partial' : 'unpaid') : 'completed',
        data.userId, data.Notes ?? null
      );

      const purchaseId = result.lastInsertRowid;

      for (const item of data.items) {
        db.prepare(`
          INSERT INTO purchase_details (PurchaseID, ItemID, IMEI, Quantity, UnitCost, UnitPrice, Total, WarehouseID)
          VALUES (?, ?, ?, ?, ?, ?, ?, ?)
        `).run(purchaseId, item.ItemID, item.IMEI ?? null, item.Quantity, item.UnitCost, item.UnitPrice ?? null, item.Quantity * item.UnitCost, item.WarehouseID);

        // Add IMEI if provided
        if (item.IMEI) {
          const existing = db.prepare('SELECT SerialID FROM item_serials WHERE IMEI = ?').get(item.IMEI);
          if (!existing) {
            db.prepare(`
              INSERT INTO item_serials (ItemID, IMEI, Status, CostPrice, WarehouseID)
              VALUES (?, ?, 'available', ?, ?)
            `).run(item.ItemID, item.IMEI, item.UnitCost, item.WarehouseID);
          }
        }

        // Add to stock quantity
        const existing = db.prepare('SELECT ID, Quantity, CostPrice FROM stock_quantities WHERE ItemID = ? AND WarehouseID = ?').get(item.ItemID, item.WarehouseID) as any;
        if (existing) {
          const newQty = existing.Quantity + item.Quantity;
          const newCost = ((existing.CostPrice * existing.Quantity) + (item.UnitCost * item.Quantity)) / newQty;
          db.prepare('UPDATE stock_quantities SET Quantity = ?, CostPrice = ? WHERE ID = ?').run(newQty, newCost, existing.ID);
        } else {
          db.prepare('INSERT INTO stock_quantities (ItemID, WarehouseID, Quantity, CostPrice) VALUES (?, ?, ?, ?)').run(item.ItemID, item.WarehouseID, item.Quantity, item.UnitCost);
        }
      }

      // Update supplier balance
      if (remaining > 0) {
        db.prepare('UPDATE suppliers SET Balance = Balance + ? WHERE SupplierID = ?').run(remaining, data.SupplierID);
      }

      // Deduct from cash account
      if (data.CashAccountID && data.PaidAmount > 0) {
        db.prepare('UPDATE cash_accounts SET Balance = Balance - ? WHERE CashAccountID = ?').run(data.PaidAmount, data.CashAccountID);
      }
    });

    tx();
    return { success: true, purchaseNumber };
  });

  // ===== PURCHASE RETURNS =====
  ipcMain.handle('purchaseReturns:list', async () => {
    const db = getDb();
    return db.prepare(`
      SELECT r.*, p.PurchaseNumber, sup.Name as SupplierName
      FROM purchase_returns r
      JOIN purchases p ON r.PurchaseID = p.PurchaseID
      JOIN suppliers sup ON p.SupplierID = sup.SupplierID
      ORDER BY r.Date DESC
    `).all();
  });

  ipcMain.handle('purchaseReturns:create', async (_event, data: {
    PurchaseID: number; items: { ItemID: number; SerialID?: number; Quantity: number; UnitCost: number }[];
    Reason?: string; CashAccountID?: number; userId: number;
  }) => {
    const db = getDb();
    const totalAmount = data.items.reduce((sum, item) => sum + (item.Quantity * item.UnitCost), 0);
    const dateStr = new Date().toISOString().split('T')[0];
    const numResult = db.prepare("SELECT COUNT(*) as count FROM purchase_returns WHERE Date = ?").get(dateStr) as any;
    const returnNumber = `PR-${dateStr.replace(/-/g, '')}-${(numResult.count + 1).toString().padStart(4, '0')}`;

    const tx = db.transaction(() => {
      const result = db.prepare(`
        INSERT INTO purchase_returns (ReturnNumber, PurchaseID, Date, TotalAmount, Reason, UserID, CashAccountID)
        VALUES (?, ?, ?, ?, ?, ?, ?)
      `).run(returnNumber, data.PurchaseID, dateStr, totalAmount, data.Reason ?? null, data.userId, data.CashAccountID ?? null);

      const returnId = result.lastInsertRowid;

      for (const item of data.items) {
        db.prepare(`
          INSERT INTO purchase_return_details (ReturnID, ItemID, SerialID, Quantity, UnitCost, Total)
          VALUES (?, ?, ?, ?, ?, ?)
        `).run(returnId, item.ItemID, item.SerialID ?? null, item.Quantity, item.UnitCost, item.Quantity * item.UnitCost);

        // Mark serial as returned
        if (item.SerialID) {
          db.prepare("UPDATE item_serials SET Status = 'returned' WHERE SerialID = ?").run(item.SerialID);
        }

        // Deduct from stock
        const stock = db.prepare('SELECT ID, Quantity FROM stock_quantities WHERE ItemID = ?').get(item.ItemID) as any;
        if (stock) {
          db.prepare('UPDATE stock_quantities SET Quantity = Quantity - ? WHERE ID = ?').run(item.Quantity, stock.ID);
        }
      }

      // Reduce supplier balance
      const purchase = db.prepare('SELECT SupplierID FROM purchases WHERE PurchaseID = ?').get(data.PurchaseID) as any;
      if (purchase?.SupplierID) {
        db.prepare('UPDATE suppliers SET Balance = Balance - ? WHERE SupplierID = ?').run(totalAmount, purchase.SupplierID);
      }

      // Refund to cash account
      if (data.CashAccountID) {
        db.prepare('UPDATE cash_accounts SET Balance = Balance + ? WHERE CashAccountID = ?').run(totalAmount, data.CashAccountID);
      }
    });

    tx();
    return { success: true, returnNumber };
  });
}

import { ipcMain } from 'electron';
import { getDb } from '../database/connection';

export function registerMaintenanceHandlers() {
  // ===== TICKETS =====
  ipcMain.handle('maintenance:list', async (_event, filters?: { status?: string; technicianId?: number; customerId?: number }) => {
    const db = getDb();
    let query = `
      SELECT t.*, e.Name as TechnicianName, u.Username
      FROM maintenance_tickets t
      LEFT JOIN employees e ON t.TechnicianID = e.EmployeeID
      JOIN users u ON t.UserID = u.UserID
      WHERE 1=1
    `;
    const params: any[] = [];
    if (filters?.status && filters.status !== 'all') { query += ' AND t.Status = ?'; params.push(filters.status); }
    if (filters?.technicianId) { query += ' AND t.TechnicianID = ?'; params.push(filters.technicianId); }
    if (filters?.customerId) { query += ' AND t.CustomerID = ?'; params.push(filters.customerId); }
    query += ' ORDER BY t.Date DESC, t.TicketID DESC';
    return db.prepare(query).all(...params);
  });

  ipcMain.handle('maintenance:get', async (_event, ticketId: number) => {
    const db = getDb();
    const ticket = db.prepare(`
      SELECT t.*, e.Name as TechnicianName, c.Name as CustomerName, c.Phone as CustomerPhone, c.Balance as CustomerBalance, c.Status as CustomerStatus
      FROM maintenance_tickets t
      LEFT JOIN employees e ON t.TechnicianID = e.EmployeeID
      LEFT JOIN customers c ON t.CustomerID = c.CustomerID
      WHERE t.TicketID = ?
    `).get(ticketId);
    const parts = db.prepare(`
      SELECT mp.*, i.ItemName
      FROM maintenance_parts mp
      JOIN items i ON mp.ItemID = i.ItemID
      WHERE mp.TicketID = ?
    `).all(ticketId);
    const log = db.prepare(`
      SELECT l.*, u.Username
      FROM maintenance_status_log l
      JOIN users u ON l.UserID = u.UserID
      WHERE l.TicketID = ?
      ORDER BY l.Date ASC
    `).all(ticketId);
    return { ticket, parts, log };
  });

  // Get open tickets for a customer
  ipcMain.handle('maintenance:openTickets', async (_event, customerId?: number, customerName?: string) => {
    const db = getDb();
    let query = `
      SELECT t.*, e.Name as TechnicianName
      FROM maintenance_tickets t
      LEFT JOIN employees e ON t.TechnicianID = e.EmployeeID
      WHERE t.Status NOT IN ('delivered', 'cancelled')
    `;
    const params: any[] = [];
    if (customerId) { query += ' AND t.CustomerID = ?'; params.push(customerId); }
    else if (customerName) { query += ' AND t.CustomerName = ?'; params.push(customerName); }
    query += ' ORDER BY t.Date DESC';
    return db.prepare(query).all(...params);
  });

  // Receive device
  ipcMain.handle('maintenance:receive', async (_event, data: {
    CustomerID?: number; CustomerName: string; CustomerPhone: string;
    DeviceModel: string; DeviceIMEI?: string; ProblemDesc: string;
    Accessories?: string; DevicePassword?: string;
    AgreedDeliveryDate?: string; AgreedCost?: number;
    TechnicianID?: number; userId: number; fiscalYearId: number;
  }) => {
    const db = getDb();
    const dateStr = new Date().toISOString().split('T')[0];
    const numResult = db.prepare("SELECT COUNT(*) as count FROM maintenance_tickets WHERE Date = ?").get(dateStr) as any;
    const ticketNumber = `MNT-${dateStr.replace(/-/g, '')}-${(numResult.count + 1).toString().padStart(4, '0')}`;

    const result = db.prepare(`
      INSERT INTO maintenance_tickets (TicketNumber, FiscalYearID, Date, CustomerID, CustomerName, CustomerPhone,
        DeviceModel, DeviceIMEI, ProblemDesc, Accessories, DevicePassword,
        AgreedDeliveryDate, AgreedCost, TechnicianID, Status, UserID)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'received', ?)
    `).run(
      ticketNumber, data.fiscalYearId, dateStr,
      data.CustomerID ?? null, data.CustomerName, data.CustomerPhone,
      data.DeviceModel, data.DeviceIMEI ?? null, data.ProblemDesc,
      data.Accessories ?? null, data.DevicePassword ?? null,
      data.AgreedDeliveryDate ?? null, data.AgreedCost ?? null,
      data.TechnicianID ?? null, data.userId
    );

    // Add status log
    const ticketId = result.lastInsertRowid;
    db.prepare(`
      INSERT INTO maintenance_status_log (TicketID, Status, Notes, UserID)
      VALUES (?, 'received', 'تم استلام الجهاز', ?)
    `).run(ticketId, data.userId);

    return { success: true, ticketId, ticketNumber };
  });

  // Update ticket status
  ipcMain.handle('maintenance:updateStatus', async (_event, ticketId: number, status: string, notes: string, userId: number) => {
    const db = getDb();
    db.transaction(() => {
      db.prepare('UPDATE maintenance_tickets SET Status = ? WHERE TicketID = ?').run(status, ticketId);
      db.prepare(`
        INSERT INTO maintenance_status_log (TicketID, Status, Notes, UserID)
        VALUES (?, ?, ?, ?)
      `).run(ticketId, status, notes, userId);
    })();
    return { success: true };
  });

  // Issue parts to maintenance ticket
  ipcMain.handle('maintenance:issuePart', async (_event, data: {
    TicketID: number; ItemID: number; Quantity: number;
    UnitCost?: number; WarehouseID: number; userId: number;
  }) => {
    const db = getDb();
    // Get cost from stock if not provided
    let unitCost = data.UnitCost;
    if (!unitCost) {
      const stock = db.prepare('SELECT CostPrice FROM stock_quantities WHERE ItemID = ? AND WarehouseID = ?').get(data.ItemID, data.WarehouseID) as any;
      unitCost = stock?.CostPrice || 0;
    }
    const totalCost = unitCost * data.Quantity;

    db.transaction(() => {
      db.prepare(`
        INSERT INTO maintenance_parts (TicketID, ItemID, Quantity, UnitCost, TotalCost, WarehouseID, IssuedByUserID)
        VALUES (?, ?, ?, ?, ?, ?, ?)
      `).run(data.TicketID, data.ItemID, data.Quantity, unitCost, totalCost, data.WarehouseID, data.userId);

      // Deduct from stock
      const stock = db.prepare('SELECT ID, Quantity FROM stock_quantities WHERE ItemID = ? AND WarehouseID = ?').get(data.ItemID, data.WarehouseID) as any;
      if (stock) {
        db.prepare('UPDATE stock_quantities SET Quantity = Quantity - ? WHERE ID = ?').run(data.Quantity, stock.ID);
      }

      // Update ticket costs
      db.prepare('UPDATE maintenance_tickets SET PartsCost = PartsCost + ?, TotalCost = TotalCost + ? WHERE TicketID = ?')
        .run(totalCost, totalCost, data.TicketID);
    })();

    return { success: true, unitCost, totalCost };
  });

  // Deliver device (create invoice)
  ipcMain.handle('maintenance:deliver', async (_event, data: {
    TicketID: number; CustomerID?: number; CustomerName: string;
    LaborCost: number; AdditionalCosts: { Description: string; Amount: number }[];
    PaymentMethod: string; PaidAmount: number;
    CashAccountID?: number; PaymentMethodID?: number;
    userId: number; fiscalYearId: number;
  }) => {
    const db = getDb();
    const ticket = db.prepare('SELECT PartsCost FROM maintenance_tickets WHERE TicketID = ?').get(data.TicketID) as any;
    const partsCost = ticket?.PartsCost || 0;
    const additionalTotal = data.AdditionalCosts.reduce((sum, a) => sum + a.Amount, 0);
    const totalCost = partsCost + data.LaborCost + additionalTotal;
    const remaining = totalCost - data.PaidAmount;

    const dateStr = new Date().toISOString().split('T')[0];
    const numResult = db.prepare("SELECT COUNT(*) as count FROM maintenance_deliveries WHERE Date = ?").get(dateStr) as any;
    const deliveryNumber = `DLV-${dateStr.replace(/-/g, '')}-${(numResult.count + 1).toString().padStart(4, '0')}`;

    const tx = db.transaction(() => {
      const result = db.prepare(`
        INSERT INTO maintenance_deliveries (DeliveryNumber, TicketID, Date, CustomerID, CustomerName,
          PartsCost, LaborCost, AdditionalCosts, TotalCost, PaidAmount, RemainingAmount,
          PaymentMethod, CashAccountID, PaymentMethodID, UserID)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
      `).run(
        deliveryNumber, data.TicketID, dateStr, data.CustomerID ?? null, data.CustomerName,
        partsCost, data.LaborCost, additionalTotal, totalCost, data.PaidAmount, remaining,
        data.PaymentMethod, data.CashAccountID ?? null, data.PaymentMethodID ?? null, data.userId
      );

      const deliveryId = result.lastInsertRowid;

      // Add additional costs
      for (const ac of data.AdditionalCosts) {
        db.prepare('INSERT INTO maintenance_additional_costs (DeliveryID, Description, Amount) VALUES (?, ?, ?)').run(deliveryId, ac.Description, ac.Amount);
      }

      // Update ticket status
      db.prepare("UPDATE maintenance_tickets SET Status = 'delivered', TotalCost = ? WHERE TicketID = ?").run(totalCost, data.TicketID);
      db.prepare(`
        INSERT INTO maintenance_status_log (TicketID, Status, Notes, UserID)
        VALUES (?, 'delivered', ?, ?)
      `).run(data.TicketID, `تم تسليم الجهاز - التكلفة: ${totalCost}`, data.userId);

      // Update customer balance
      if (data.CustomerID && remaining > 0) {
        db.prepare('UPDATE customers SET Balance = Balance + ? WHERE CustomerID = ?').run(remaining, data.CustomerID);
      }

      // Update cash account
      if (data.CashAccountID && data.PaidAmount > 0) {
        db.prepare('UPDATE cash_accounts SET Balance = Balance + ? WHERE CashAccountID = ?').run(data.PaidAmount, data.CashAccountID);
      }

      // Add technician commission if applicable
      const ticket2 = db.prepare('SELECT TechnicianID FROM maintenance_tickets WHERE TicketID = ?').get(data.TicketID) as any;
      if (ticket2?.TechnicianID) {
        db.prepare(`
          INSERT INTO commissions (EmployeeID, CommissionType, Amount, Date, ReferenceType, ReferenceID, IsPaid, PaidAmount, FiscalYearID, UserID)
          VALUES (?, 'maintenance', ?, ?, 'maintenance_delivery', ?, 0, 0, ?, ?)
        `).run(ticket2.TechnicianID, data.LaborCost, dateStr, deliveryId, data.fiscalYearId, data.userId);
      }
    });

    tx();
    return { success: true, deliveryNumber, totalCost, remaining };
  });

  // Maintenance return (cancel delivery, restore parts)
  ipcMain.handle('maintenance:return', async (_event, data: {
    DeliveryID: number; TicketID: number; Reason: string;
    TotalRefund: number; CashAccountID?: number; PartsRestored: number; userId: number; fiscalYearId: number;
  }) => {
    const db = getDb();
    const dateStr = new Date().toISOString().split('T')[0];
    const numResult = db.prepare("SELECT COUNT(*) as count FROM maintenance_returns WHERE Date = ?").get(dateStr) as any;
    const returnNumber = `MRT-${dateStr.replace(/-/g, '')}-${(numResult.count + 1).toString().padStart(4, '0')}`;

    const tx = db.transaction(() => {
      const result = db.prepare(`
        INSERT INTO maintenance_returns (ReturnNumber, DeliveryID, TicketID, Date, Reason, TotalRefund, CashAccountID, PartsRestored, UserID)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
      `).run(returnNumber, data.DeliveryID, data.TicketID, dateStr, data.Reason, data.TotalRefund, data.CashAccountID ?? null, data.PartsRestored, data.userId);

      // Restore parts to stock if not damaged
      if (data.PartsRestored === 1) {
        const parts = db.prepare('SELECT * FROM maintenance_parts WHERE TicketID = ?').all(data.TicketID) as any[];
        for (const part of parts) {
          const stock = db.prepare('SELECT ID, Quantity FROM stock_quantities WHERE ItemID = ? AND WarehouseID = ?').get(part.ItemID, part.WarehouseID) as any;
          if (stock) {
            db.prepare('UPDATE stock_quantities SET Quantity = Quantity + ? WHERE ID = ?').run(part.Quantity, stock.ID);
          } else {
            db.prepare('INSERT INTO stock_quantities (ItemID, WarehouseID, Quantity, CostPrice) VALUES (?, ?, ?, ?)').run(part.ItemID, part.WarehouseID, part.Quantity, part.UnitCost);
          }
        }
      }

      // Update ticket status back
      db.prepare("UPDATE maintenance_tickets SET Status = 'returned' WHERE TicketID = ?").run(data.TicketID);

      // Refund from cash account
      if (data.CashAccountID) {
        db.prepare('UPDATE cash_accounts SET Balance = Balance - ? WHERE CashAccountID = ?').run(data.TotalRefund, data.CashAccountID);
      }

      // Reduce customer balance
      const delivery = db.prepare('SELECT CustomerID FROM maintenance_deliveries WHERE DeliveryID = ?').get(data.DeliveryID) as any;
      if (delivery?.CustomerID) {
        db.prepare('UPDATE customers SET Balance = Balance - ? WHERE CustomerID = ?').run(data.TotalRefund, delivery.CustomerID);
      }

      // Cancel technician commission
      db.prepare("UPDATE commissions SET IsPaid = 1, PaidAmount = 0 WHERE ReferenceType = 'maintenance_delivery' AND ReferenceID = ?").run(data.DeliveryID);
    });

    tx();
    return { success: true, returnNumber };
  });
}

import { ipcMain } from 'electron';
import { getDb } from '../database/connection';

export function registerVouchersHandlers() {
  ipcMain.handle('vouchers:list', async (_event, filters?: { type?: string; fromDate?: string; toDate?: string }) => {
    const db = getDb();
    let query = `
      SELECT v.*, u.Username
      FROM vouchers v
      JOIN users u ON v.UserID = u.UserID
      WHERE 1=1
    `;
    const params: any[] = [];
    if (filters?.type && filters.type !== 'all') { query += ' AND v.VoucherType = ?'; params.push(filters.type); }
    if (filters?.fromDate) { query += ' AND v.Date >= ?'; params.push(filters.fromDate); }
    if (filters?.toDate) { query += ' AND v.Date <= ?'; params.push(filters.toDate); }
    query += ' ORDER BY v.Date DESC, v.VoucherID DESC';
    return db.prepare(query).all(...params);
  });

  ipcMain.handle('vouchers:create', async (_event, data: {
    VoucherType: string; Amount: number;
    PartyType?: string; PartyID?: number; PartyName?: string;
    Description: string; CashAccountID: number; PaymentMethodID?: number;
    ReferenceType?: string; ReferenceID?: number;
    userId: number; fiscalYearId: number;
  }) => {
    const db = getDb();
    const dateStr = new Date().toISOString().split('T')[0];
    const prefix = data.VoucherType === 'receipt' ? 'RCV' : 'PAY';
    const numResult = db.prepare("SELECT COUNT(*) as count FROM vouchers WHERE Date = ? AND VoucherType = ?").get(dateStr, data.VoucherType) as any;
    const voucherNumber = `${prefix}-${dateStr.replace(/-/g, '')}-${(numResult.count + 1).toString().padStart(4, '0')}`;

    const tx = db.transaction(() => {
      const result = db.prepare(`
        INSERT INTO vouchers (VoucherNumber, VoucherType, FiscalYearID, Date, Amount,
          PartyType, PartyID, PartyName, Description, CashAccountID, PaymentMethodID,
          ReferenceType, ReferenceID, UserID)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
      `).run(
        voucherNumber, data.VoucherType, data.fiscalYearId, dateStr, data.Amount,
        data.PartyType ?? null, data.PartyID ?? null, data.PartyName ?? null,
        data.Description, data.CashAccountID, data.PaymentMethodID ?? null,
        data.ReferenceType ?? null, data.ReferenceID ?? null, data.userId
      );

      // Update cash account balance
      if (data.VoucherType === 'receipt') {
        db.prepare('UPDATE cash_accounts SET Balance = Balance + ? WHERE CashAccountID = ?').run(data.Amount, data.CashAccountID);
        if (data.PaymentMethodID) {
          db.prepare('UPDATE payment_methods SET Balance = Balance + ? WHERE PaymentMethodID = ?').run(data.Amount, data.PaymentMethodID);
        }
      } else {
        db.prepare('UPDATE cash_accounts SET Balance = Balance - ? WHERE CashAccountID = ?').run(data.Amount, data.CashAccountID);
        if (data.PaymentMethodID) {
          db.prepare('UPDATE payment_methods SET Balance = Balance - ? WHERE PaymentMethodID = ?').run(data.Amount, data.PaymentMethodID);
        }
      }

      // Update party balance
      if (data.PartyType === 'customer' && data.PartyID) {
        if (data.VoucherType === 'receipt') {
          db.prepare('UPDATE customers SET Balance = Balance - ? WHERE CustomerID = ?').run(data.Amount, data.PartyID);
        } else {
          db.prepare('UPDATE customers SET Balance = Balance + ? WHERE CustomerID = ?').run(data.Amount, data.PartyID);
        }
      } else if (data.PartyType === 'supplier' && data.PartyID) {
        if (data.VoucherType === 'payment') {
          db.prepare('UPDATE suppliers SET Balance = Balance - ? WHERE SupplierID = ?').run(data.Amount, data.PartyID);
        } else {
          db.prepare('UPDATE suppliers SET Balance = Balance + ? WHERE SupplierID = ?').run(data.Amount, data.PartyID);
        }
      } else if (data.PartyType === 'employee' && data.PartyID) {
        if (data.VoucherType === 'payment') {
          db.prepare('UPDATE employees SET Balance = Balance - ? WHERE EmployeeID = ?').run(data.Amount, data.PartyID);
        } else {
          db.prepare('UPDATE employees SET Balance = Balance + ? WHERE EmployeeID = ?').run(data.Amount, data.PartyID);
        }
      }
    });

    tx();
    return { success: true, voucherNumber };
  });
}

import { ipcMain } from 'electron';
import { getDb } from '../database/connection';

export function registerPayrollHandlers() {
  // ===== SALARIES =====
  ipcMain.handle('salaries:list', async (_event, filters?: { employeeId?: number; month?: string }) => {
    const db = getDb();
    let query = `
      SELECT s.*, e.Name as EmployeeName, u.Username
      FROM salaries s
      JOIN employees e ON s.EmployeeID = e.EmployeeID
      JOIN users u ON s.UserID = u.UserID
      WHERE 1=1
    `;
    const params: any[] = [];
    if (filters?.employeeId) { query += ' AND s.EmployeeID = ?'; params.push(filters.employeeId); }
    if (filters?.month) { query += ' AND s.Month = ?'; params.push(filters.month); }
    query += ' ORDER BY s.Month DESC';
    return db.prepare(query).all(...params);
  });

  ipcMain.handle('salaries:create', async (_event, data: {
    EmployeeID: number; Month: string;
    CashAccountID?: number; PaidAmount: number;
    userId: number; fiscalYearId: number;
  }) => {
    const db = getDb();
    const emp = db.prepare('SELECT * FROM employees WHERE EmployeeID = ?').get(data.EmployeeID) as any;
    if (!emp) return { success: false, message: 'الموظف غير موجود' };

    // Get unpaid commissions
    const commissions = db.prepare("SELECT * FROM commissions WHERE EmployeeID = ? AND IsPaid = 0").all(data.EmployeeID) as any[];
    const commissionsTotal = commissions.reduce((sum, c) => sum + c.Amount, 0);

    // Get unpaid deductions
    const deductions = db.prepare("SELECT * FROM employee_deductions WHERE EmployeeID = ? AND IsDeducted = 0").all(data.EmployeeID) as any[];
    const deductionsTotal = deductions.reduce((sum, d) => sum + d.Amount, 0);

    // Get unpaid advances
    const advances = db.prepare("SELECT * FROM employee_advances WHERE EmployeeID = ? AND IsDeducted = 0").all(data.EmployeeID) as any[];
    const advancesTotal = advances.reduce((sum, a) => sum + a.Amount, 0);

    const netSalary = emp.BaseSalary + emp.Allowances + commissionsTotal - deductionsTotal - advancesTotal;
    const paidAmount = data.PaidAmount > 0 ? Math.min(data.PaidAmount, netSalary) : netSalary;
    const status = paidAmount >= netSalary ? 'paid' : 'partial';
    const paymentDate = new Date().toISOString().split('T')[0];

    const tx = db.transaction(() => {
      const result = db.prepare(`
        INSERT INTO salaries (EmployeeID, Month, FiscalYearID, BaseSalary, Allowances,
          CommissionsTotal, DeductionsTotal, AdvancesTotal, NetSalary, PaidAmount, Status, CashAccountID, PaymentDate, UserID)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
      `).run(
        data.EmployeeID, data.Month, data.fiscalYearId,
        emp.BaseSalary, emp.Allowances,
        commissionsTotal, deductionsTotal, advancesTotal,
        netSalary, paidAmount, status, data.CashAccountID ?? null, paymentDate, data.userId
      );

      const salaryId = result.lastInsertRowid;

      // Mark commissions as paid
      const commissionPaidPerItem = commissions.length > 0 ? (paidAmount / netSalary) * commissionsTotal : 0;
      for (const c of commissions) {
        const paidPortion = (c.Amount / commissionsTotal) * commissionPaidPerItem;
        db.prepare('UPDATE commissions SET IsPaid = 1, PaidInSalaryID = ?, PaidAmount = ? WHERE CommissionID = ?')
          .run(salaryId, paidPortion, c.CommissionID);
      }

      // Mark deductions as deducted
      for (const d of deductions) {
        db.prepare('UPDATE employee_deductions SET IsDeducted = 1, DeductedFromSalaryID = ? WHERE DeductionID = ?').run(salaryId, d.DeductionID);
      }

      // Mark advances as deducted
      for (const a of advances) {
        db.prepare('UPDATE employee_advances SET IsDeducted = 1, DeductedFromSalaryID = ? WHERE AdvanceID = ?').run(salaryId, a.AdvanceID);
      }

      // Update employee balance
      db.prepare('UPDATE employees SET Balance = Balance + ? WHERE EmployeeID = ?').run(netSalary - paidAmount, data.EmployeeID);

      // Deduct from cash account
      if (data.CashAccountID) {
        db.prepare('UPDATE cash_accounts SET Balance = Balance - ? WHERE CashAccountID = ?').run(paidAmount, data.CashAccountID);
      }
    });

    tx();
    return { success: true, netSalary, paidAmount, status };
  });

  // ===== ADVANCES =====
  ipcMain.handle('advances:list', async (_event, employeeId?: number) => {
    const db = getDb();
    let query = `
      SELECT a.*, e.Name as EmployeeName
      FROM employee_advances a
      JOIN employees e ON a.EmployeeID = e.EmployeeID
      WHERE 1=1
    `;
    const params: any[] = [];
    if (employeeId) { query += ' AND a.EmployeeID = ?'; params.push(employeeId); }
    query += ' ORDER BY a.Date DESC';
    return db.prepare(query).all(...params);
  });

  ipcMain.handle('advances:create', async (_event, data: {
    EmployeeID: number; Amount: number; Reason?: string;
    CashAccountID: number; userId: number; fiscalYearId: number;
  }) => {
    const db = getDb();
    const dateStr = new Date().toISOString().split('T')[0];

    db.transaction(() => {
      db.prepare(`
        INSERT INTO employee_advances (EmployeeID, Amount, Date, Reason, CashAccountID, IsDeducted, FiscalYearID, UserID)
        VALUES (?, ?, ?, ?, ?, 0, ?, ?)
      `).run(data.EmployeeID, data.Amount, dateStr, data.Reason ?? null, data.CashAccountID, data.fiscalYearId, data.userId);

      db.prepare('UPDATE employees SET Balance = Balance + ? WHERE EmployeeID = ?').run(data.Amount, data.EmployeeID);
      db.prepare('UPDATE cash_accounts SET Balance = Balance - ? WHERE CashAccountID = ?').run(data.Amount, data.CashAccountID);
    })();

    return { success: true };
  });

  // ===== DEDUCTIONS =====
  ipcMain.handle('deductions:list', async (_event, employeeId?: number) => {
    const db = getDb();
    let query = `
      SELECT d.*, e.Name as EmployeeName, i.ItemName as DamagedItemName
      FROM employee_deductions d
      JOIN employees e ON d.EmployeeID = e.EmployeeID
      LEFT JOIN items i ON d.DamagedItemID = i.ItemID
      WHERE 1=1
    `;
    const params: any[] = [];
    if (employeeId) { query += ' AND d.EmployeeID = ?'; params.push(employeeId); }
    query += ' ORDER BY d.Date DESC';
    return db.prepare(query).all(...params);
  });

  ipcMain.handle('deductions:create', async (_event, data: {
    EmployeeID: number; Amount: number; Reason: string;
    DamagedItemID?: number; DamageCostType?: string;
    Notes?: string; userId: number; fiscalYearId: number;
  }) => {
    const db = getDb();
    const dateStr = new Date().toISOString().split('T')[0];

    // Calculate amount if damaged item
    let amount = data.Amount;
    if (data.Reason === 'damage' && data.DamagedItemID) {
      if (data.DamageCostType === 'cost') {
        const item = db.prepare('SELECT CostPrice FROM items WHERE ItemID = ?').get(data.DamagedItemID) as any;
        amount = item?.CostPrice || amount;
      } else if (data.DamageCostType === 'sale') {
        const item = db.prepare('SELECT SalePrice FROM items WHERE ItemID = ?').get(data.DamagedItemID) as any;
        amount = item?.SalePrice || amount;
      }
    }

    db.prepare(`
      INSERT INTO employee_deductions (EmployeeID, Amount, Date, Reason, DamagedItemID, DamageCostType, IsDeducted, FiscalYearID, UserID, Notes)
      VALUES (?, ?, ?, ?, ?, ?, 0, ?, ?, ?)
    `).run(data.EmployeeID, amount, dateStr, data.Reason, data.DamagedItemID ?? null, data.DamageCostType ?? null, data.fiscalYearId, data.userId, data.Notes ?? null);

    return { success: true, amount };
  });
}

import { ipcMain } from 'electron';
import { getDb } from '../database/connection';

export function registerRentHandlers() {
  ipcMain.handle('rents:list', async () => {
    const db = getDb();
    return db.prepare('SELECT * FROM rents ORDER BY StartDate DESC').all();
  });

  ipcMain.handle('rents:create', async (_event, data: {
    RentName: string; RentType: string; Amount: number; Period: string;
    StartDate: string; PartyName?: string; PartyPhone?: string; Notes?: string;
  }) => {
    const db = getDb();
    const result = db.prepare(`
      INSERT INTO rents (RentName, RentType, Amount, Period, StartDate, IsActive, PartyName, PartyPhone, Notes)
      VALUES (?, ?, ?, ?, ?, 1, ?, ?, ?)
    `).run(data.RentName, data.RentType, data.Amount, data.Period, data.StartDate, data.PartyName ?? null, data.PartyPhone ?? null, data.Notes ?? null);
    return { success: true, id: result.lastInsertRowid };
  });

  ipcMain.handle('rents:update', async (_event, id: number, data: any) => {
    const db = getDb();
    db.prepare(`
      UPDATE rents SET RentName = ?, RentType = ?, Amount = ?, Period = ?, IsActive = ?, PartyName = ?, PartyPhone = ?, Notes = ?
      WHERE RentID = ?
    `).run(data.RentName, data.RentType, data.Amount, data.Period, data.IsActive, data.PartyName, data.PartyPhone, data.Notes, id);
    return { success: true };
  });

  ipcMain.handle('rents:delete', async (_event, id: number) => {
    const db = getDb();
    db.prepare('UPDATE rents SET IsActive = 0 WHERE RentID = ?').run(id);
    return { success: true };
  });

  // Rent payments
  ipcMain.handle('rentPayments:list', async (_event, rentId?: number) => {
    const db = getDb();
    let query = `
      SELECT rp.*, r.RentName, r.RentType, r.Period
      FROM rent_payments rp
      JOIN rents r ON rp.RentID = r.RentID
      WHERE 1=1
    `;
    const params: any[] = [];
    if (rentId) { query += ' AND rp.RentID = ?'; params.push(rentId); }
    query += ' ORDER BY rp.DueDate DESC';
    return db.prepare(query).all(...params);
  });

  ipcMain.handle('rentPayments:pay', async (_event, data: {
    RentPaymentID: number; CashAccountID: number;
    userId: number; fiscalYearId: number;
  }) => {
    const db = getDb();
    const payment = db.prepare('SELECT * FROM rent_payments WHERE RentPaymentID = ?').get(data.RentPaymentID) as any;
    if (!payment) return { success: false, message: 'الدفعة غير موجودة' };

    const dateStr = new Date().toISOString().split('T')[0];

    db.transaction(() => {
      db.prepare('UPDATE rent_payments SET Status = ?, PaidDate = ?, CashAccountID = ? WHERE RentPaymentID = ?')
        .run('paid', dateStr, data.CashAccountID, data.RentPaymentID);

      // Update cash account
      const rent = db.prepare('SELECT RentType FROM rents WHERE RentID = ?').get(payment.RentID) as any;
      if (rent?.RentType === 'expense') {
        db.prepare('UPDATE cash_accounts SET Balance = Balance - ? WHERE CashAccountID = ?').run(payment.Amount, data.CashAccountID);
      } else {
        db.prepare('UPDATE cash_accounts SET Balance = Balance + ? WHERE CashAccountID = ?').run(payment.Amount, data.CashAccountID);
      }
    })();

    return { success: true };
  });

  // Generate rent payments for a period
  ipcMain.handle('rents:generatePayments', async (_event, rentId: number, months: number, userId: number, fiscalYearId: number) => {
    const db = getDb();
    const rent = db.prepare('SELECT * FROM rents WHERE RentID = ?').get(rentId) as any;
    if (!rent) return { success: false, message: 'الإيجار غير موجود' };

    const startDate = new Date(rent.StartDate);
    const tx = db.transaction(() => {
      for (let i = 0; i < months; i++) {
        const dueDate = new Date(startDate);
        if (rent.Period === 'monthly') dueDate.setMonth(dueDate.getMonth() + i);
        else dueDate.setFullYear(dueDate.getFullYear() + i);

        const periodLabel = rent.Period === 'monthly'
          ? `${dueDate.toLocaleString('ar-EG', { month: 'long', year: 'numeric' })}`
          : `${dueDate.getFullYear()}`;

        // Check if payment already exists
        const existing = db.prepare('SELECT RentPaymentID FROM rent_payments WHERE RentID = ? AND PeriodLabel = ?').get(rentId, periodLabel);
        if (!existing) {
          db.prepare(`
            INSERT INTO rent_payments (RentID, PeriodLabel, Amount, DueDate, Status, FiscalYearID, UserID)
            VALUES (?, ?, ?, ?, 'pending', ?, ?)
          `).run(rentId, periodLabel, rent.Amount, dueDate.toISOString().split('T')[0], fiscalYearId, userId);
        }
      }
    });
    tx();
    return { success: true };
  });
}

import { ipcMain } from 'electron';
import { getDb } from '../database/connection';

export function registerFiscalYearHandlers() {
  ipcMain.handle('fiscalYear:list', async () => {
    const db = getDb();
    return db.prepare('SELECT * FROM fiscal_years ORDER BY StartDate DESC').all();
  });

  ipcMain.handle('fiscalYear:getActive', async () => {
    const db = getDb();
    return db.prepare("SELECT * FROM fiscal_years WHERE Status = 'open' ORDER BY StartDate DESC LIMIT 1").get();
  });

  ipcMain.handle('fiscalYear:create', async (_event, data: { YearName: string; StartDate: string; EndDate: string }) => {
    const db = getDb();
    const result = db.prepare('INSERT INTO fiscal_years (YearName, StartDate, EndDate, Status) VALUES (?, ?, ?, ?)').run(data.YearName, data.StartDate, data.EndDate, 'open');
    return { success: true, id: result.lastInsertRowid };
  });

  ipcMain.handle('fiscalYear:close', async (_event, fiscalYearId: number, userId: number) => {
    const db = getDb();
    const fy = db.prepare('SELECT * FROM fiscal_years WHERE FiscalYearID = ?').get(fiscalYearId) as any;
    if (!fy) return { success: false, message: 'السنة المالية غير موجودة' };
    if (fy.Status === 'closed') return { success: false, message: 'السنة المالية مغلقة بالفعل' };

    const dateStr = new Date().toISOString().split('T')[0];

    db.transaction(() => {
      // Close current year
      db.prepare('UPDATE fiscal_years SET Status = ?, ClosedAt = ?, ClosedByUserID = ? WHERE FiscalYearID = ?')
        .run('closed', dateStr, userId, fiscalYearId);

      // Create new year starting the day after
      const startDate = new Date(fy.EndDate);
      startDate.setDate(startDate.getDate() + 1);
      const endDate = new Date(startDate);
      endDate.setFullYear(endDate.getFullYear() + 1);

      const newYearName = `السنة المالية ${endDate.getFullYear()}`;
      db.prepare('INSERT INTO fiscal_years (YearName, StartDate, EndDate, Status) VALUES (?, ?, ?, ?)').run(
        newYearName, startDate.toISOString().split('T')[0], endDate.toISOString().split('T')[0], 'open'
      );
    })();

    return { success: true };
  });
}

