import { useState, useEffect } from 'react';
import { Plus, Search, Edit, Trash2, Package, ArrowRightLeft, Smartphone } from 'lucide-react';
import { Button } from '../../components/ui/Button';
import { Input, Select } from '../../components/ui/Input';
import { Modal } from '../../components/ui/Modal';
import { Badge } from '../../components/ui/Badge';
import { DataTable } from '../../components/shared/DataTable';
import { useToastStore } from '../../components/ui/Toast';

export function InventoryPage() {
  const { showToast } = useToastStore();
  const [tab, setTab] = useState<'items' | 'warehouses' | 'transfers'>('items');
  const [items, setItems] = useState<any[]>([]);
  const [warehouses, setWarehouses] = useState<any[]>([]);
  const [categories, setCategories] = useState<any[]>([]);
  const [search, setSearch] = useState('');
  const [typeFilter, setTypeFilter] = useState('all');
  const [showItemModal, setShowItemModal] = useState(false);
  const [showWhModal, setShowWhModal] = useState(false);
  const [showTransferModal, setShowTransferModal] = useState(false);
  const [showSerialsModal, setShowSerialsModal] = useState(false);
  const [editingItem, setEditingItem] = useState<any>(null);
  const [editingWh, setEditingWh] = useState<any>(null);
  const [serialsItem, setSerialsItem] = useState<any>(null);

  const [itemForm, setItemForm] = useState({ ItemName: '', CategoryID: '', Barcode: '', ItemType: 'phone', IsSerialized: 1, SalePrice: '', CostPrice: '', MinStock: '', Unit: 'قطعة', IsActive: 1 });
  const [whForm, setWhForm] = useState({ WarehouseName: '', WarehouseType: 'main' });
  const [serials, setSerials] = useState<any[]>([]);
  const [newImei, setNewImei] = useState('');

  const fetchData = async () => {
    const [it, wh, cat] = await Promise.all([
      window.api.invoke('items:list', { search, type: typeFilter, isActive: 1 }),
      window.api.invoke('warehouses:list'),
      window.api.invoke('categories:list'),
    ]);
    setItems(it);
    setWarehouses(wh);
    setCategories(cat);
  };

  useEffect(() => { fetchData(); }, [search, typeFilter]);

  const saveItem = async () => {
    if (!itemForm.ItemName) { showToast('error', 'يرجى إدخال اسم الصنف'); return; }
    const data = { ...itemForm, CategoryID: itemForm.CategoryID ? parseInt(itemForm.CategoryID) : null, SalePrice: parseFloat(itemForm.SalePrice) || 0, CostPrice: parseFloat(itemForm.CostPrice) || 0, MinStock: parseInt(itemForm.MinStock) || 0, IsSerialized: itemForm.ItemType === 'phone' ? 1 : 0 };
    if (editingItem) {
      await window.api.invoke('items:update', editingItem.ItemID, data);
      showToast('success', 'تم تحديث الصنف');
    } else {
      await window.api.invoke('items:create', data);
      showToast('success', 'تم إضافة الصنف');
    }
    setShowItemModal(false);
    fetchData();
  };

  const saveWh = async () => {
    if (!whForm.WarehouseName) { showToast('error', 'يرجى إدخال اسم المخزن'); return; }
    if (editingWh) {
      await window.api.invoke('warehouses:update', editingWh.WarehouseID, whForm);
    } else {
      await window.api.invoke('warehouses:create', whForm);
    }
    setShowWhModal(false);
    fetchData();
    showToast('success', 'تم الحفظ');
  };

  const openSerials = async (item: any) => {
    setSerialsItem(item);
    const s = await window.api.invoke('serials:list', item.ItemID);
    setSerials(s);
    setShowSerialsModal(true);
  };

  const addSerial = async () => {
    if (!newImei) return;
    const wh = warehouses[0];
    const result = await window.api.invoke('serials:add', { ItemID: serialsItem.ItemID, IMEI: newImei, WarehouseID: wh.WarehouseID });
    if (!result.success) { showToast('error', result.message); return; }
    setNewImei('');
    const s = await window.api.invoke('serials:list', serialsItem.ItemID);
    setSerials(s);
    showToast('success', 'تم إضافة الرقم التسلسلي');
  };

  const typeLabels: Record<string, string> = { phone: 'هاتف', accessory: 'إكسسوار', spare_part: 'قطعة غيار' };

  return (
    <div className="space-y-4">
      <h1 className="text-2xl font-bold text-slate-800 dark:text-white">المخازن</h1>

      <div className="flex gap-2">
        <button onClick={() => setTab('items')} className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-medium ${tab === 'items' ? 'bg-primary-600 text-white' : 'bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-300'}`}><Package size={16} /> الأصناف</button>
        <button onClick={() => setTab('warehouses')} className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-medium ${tab === 'warehouses' ? 'bg-primary-600 text-white' : 'bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-300'}`><Package size={16} /> المخازن</button>
        <button onClick={() => setTab('transfers')} className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-medium ${tab === 'transfers' ? 'bg-primary-600 text-white' : 'bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-300'}`}><ArrowRightLeft size={16} /> التحويلات</button>
      </div>

      {tab === 'items' && (
        <div className="space-y-4">
          <div className="flex items-center justify-between gap-4">
            <div className="flex gap-3 flex-1">
              <div className="relative flex-1 max-w-xs">
                <Search className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="بحث..." className="w-full pr-9 pl-3 py-2 rounded-lg border border-slate-300 dark:border-slate-600 bg-white dark:bg-slate-800 text-slate-800 dark:text-white text-sm focus:outline-none focus:ring-2 focus:ring-primary-500" />
              </div>
              <Select value={typeFilter} onChange={(e) => setTypeFilter(e.target.value)} className="max-w-xs">
                <option value="all">كل الأنواع</option>
                <option value="phone">هواتف</option>
                <option value="accessory">إكسسوارات</option>
                <option value="spare_part">قطع غيار</option>
              </Select>
            </div>
            <Button onClick={() => { setEditingItem(null); setItemForm({ ItemName: '', CategoryID: '', Barcode: '', ItemType: 'phone', IsSerialized: 1, SalePrice: '', CostPrice: '', MinStock: '', Unit: 'قطعة', IsActive: 1 }); setShowItemModal(true); }} icon={<Plus size={16} />}>صنف جديد</Button>
          </div>

          <DataTable
            columns={[
              { key: 'ItemName', title: 'الاسم', render: (row) => <span className="font-medium">{row.ItemName}</span> },
              { key: 'ItemType', title: 'النوع', render: (row) => <Badge variant={row.ItemType === 'phone' ? 'blue' : row.ItemType === 'accessory' ? 'green' : 'purple'}>{typeLabels[row.ItemType]}</Badge> },
              { key: 'Barcode', title: 'الباركود', render: (row) => row.Barcode || '—' },
              { key: 'SalePrice', title: 'سعر البيع', render: (row) => row.SalePrice?.toFixed(2) || '—' },
              { key: 'stock', title: 'المخزون', render: (row) => row.IsSerialized ? `${row.AvailableSerials} متاح` : `${row.TotalStock || 0} ${row.Unit}` },
              { key: 'actions', title: 'إجراءات', render: (row) => (
                <div className="flex gap-2">
                  <button onClick={() => { setEditingItem(row); setItemForm({ ItemName: row.ItemName, CategoryID: row.CategoryID?.toString() || '', Barcode: row.Barcode || '', ItemType: row.ItemType, IsSerialized: row.IsSerialized, SalePrice: row.SalePrice?.toString() || '', CostPrice: row.CostPrice?.toString() || '', MinStock: row.MinStock?.toString() || '', Unit: row.Unit || 'قطعة', IsActive: row.IsActive }); setShowItemModal(true); }} className="text-xs text-primary-600 hover:underline flex items-center gap-1"><Edit size={12} /> تعديل</button>
                  {row.IsSerialized && <button onClick={() => openSerials(row)} className="text-xs text-blue-600 hover:underline flex items-center gap-1"><Smartphone size={12} /> IMEI</button>}
                </div>
              )},
            ]}
            data={items}
            keyField="ItemID"
            emptyMessage="لا توجد أصناف"
          />
        </div>
      )}

      {tab === 'warehouses' && (
        <div className="space-y-4">
          <div className="flex justify-end"><Button onClick={() => { setEditingWh(null); setWhForm({ WarehouseName: '', WarehouseType: 'main' }); setShowWhModal(true); }} icon={<Plus size={16} />}>مخزن جديد</Button></div>
          <DataTable
            columns={[
              { key: 'WarehouseName', title: 'الاسم', render: (row) => <span className="font-medium">{row.WarehouseName}</span> },
              { key: 'WarehouseType', title: 'النوع', render: (row) => <Badge variant={row.WarehouseType === 'main' ? 'blue' : row.WarehouseType === 'maintenance' ? 'orange' : 'gray'}>{row.WarehouseType === 'main' ? 'رئيسي' : row.WarehouseType === 'maintenance' ? 'صيانة' : 'أخرى'}</Badge> },
              { key: 'actions', title: '', render: (row) => <button onClick={() => { setEditingWh(row); setWhForm({ WarehouseName: row.WarehouseName, WarehouseType: row.WarehouseType }); setShowWhModal(true); }} className="text-xs text-primary-600 hover:underline flex items-center gap-1"><Edit size={12} /> تعديل</button> },
            ]}
            data={warehouses}
            keyField="WarehouseID"
            emptyMessage="لا توجد مخازن"
          />
        </div>
      )}

      {tab === 'transfers' && (
        <div className="space-y-4">
          <div className="flex justify-end"><Button onClick={() => setShowTransferModal(true)} icon={<ArrowRightLeft size={16} />}>تحويل جديد</Button></div>
          <TransferList warehouses={warehouses} showToast={showToast} />
        </div>
      )}

      {/* Item Modal */}
      <Modal isOpen={showItemModal} onClose={() => setShowItemModal(false)} title={editingItem ? 'تعديل صنف' : 'صنف جديد'} size="lg"
        footer={<><Button variant="secondary" onClick={() => setShowItemModal(false)}>إلغاء</Button><Button onClick={saveItem}>حفظ</Button></>}
      >
        <div className="grid grid-cols-2 gap-4">
          <Input label="اسم الصنف" value={itemForm.ItemName} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setItemForm({ ...itemForm, ItemName: e.target.value })} />
          <Input label="الباركود" value={itemForm.Barcode} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setItemForm({ ...itemForm, Barcode: e.target.value })} />
          <Select label="نوع الصنف" value={itemForm.ItemType} onChange={(e) => setItemForm({ ...itemForm, ItemType: e.target.value, IsSerialized: e.target.value === 'phone' ? 1 : 0 })}>
            <option value="phone">هاتف (مسلسل)</option>
            <option value="accessory">إكسسوار (كمية)</option>
            <option value="spare_part">قطعة غيار (كمية)</option>
          </Select>
          <Input label="سعر البيع" type="number" value={itemForm.SalePrice} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setItemForm({ ...itemForm, SalePrice: e.target.value })} />
          <Input label="سعر التكلفة" type="number" value={itemForm.CostPrice} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setItemForm({ ...itemForm, CostPrice: e.target.value })} />
          <Input label="حد التنبيه" type="number" value={itemForm.MinStock} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setItemForm({ ...itemForm, MinStock: e.target.value })} />
          <Input label="الوحدة" value={itemForm.Unit} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setItemForm({ ...itemForm, Unit: e.target.value })} />
        </div>
      </Modal>

      {/* Warehouse Modal */}
      <Modal isOpen={showWhModal} onClose={() => setShowWhModal(false)} title={editingWh ? 'تعديل مخزن' : 'مخزن جديد'}
        footer={<><Button variant="secondary" onClick={() => setShowWhModal(false)}>إلغاء</Button><Button onClick={saveWh}>حفظ</Button></>}
      >
        <div className="space-y-4">
          <Input label="اسم المخزن" value={whForm.WarehouseName} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setWhForm({ ...whForm, WarehouseName: e.target.value })} />
          <Select label="النوع" value={whForm.WarehouseType} onChange={(e) => setWhForm({ ...whForm, WarehouseType: e.target.value })}>
            <option value="main">مخزن رئيسي</option>
            <option value="maintenance">مخزن صيانة</option>
            <option value="other">أخرى</option>
          </Select>
        </div>
      </Modal>

      {/* Serials Modal */}
      <Modal isOpen={showSerialsModal} onClose={() => setShowSerialsModal(false)} title={`أرقام IMEI - ${serialsItem?.ItemName || ''}`} size="lg">
        <div className="space-y-4">
          <div className="flex gap-2">
            <Input placeholder="أدخل رقم IMEI" value={newImei} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setNewImei(e.target.value)} />
            <Button onClick={addSerial}>إضافة</Button>
          </div>
          <DataTable
            columns={[
              { key: 'IMEI', title: 'IMEI', render: (row) => <span className="font-mono">{row.IMEI}</span> },
              { key: 'Status', title: 'الحالة', render: (row) => <Badge variant={row.Status === 'available' ? 'green' : row.Status === 'sold' ? 'red' : 'orange'}>{row.Status === 'available' ? 'متاح' : row.Status === 'sold' ? 'مباع' : row.Status === 'returned' ? 'مرتجع' : 'في الصيانة'}</Badge> },
              { key: 'WarehouseName', title: 'المخزن' },
              { key: 'CostPrice', title: 'التكلفة', render: (row) => row.CostPrice?.toFixed(2) || '—' },
            ]}
            data={serials}
            keyField="SerialID"
            emptyMessage="لا توجد أرقام تسلسلية"
          />
        </div>
      </Modal>
    </div>
  );
}

function TransferList({ warehouses, showToast }: { warehouses: any[]; showToast: (type: 'success' | 'error', msg: string) => void }) {
  const [transfers, setTransfers] = useState<any[]>([]);
  const [showModal, setShowModal] = useState(false);
  const [fromWh, setFromWh] = useState('');
  const [toWh, setToWh] = useState('');
  const [items] = useState<any[]>([]);
  const [selectedItems, setSelectedItems] = useState<any[]>([]);

  const fetchTransfers = async () => {
    const t = await window.api.invoke('transfers:list');
    setTransfers(t);
  };

  useEffect(() => { fetchTransfers(); }, []);

  const handleTransfer = async () => {
    if (!fromWh || !toWh || fromWh === toWh) { showToast('error', 'يرجى اختيار مخازن صحيحة'); return; }
    if (selectedItems.length === 0) { showToast('error', 'أضف أصنافاً للتحويل'); return; }
    const result = await window.api.invoke('transfers:create', {
      FromWarehouseID: parseInt(fromWh),
      ToWarehouseID: parseInt(toWh),
      items: selectedItems,
      userId: 1,
    });
    if (result.success) {
      showToast('success', `تم التحويل - رقم: ${result.transferNumber}`);
