  return (
    <>
      <DataTable
        columns={[
          { key: 'TransferNumber', title: 'رقم التحويل', render: (row) => <span className="font-mono text-xs">{row.TransferNumber}</span> },
          { key: 'Date', title: 'التاريخ' },
          { key: 'FromWarehouse', title: 'من', render: (row) => row.FromWarehouse },
          { key: 'ToWarehouse', title: 'إلى', render: (row) => row.ToWarehouse },
          { key: 'Status', title: 'الحالة', render: (row) => <Badge variant={row.Status === 'completed' ? 'green' : 'gray'}>{row.Status === 'completed' ? 'مكتمل' : 'ملغي'}</Badge> },
        ]}
        data={transfers}
        keyField="TransferID"
        emptyMessage="لا توجد تحويلات"
      />
    </>
  );
}

import { useState, useEffect } from 'react';
import { Plus, Receipt } from 'lucide-react';
import { Button } from '../../components/ui/Button';
import { Input, Select, Textarea } from '../../components/ui/Input';
import { Modal } from '../../components/ui/Modal';
import { Badge } from '../../components/ui/Badge';
import { DataTable } from '../../components/shared/DataTable';
import { useToastStore } from '../../components/ui/Toast';

export function VouchersPage() {
  const { showToast } = useToastStore();
  const [vouchers, setVouchers] = useState<any[]>([]);
  const [typeFilter, setTypeFilter] = useState('all');
  const [showModal, setShowModal] = useState(false);
  const [cashAccounts, setCashAccounts] = useState<any[]>([]);
  const [paymentMethods, setPaymentMethods] = useState<any[]>([]);
  const [customers, setCustomers] = useState<any[]>([]);
  const [suppliers, setSuppliers] = useState<any[]>([]);
  const [employees, setEmployees] = useState<any[]>([]);

  const [form, setForm] = useState({
    VoucherType: 'receipt',
    Amount: '',
    PartyType: 'general',
    PartyID: '',
    PartyName: '',
    Description: '',
    CashAccountID: '',
    PaymentMethodID: '',
  });

  const fetchData = async () => {
    const [v, ca, pm, cu, su, em] = await Promise.all([
      window.api.invoke('vouchers:list', { type: typeFilter }),
      window.api.invoke('cashAccounts:list'),
      window.api.invoke('paymentMethods:list'),
      window.api.invoke('customers:list'),
      window.api.invoke('suppliers:list'),
      window.api.invoke('employees:list', { isActive: 1 }),
    ]);
    setVouchers(v);
    setCashAccounts(ca);
    setPaymentMethods(pm);
    setCustomers(cu);
    setSuppliers(su);
    setEmployees(em);
  };

  useEffect(() => { fetchData(); }, [typeFilter]);

  const handleSave = async () => {
    if (!form.Amount || !form.Description || !form.CashAccountID) {
      showToast('error', 'يرجى إدخال المبلغ والبيان والخزنة');
      return;
    }
    const activeFy = await window.api.invoke('fiscalYear:getActive');
    if (!activeFy) {
      showToast('error', 'لا توجد سنة مالية مفتوحة');
      return;
    }
    const data = {
      ...form,
      Amount: parseFloat(form.Amount),
      PartyID: form.PartyID ? parseInt(form.PartyID) : null,
      CashAccountID: parseInt(form.CashAccountID),
      PaymentMethodID: form.PaymentMethodID ? parseInt(form.PaymentMethodID) : null,
      userId: 1,
      fiscalYearId: activeFy.FiscalYearID,
    };
    const result = await window.api.invoke('vouchers:create', data);
    if (result.success) {
      showToast('success', `تم إنشاء السند - رقم: ${result.voucherNumber}`);
      setShowModal(false);
      setForm({ VoucherType: 'receipt', Amount: '', PartyType: 'general', PartyID: '', PartyName: '', Description: '', CashAccountID: '', PaymentMethodID: '' });
      fetchData();
    }
  };

  const partyTypeOptions = [
    { value: 'general', label: 'عام' },
    { value: 'customer', label: 'عميل' },
    { value: 'supplier', label: 'مورد' },
    { value: 'employee', label: 'موظف' },
  ];

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-bold text-slate-800 dark:text-white">السندات</h1>
        <Button onClick={() => setShowModal(true)} icon={<Plus size={16} />}>سند جديد</Button>
      </div>

      <div className="flex gap-2">
        <button onClick={() => setTypeFilter('all')} className={`px-4 py-2 rounded-lg text-sm font-medium ${typeFilter === 'all' ? 'bg-primary-600 text-white' : 'bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-300'}`}>الكل</button>
        <button onClick={() => setTypeFilter('receipt')} className={`px-4 py-2 rounded-lg text-sm font-medium ${typeFilter === 'receipt' ? 'bg-green-600 text-white' : 'bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-300'}`}>سندات قبض</button>
        <button onClick={() => setTypeFilter('payment')} className={`px-4 py-2 rounded-lg text-sm font-medium ${typeFilter === 'payment' ? 'bg-red-600 text-white' : 'bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-300'}`}>سندات صرف</button>
      </div>

      <DataTable
        columns={[
          { key: 'VoucherNumber', title: 'رقم السند', render: (row) => <span className="font-mono text-xs">{row.VoucherNumber}</span> },
          { key: 'Date', title: 'التاريخ' },
          { key: 'VoucherType', title: 'النوع', render: (row) => <Badge variant={row.VoucherType === 'receipt' ? 'green' : 'red'}>{row.VoucherType === 'receipt' ? 'قبض' : 'صرف'}</Badge> },
          { key: 'Amount', title: 'المبلغ', render: (row) => <span className="font-bold">{row.Amount?.toFixed(2)}</span> },
          { key: 'Description', title: 'البيان' },
          { key: 'PartyName', title: 'الطرف', render: (row) => row.PartyName || '—' },
          { key: 'Username', title: 'المستخدم' },
        ]}
        data={vouchers}
        keyField="VoucherID"
        emptyMessage="لا توجد سندات"
      />

      <Modal isOpen={showModal} onClose={() => setShowModal(false)} title="سند جديد"
        footer={<><Button variant="secondary" onClick={() => setShowModal(false)}>إلغاء</Button><Button onClick={handleSave}>حفظ</Button></>}
      >
        <div className="grid grid-cols-2 gap-4">
          <Select label="نوع السند" value={form.VoucherType} onChange={(e) => setForm({ ...form, VoucherType: e.target.value })}>
            <option value="receipt">سند قبض</option>
            <option value="payment">سند صرف</option>
          </Select>
          <Input label="المبلغ" type="number" value={form.Amount} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setForm({ ...form, Amount: e.target.value })} />
          <Select label="نوع الطرف" value={form.PartyType} onChange={(e) => setForm({ ...form, PartyType: e.target.value, PartyID: '' })}>
            {partyTypeOptions.map(o => <option key={o.value} value={o.value}>{o.label}</option>)}
          </Select>
          {form.PartyType === 'customer' && (
            <Select label="العميل" value={form.PartyID} onChange={(e) => setForm({ ...form, PartyID: e.target.value })}>
              <option value="">— اختر —</option>
              {customers.map((c: any) => <option key={c.CustomerID} value={c.CustomerID}>{c.Name} ({c.Balance?.toFixed(2)})</option>)}
            </Select>
          )}
          {form.PartyType === 'supplier' && (
            <Select label="المورد" value={form.PartyID} onChange={(e) => setForm({ ...form, PartyID: e.target.value })}>
              <option value="">— اختر —</option>
              {suppliers.map((s: any) => <option key={s.SupplierID} value={s.SupplierID}>{s.Name} ({s.Balance?.toFixed(2)})</option>)}
            </Select>
          )}
          {form.PartyType === 'employee' && (
            <Select label="الموظف" value={form.PartyID} onChange={(e) => setForm({ ...form, PartyID: e.target.value })}>
              <option value="">— اختر —</option>
              {employees.map((emp: any) => <option key={emp.EmployeeID} value={emp.EmployeeID}>{emp.Name}</option>)}
            </Select>
          )}
          {form.PartyType === 'general' && (
            <Input label="اسم الطرف (اختياري)" value={form.PartyName} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setForm({ ...form, PartyName: e.target.value })} />
          )}
          <Select label="الخزنة/البنك" value={form.CashAccountID} onChange={(e) => setForm({ ...form, CashAccountID: e.target.value })}>
            <option value="">— اختر —</option>
            {cashAccounts.map((ca: any) => <option key={ca.CashAccountID} value={ca.CashAccountID}>{ca.AccountName} ({ca.Balance?.toFixed(2)})</option>)}
          </Select>
          <Select label="طريقة الدفع (اختياري)" value={form.PaymentMethodID} onChange={(e) => setForm({ ...form, PaymentMethodID: e.target.value })}>
            <option value="">— بدون —</option>
            {paymentMethods.map((pm: any) => <option key={pm.PaymentMethodID} value={pm.PaymentMethodID}>{pm.MethodName}</option>)}
          </Select>
          <div className="col-span-2">
            <Textarea label="البيان" value={form.Description} onChange={(e: React.ChangeEvent<HTMLTextAreaElement>) => setForm({ ...form, Description: e.target.value })} placeholder="وصف العملية..." />
          </div>
        </div>
      </Modal>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Plus, Trash2, ShoppingCart, Smartphone, Search } from 'lucide-react';
import { Button } from '../../components/ui/Button';
import { Input, Select } from '../../components/ui/Input';
import { Modal } from '../../components/ui/Modal';
import { Badge } from '../../components/ui/Badge';
import { DataTable } from '../../components/shared/DataTable';
import { useToastStore } from '../../components/ui/Toast';

interface CartItem { ItemID: number; ItemName: string; SerialID?: number; IMEI?: string; Quantity: number; UnitPrice: number; UnitCost?: number; }

export function SalesPage() {
  const { showToast } = useToastStore();
  const [showSaleModal, setShowSaleModal] = useState(false);
  const [sales, setSales] = useState<any[]>([]);
  const [customers, setCustomers] = useState<any[]>([]);
  const [cashAccounts, setCashAccounts] = useState<any[]>([]);
  const [paymentMethods, setPaymentMethods] = useState<any[]>([]);
  const [items, setItems] = useState<any[]>([]);
  const [availableSerials, setAvailableSerials] = useState<any[]>([]);
  const [searchItem, setSearchItem] = useState('');

  // Sale form
  const [selectedCustomer, setSelectedCustomer] = useState('');
  const [customerName, setCustomerName] = useState('');
  const [customerPhone, setCustomerPhone] = useState('');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [discount, setDiscount] = useState('');
  const [taxRate, setTaxRate] = useState(0);
  const [taxEnabled, setTaxEnabled] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState('cash');
  const [paidAmount, setPaidAmount] = useState('');
  const [cashAccountId, setCashAccountId] = useState('');
  const [paymentMethodId, setPaymentMethodId] = useState('');
  const [notes, setNotes] = useState('');

  const [selectedItem, setSelectedItem] = useState('');
  const [selectedSerial, setSelectedSerial] = useState('');
  const [itemQty, setItemQty] = useState('1');
  const [itemPrice, setItemPrice] = useState('');

  const fetchData = async () => {
    const [s, cu, ca, pm, it, settings] = await Promise.all([
      window.api.invoke('sales:list'),
      window.api.invoke('customers:list'),
      window.api.invoke('cashAccounts:list'),
      window.api.invoke('paymentMethods:list'),
      window.api.invoke('items:list', { search: searchItem, isActive: 1 }),
      window.api.invoke('settings:getAll'),
    ]);
    setSales(s);
    setCustomers(cu);
    setCashAccounts(ca);
    setPaymentMethods(pm);
    setItems(it);
    setTaxEnabled(settings.vat_enabled === '1');
    setTaxRate(parseFloat(settings.vat_rate || '0'));
  };

  useEffect(() => { fetchData(); }, [searchItem]);

  const subtotal = cart.reduce((sum, item) => sum + item.Quantity * item.UnitPrice, 0);
  const discountAmount = parseFloat(discount) || 0;
  const taxAmount = taxEnabled ? (subtotal - discountAmount) * (taxRate / 100) : 0;
  const total = subtotal - discountAmount + taxAmount;

  const addToCart = async () => {
    if (!selectedItem) { showToast('error', 'اختر صنفاً'); return; }
    const item = items.find(i => i.ItemID === parseInt(selectedItem));
    if (!item) return;

    if (item.IsSerialized) {
      if (!selectedSerial) { showToast('error', 'اختر رقم IMEI'); return; }
      const serial = availableSerials.find(s => s.SerialID === parseInt(selectedSerial));
      if (!serial) return;
      if (cart.find(c => c.SerialID === serial.SerialID)) { showToast('error', 'هذا الجهاز في السلة بالفعل'); return; }
      setCart([...cart, { ItemID: item.ItemID, ItemName: item.ItemName, SerialID: serial.SerialID, IMEI: serial.IMEI, Quantity: 1, UnitPrice: parseFloat(itemPrice) || item.SalePrice || 0, UnitCost: item.CostPrice }]);
      setSelectedSerial('');
    } else {
      setCart([...cart, { ItemID: item.ItemID, ItemName: item.ItemName, Quantity: parseInt(itemQty) || 1, UnitPrice: parseFloat(itemPrice) || item.SalePrice || 0, UnitCost: item.CostPrice }]);
    }
    setSelectedItem('');
    setItemPrice('');
    setItemQty('1');
  };

  const removeFromCart = (idx: number) => setCart(cart.filter((_, i) => i !== idx));

  const onItemSelected = async (itemId: string) => {
    setSelectedItem(itemId);
    const item = items.find(i => i.ItemID === parseInt(itemId));
    if (item?.IsSerialized) {
      const serials = await window.api.invoke('serials:getAvailable', parseInt(itemId));
      setAvailableSerials(serials);
    } else {
      setAvailableSerials([]);
      setItemPrice(item?.SalePrice?.toString() || '');
    }
  };

  const handleSale = async () => {
    if (cart.length === 0) { showToast('error', 'السلة فارغة'); return; }
    if (!cashAccountId && paymentMethod === 'cash') { showToast('error', 'اختر الخزنة'); return; }

    const customer = customers.find(c => c.CustomerID === parseInt(selectedCustomer));
    if (selectedCustomer && customer?.Status === 'suspended') { showToast('error', 'العميل محظور - لا يمكن البيع له'); return; }

    const activeFy = await window.api.invoke('fiscalYear:getActive');
    if (!activeFy) { showToast('error', 'لا توجد سنة مالية مفتوحة'); return; }

    const paid = parseFloat(paidAmount) || (paymentMethod === 'cash' ? total : 0);

    const result = await window.api.invoke('sales:create', {
      CustomerID: selectedCustomer ? parseInt(selectedCustomer) : undefined,
      CustomerName: customer?.Name || customerName,
      CustomerPhone: customer?.Phone || customerPhone,
      items: cart.map(c => ({ ItemID: c.ItemID, SerialID: c.SerialID, IMEI: c.IMEI, Quantity: c.Quantity, UnitPrice: c.UnitPrice, UnitCost: c.UnitCost })),
      Discount: discountAmount,
      TaxRate: taxEnabled ? taxRate : 0,
      TaxAmount: taxAmount,
      PaymentMethod: paymentMethod,
      PaidAmount: paid,
      CashAccountID: cashAccountId ? parseInt(cashAccountId) : undefined,
      PaymentMethodID: paymentMethodId ? parseInt(paymentMethodId) : undefined,
      Notes: notes,
      userId: 1,
      fiscalYearId: activeFy.FiscalYearID,
    });

    if (result.success) {
      showToast('success', `تم إنشاء الفاتورة - رقم: ${result.saleNumber}`);
      setShowSaleModal(false);
      resetForm();
      fetchData();
    } else {
      showToast('error', result.message || 'فشل إنشاء الفاتورة');
    }
  };

  const resetForm = () => {
    setCart([]); setSelectedCustomer(''); setCustomerName(''); setCustomerPhone('');
    setDiscount(''); setPaidAmount(''); setCashAccountId(''); setPaymentMethodId(''); setNotes('');
  };

  const selectedCustomerObj = customers.find(c => c.CustomerID === parseInt(selectedCustomer));

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-bold text-slate-800 dark:text-white">المبيعات</h1>
        <Button onClick={() => setShowSaleModal(true)} icon={<Plus size={16} />}>فاتورة جديدة</Button>
      </div>

      <DataTable
        columns={[
          { key: 'SaleNumber', title: 'رقم الفاتورة', render: (row) => <span className="font-mono text-xs">{row.SaleNumber}</span> },
          { key: 'Date', title: 'التاريخ' },
          { key: 'CustomerName', title: 'العميل', render: (row) => row.CustomerName || row.CustomerName || '—' },
          { key: 'TotalAmount', title: 'الإجمالي', render: (row) => <span className="font-bold">{row.TotalAmount?.toFixed(2)}</span> },
          { key: 'PaidAmount', title: 'المدفوع', render: (row) => <span className="text-green-600">{row.PaidAmount?.toFixed(2)}</span> },
          { key: 'RemainingAmount', title: 'المتبقي', render: (row) => row.RemainingAmount > 0 ? <span className="text-red-600">{row.RemainingAmount?.toFixed(2)}</span> : '—' },
          { key: 'Status', title: 'الحالة', render: (row) => <Badge variant={row.Status === 'completed' ? 'green' : row.Status === 'partial' ? 'yellow' : 'red'}>{row.Status === 'completed' ? 'مكتملة' : row.Status === 'partial' ? 'جزئية' : 'غير مدفوعة'}</Badge> },
        ]}
        data={sales}
        keyField="SaleID"
        emptyMessage="لا توجد فواتير"
      />

      {/* Sale Modal */}
      <Modal isOpen={showSaleModal} onClose={() => setShowSaleModal(false)} title="فاتورة بيع جديدة" size="xl"
        footer={<><Button variant="secondary" onClick={() => setShowSaleModal(false)}>إلغاء</Button><Button onClick={handleSale} icon={<ShoppingCart size={16} />}>إتمام البيع</Button></>}
      >
        <div className="space-y-4">
          {/* Customer */}
          <div className="grid grid-cols-3 gap-3">
            <Select label="العميل" value={selectedCustomer} onChange={(e) => setSelectedCustomer(e.target.value)}>
              <option value="">— عميل نقدي —</option>
              {customers.map((c: any) => <option key={c.CustomerID} value={c.CustomerID}>{c.Name} ({c.Phone || '—'})</option>)}
            </Select>
            {!selectedCustomer && <>
              <Input label="الاسم" value={customerName} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setCustomerName(e.target.value)} />
              <Input label="الهاتف" value={customerPhone} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setCustomerPhone(e.target.value)} />
            </>}
            {selectedCustomerObj && <>
              <Input label="الهاتف" value={selectedCustomerObj.Phone || ''} disabled />
              <div>
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">الرصيد السابق</label>
                <div className={`px-3 py-2 rounded-lg text-sm font-bold ${selectedCustomerObj.Balance > 0 ? 'text-red-600 bg-red-50 dark:bg-red-900/20' : 'text-green-600 bg-green-50 dark:bg-green-900/20'}`}>
                  {selectedCustomerObj.Balance?.toFixed(2)} مدين
                </div>
              </div>
            </>}
          </div>

          {/* Add item */}
          <div className="bg-slate-50 dark:bg-slate-800/50 rounded-lg p-3 border border-slate-200 dark:border-slate-700">
            <div className="grid grid-cols-12 gap-2 items-end">
              <div className="col-span-4">
                <Select label="الصنف" value={selectedItem} onChange={(e) => onItemSelected(e.target.value)}>
                  <option value="">— اختر —</option>
                  {items.map((it: any) => <option key={it.ItemID} value={it.ItemID}>{it.ItemName} {it.IsSerialized ? '(IMEI)' : ''}</option>)}
                </Select>
              </div>
              {availableSerials.length > 0 && (
                <div className="col-span-3">
                  <Select label="IMEI" value={selectedSerial} onChange={(e) => setSelectedSerial(e.target.value)}>
                    <option value="">— اختر —</option>
                    {availableSerials.map((s: any) => <option key={s.SerialID} value={s.SerialID}>{s.IMEI}</option>)}
                  </Select>
                </div>
              )}
              {availableSerials.length === 0 && selectedItem && (
                <div className="col-span-2"><Input label="الكمية" type="number" value={itemQty} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setItemQty(e.target.value)} /></div>
              )}
              <div className="col-span-2"><Input label="السعر" type="number" value={itemPrice} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setItemPrice(e.target.value)} /></div>
              <div className="col-span-2"><Button onClick={addToCart} icon={<Plus size={14} />} size="sm">إضافة</Button></div>
            </div>
          </div>

          {/* Cart */}
          <div className="rounded-lg border border-slate-200 dark:border-slate-700 overflow-hidden">
            <table className="w-full text-sm">
              <thead><tr className="bg-slate-50 dark:bg-slate-800/50"><th className="px-3 py-2 text-right">الصنف</th><th className="px-3 py-2 text-right">IMEI</th><th className="px-3 py-2 text-right">الكمية</th><th className="px-3 py-2 text-right">السعر</th><th className="px-3 py-2 text-right">الإجمالي</th><th className="px-3 py-2"></th></tr></thead>
              <tbody>
                {cart.length === 0 ? <tr><td colSpan={6} className="px-3 py-4 text-center text-slate-400">السلة فارغة</td></tr> :
                  cart.map((item, idx) => (
                    <tr key={idx} className="border-t border-slate-100 dark:border-slate-700/50">
                      <td className="px-3 py-2 font-medium">{item.ItemName}</td>
                      <td className="px-3 py-2 font-mono text-xs">{item.IMEI || '—'}</td>
                      <td className="px-3 py-2">{item.Quantity}</td>
                      <td className="px-3 py-2">{item.UnitPrice.toFixed(2)}</td>
                      <td className="px-3 py-2 font-bold">{(item.Quantity * item.UnitPrice).toFixed(2)}</td>
                      <td className="px-3 py-2"><button onClick={() => removeFromCart(idx)} className="text-red-500 hover:text-red-600"><Trash2 size={14} /></button></td>
                    </tr>
                  ))
                }
              </tbody>
            </table>
          </div>

          {/* Totals & Payment */}
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <div className="flex justify-between text-sm"><span className="text-slate-500">الإجمالي الفرعي</span><span className="font-medium">{subtotal.toFixed(2)}</span></div>
              <div className="flex items-center gap-2">
                <input type="checkbox" checked={taxEnabled} onChange={(e) => setTaxEnabled(e.target.checked)} className="w-4 h-4" />
                <span className="text-sm text-slate-500">ضريبة ({taxRate}%)</span>
                <span className="font-medium mr-auto">{taxAmount.toFixed(2)}</span>
              </div>
              <div className="flex items-center gap-2">
                <span className="text-sm text-slate-500">خصم</span>
                <input type="number" value={discount} onChange={(e) => setDiscount(e.target.value)} className="w-24 px-2 py-1 rounded border border-slate-300 dark:border-slate-600 bg-white dark:bg-slate-800 text-sm" />
              </div>
              <div className="flex justify-between text-lg font-bold border-t border-slate-200 dark:border-slate-700 pt-2"><span>الإجمالي</span><span className="text-primary-600">{total.toFixed(2)}</span></div>
            </div>
            <div className="space-y-3">
              <Select label="طريقة الدفع" value={paymentMethod} onChange={(e) => setPaymentMethod(e.target.value)}>
                <option value="cash">نقدي</option>
                <option value="credit">آجل</option>
                <option value="card">بطاقة</option>
                <option value="transfer">تحويل</option>
                <option value="wallet">محفظة</option>
              </Select>
              <Input label="المبلغ المدفوع" type="number" value={paidAmount} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setPaidAmount(e.target.value)} hint={`الإجمالي: ${total.toFixed(2)}`} />
              <Select label="الخزنة/البنك" value={cashAccountId} onChange={(e) => setCashAccountId(e.target.value)}>
                <option value="">— اختر —</option>
                {cashAccounts.map((ca: any) => <option key={ca.CashAccountID} value={ca.CashAccountID}>{ca.AccountName} ({ca.Balance?.toFixed(2)})</option>)}
              </Select>
            </div>
          </div>
        </div>
      </Modal>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Plus, Wrench, Smartphone, Search } from 'lucide-react';
import { Button } from '../../components/ui/Button';
import { Input, Select, Textarea } from '../../components/ui/Input';
import { Modal } from '../../components/ui/Modal';
import { Badge } from '../../components/ui/Badge';
import { DataTable } from '../../components/shared/DataTable';
import { useToastStore } from '../../components/ui/Toast';

const statusLabels: Record<string, string> = {
  received: 'مستلم', inspecting: 'فحص', in_progress: 'قيد العمل',
  ready: 'جاهز للتسليم', delivered: 'تم التسليم', returned: 'مرتجع', cancelled: 'ملغي'
};
const statusVariants: Record<string, 'gray' | 'blue' | 'yellow' | 'orange' | 'green' | 'red' | 'purple'> = {
  received: 'blue', inspecting: 'yellow', in_progress: 'orange',
  ready: 'purple', delivered: 'green', returned: 'red', cancelled: 'gray'
};

export function MaintenancePage() {
  const { showToast } = useToastStore();
  const [tab, setTab] = useState<'list' | 'receive' | 'deliver'>('list');
  const [tickets, setTickets] = useState<any[]>([]);
  const [statusFilter, setStatusFilter] = useState('all');
  const [customers, setCustomers] = useState<any[]>([]);
  const [employees, setEmployees] = useState<any[]>([]);
  const [cashAccounts, setCashAccounts] = useState<any[]>([]);
  const [showReceive, setShowReceive] = useState(false);
  const [showDeliver, setShowDeliver] = useState(false);
  const [openTickets, setOpenTickets] = useState<any[]>([]);
  const [selectedTicket, setSelectedTicket] = useState('');

  // Receive form
  const [recvForm, setRecvForm] = useState({
    CustomerID: '', CustomerName: '', CustomerPhone: '',
    DeviceModel: '', DeviceIMEI: '', ProblemDesc: '',
    Accessories: '', DevicePassword: '',
    AgreedDeliveryDate: '', AgreedCost: '',
    TechnicianID: '',
  });

  // Deliver form
  const [deliverForm, setDeliverForm] = useState({
    LaborCost: '', PaidAmount: '', CashAccountID: '', PaymentMethod: 'cash',
  });

  const fetchData = async () => {
    const [t, cu, em, ca] = await Promise.all([
      window.api.invoke('maintenance:list', { status: statusFilter }),
      window.api.invoke('customers:list'),
      window.api.invoke('employees:list', { isActive: 1 }),
      window.api.invoke('cashAccounts:list'),
    ]);
    setTickets(t);
    setCustomers(cu);
    setEmployees(em);
    setCashAccounts(ca);
  };

  useEffect(() => { fetchData(); }, [statusFilter]);

  const handleReceive = async () => {
    if (!recvForm.CustomerName || !recvForm.CustomerPhone || !recvForm.DeviceModel || !recvForm.ProblemDesc) {
      showToast('error', 'يرجى إدخال بيانات العميل والجهاز والمشكلة');
      return;
    }
    const activeFy = await window.api.invoke('fiscalYear:getActive');
    if (!activeFy) { showToast('error', 'لا توجد سنة مالية مفتوحة'); return; }
    const result = await window.api.invoke('maintenance:receive', {
      CustomerID: recvForm.CustomerID ? parseInt(recvForm.CustomerID) : undefined,
      CustomerName: recvForm.CustomerName,
      CustomerPhone: recvForm.CustomerPhone,
      DeviceModel: recvForm.DeviceModel,
      DeviceIMEI: recvForm.DeviceIMEI || undefined,
      ProblemDesc: recvForm.ProblemDesc,
      Accessories: recvForm.Accessories || undefined,
      DevicePassword: recvForm.DevicePassword || undefined,
      AgreedDeliveryDate: recvForm.AgreedDeliveryDate || undefined,
      AgreedCost: recvForm.AgreedCost ? parseFloat(recvForm.AgreedCost) : undefined,
      TechnicianID: recvForm.TechnicianID ? parseInt(recvForm.TechnicianID) : undefined,
      userId: 1,
      fiscalYearId: activeFy.FiscalYearID,
    });
    if (result.success) {
      showToast('success', `تم استلام الجهاز - رقم: ${result.ticketNumber}`);
      setShowReceive(false);
      setRecvForm({ CustomerID: '', CustomerName: '', CustomerPhone: '', DeviceModel: '', DeviceIMEI: '', ProblemDesc: '', Accessories: '', DevicePassword: '', AgreedDeliveryDate: '', AgreedCost: '', TechnicianID: '' });
      fetchData();
    }
  };

  const openDeliverModal = async () => {
    const open = await window.api.invoke('maintenance:list', { status: 'all' });
    const filtered = open.filter((t: any) => !['delivered', 'cancelled', 'returned'].includes(t.Status));
    setOpenTickets(filtered);
    setShowDeliver(true);
  };

  const handleDeliver = async () => {
    if (!selectedTicket) { showToast('error', 'اختر جهازاً'); return; }
    const activeFy = await window.api.invoke('fiscalYear:getActive');
    if (!activeFy) { showToast('error', 'لا توجد سنة مالية مفتوحة'); return; }
    const ticket = openTickets.find(t => t.TicketID === parseInt(selectedTicket));
    const result = await window.api.invoke('maintenance:deliver', {
      TicketID: parseInt(selectedTicket),
      CustomerID: ticket?.CustomerID,
      CustomerName: ticket?.CustomerName,
      LaborCost: parseFloat(deliverForm.LaborCost) || 0,
      AdditionalCosts: [],
      PaymentMethod: deliverForm.PaymentMethod,
      PaidAmount: parseFloat(deliverForm.PaidAmount) || 0,
      CashAccountID: deliverForm.CashAccountID ? parseInt(deliverForm.CashAccountID) : undefined,
      userId: 1,
      fiscalYearId: activeFy.FiscalYearID,
    });
    if (result.success) {
      showToast('success', `تم تسليم الجهاز - الإجمالي: ${result.totalCost?.toFixed(2)}`);
      setShowDeliver(false);
      setSelectedTicket('');
      setDeliverForm({ LaborCost: '', PaidAmount: '', CashAccountID: '', PaymentMethod: 'cash' });
      fetchData();
    }
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-bold text-slate-800 dark:text-white">الصيانة</h1>
        <div className="flex gap-2">
          <Button variant="secondary" onClick={openDeliverModal} icon={<Smartphone size={16} />}>تسليم جهاز</Button>
          <Button onClick={() => setShowReceive(true)} icon={<Plus size={16} />}>استلام جهاز</Button>
        </div>
      </div>

      <div className="flex gap-2 flex-wrap">
        {['all', 'received', 'in_progress', 'ready', 'delivered'].map(s => (
          <button key={s} onClick={() => setStatusFilter(s)} className={`px-3 py-1.5 rounded-lg text-xs font-medium ${statusFilter === s ? 'bg-primary-600 text-white' : 'bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-300'}`}>
            {s === 'all' ? 'الكل' : statusLabels[s]}
          </button>
        ))}
      </div>

      <DataTable
        columns={[
          { key: 'TicketNumber', title: 'رقم الأمر', render: (row) => <span className="font-mono text-xs">{row.TicketNumber}</span> },
          { key: 'Date', title: 'التاريخ' },
          { key: 'CustomerName', title: 'العميل', render: (row) => <span className="font-medium">{row.CustomerName}</span> },
          { key: 'CustomerPhone', title: 'الهاتف' },
          { key: 'DeviceModel', title: 'الجهاز' },
          { key: 'ProblemDesc', title: 'المشكلة', render: (row) => <span className="text-xs text-slate-500">{row.ProblemDesc?.substring(0, 40)}</span> },
          { key: 'TechnicianName', title: 'الفني', render: (row) => row.TechnicianName || '—' },
          { key: 'Status', title: 'الحالة', render: (row) => <Badge variant={statusVariants[row.Status]}>{statusLabels[row.Status]}</Badge> },
          { key: 'TotalCost', title: 'التكلفة', render: (row) => row.TotalCost > 0 ? <span className="font-bold">{row.TotalCost?.toFixed(2)}</span> : '—' },
        ]}
        data={tickets}
        keyField="TicketID"
        emptyMessage="لا توجد أوامر صيانة"
      />

      {/* Receive Modal */}
      <Modal isOpen={showReceive} onClose={() => setShowReceive(false)} title="استلام جهاز للصيانة" size="lg"
        footer={<><Button variant="secondary" onClick={() => setShowReceive(false)}>إلغاء</Button><Button onClick={handleReceive} icon={<Wrench size={16} />}>استلام</Button></>}
      >
        <div className="grid grid-cols-2 gap-4">
          <Select label="العميل (اختياري)" value={recvForm.CustomerID} onChange={(e) => setRecvForm({ ...recvForm, CustomerID: e.target.value, CustomerName: e.target.value ? customers.find(c => c.CustomerID === parseInt(e.target.value))?.Name || '' : recvForm.CustomerName, CustomerPhone: e.target.value ? customers.find(c => c.CustomerID === parseInt(e.target.value))?.Phone || '' : recvForm.CustomerPhone })}>
            <option value="">— عميل جديد —</option>
            {customers.map((c: any) => <option key={c.CustomerID} value={c.CustomerID}>{c.Name} ({c.Phone || '—'})</option>)}
          </Select>
          <Input label="رقم الهاتف" value={recvForm.CustomerPhone} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setRecvForm({ ...recvForm, CustomerPhone: e.target.value })} />
          <Input label="اسم العميل" value={recvForm.CustomerName} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setRecvForm({ ...recvForm, CustomerName: e.target.value })} />
          <Input label="نوع الجهاز" value={recvForm.DeviceModel} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setRecvForm({ ...recvForm, DeviceModel: e.target.value })} />
          <Input label="رقم IMEI" value={recvForm.DeviceIMEI} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setRecvForm({ ...recvForm, DeviceIMEI: e.target.value })} />
          <Input label="الموعد المتفق للتسليم" type="date" value={recvForm.AgreedDeliveryDate} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setRecvForm({ ...recvForm, AgreedDeliveryDate: e.target.value })} />
          <Input label="المبلغ المتفق عليه" type="number" value={recvForm.AgreedCost} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setRecvForm({ ...recvForm, AgreedCost: e.target.value })} />
          <Select label="الفني" value={recvForm.TechnicianID} onChange={(e) => setRecvForm({ ...recvForm, TechnicianID: e.target.value })}>
            <option value="">— بدون —</option>
            {employees.map((emp: any) => <option key={emp.EmployeeID} value={emp.EmployeeID}>{emp.Name} ({emp.Position || ''})</option>)}
          </Select>
          <div className="col-span-2"><Textarea label="المشكلة المشتكى منها" value={recvForm.ProblemDesc} onChange={(e: React.ChangeEvent<HTMLTextAreaElement>) => setRecvForm({ ...recvForm, ProblemDesc: e.target.value })} /></div>
          <Input label="المرفقات (شريحة، ميموري، جراب)" value={recvForm.Accessories} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setRecvForm({ ...recvForm, Accessories: e.target.value })} />
          <Input label="الرقم السري / نمط القفل" value={recvForm.DevicePassword} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setRecvForm({ ...recvForm, DevicePassword: e.target.value })} />
        </div>
      </Modal>

      {/* Deliver Modal */}
      <Modal isOpen={showDeliver} onClose={() => setShowDeliver(false)} title="تسليم جهاز" size="lg"
        footer={<><Button variant="secondary" onClick={() => setShowDeliver(false)}>إلغاء</Button><Button onClick={handleDeliver}>تسليم</Button></>}
      >
        <div className="space-y-4">
          <Select label="اختر الجهاز" value={selectedTicket} onChange={(e) => setSelectedTicket(e.target.value)}>
            <option value="">— اختر —</option>
            {openTickets.map((t: any) => <option key={t.TicketID} value={t.TicketID}>{t.TicketNumber} - {t.CustomerName} - {t.DeviceModel}</option>)}
          </Select>
          {selectedTicket && (() => {
            const t = openTickets.find(t => t.TicketID === parseInt(selectedTicket));
            return t ? (
              <div className="bg-slate-50 dark:bg-slate-800/50 rounded-lg p-4 space-y-2 text-sm">
                <div className="flex justify-between"><span className="text-slate-500">العميل:</span><span className="font-medium">{t.CustomerName}</span></div>
                <div className="flex justify-between"><span className="text-slate-500">الجهاز:</span><span>{t.DeviceModel}</span></div>
                <div className="flex justify-between"><span className="text-slate-500">المشكلة:</span><span>{t.ProblemDesc}</span></div>
                <div className="flex justify-between"><span className="text-slate-500">تكلفة القطع:</span><span className="font-bold">{t.PartsCost?.toFixed(2) || '0'}</span></div>
              </div>
            ) : null;
          })()}
          <div className="grid grid-cols-2 gap-4">
            <Input label="المصنعية (العمالة)" type="number" value={deliverForm.LaborCost} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setDeliverForm({ ...deliverForm, LaborCost: e.target.value })} />
            <Input label="المبلغ المدفوع" type="number" value={deliverForm.PaidAmount} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setDeliverForm({ ...deliverForm, PaidAmount: e.target.value })} />
            <Select label="طريقة الدفع" value={deliverForm.PaymentMethod} onChange={(e) => setDeliverForm({ ...deliverForm, PaymentMethod: e.target.value })}>
              <option value="cash">نقدي</option><option value="credit">آجل</option><option value="card">بطاقة</option>
            </Select>
            <Select label="الخزنة" value={deliverForm.CashAccountID} onChange={(e) => setDeliverForm({ ...deliverForm, CashAccountID: e.target.value })}>
              <option value="">— اختر —</option>
              {cashAccounts.map((ca: any) => <option key={ca.CashAccountID} value={ca.CashAccountID}>{ca.AccountName}</option>)}
            </Select>
          </div>
        </div>
      </Modal>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Plus, Trash2, Search } from 'lucide-react';
import { Button } from '../../components/ui/Button';
import { Input, Select } from '../../components/ui/Input';
import { Modal } from '../../components/ui/Modal';
import { Badge } from '../../components/ui/Badge';
import { DataTable } from '../../components/shared/DataTable';
import { useToastStore } from '../../components/ui/Toast';

interface PurchaseItem { ItemID: number; ItemName: string; IMEI?: string; Quantity: number; UnitCost: number; WarehouseID: number; }

export function PurchasesPage() {
  const { showToast } = useToastStore();
  const [purchases, setPurchases] = useState<any[]>([]);
  const [suppliers, setSuppliers] = useState<any[]>([]);
  const [items, setItems] = useState<any[]>([]);
  const [warehouses, setWarehouses] = useState<any[]>([]);
  const [cashAccounts, setCashAccounts] = useState<any[]>([]);
  const [showModal, setShowModal] = useState(false);
  const [search, setSearch] = useState('');

  const [supplierId, setSupplierId] = useState('');
  const [cart, setCart] = useState<PurchaseItem[]>([]);
  const [discount, setDiscount] = useState('');
  const [paidAmount, setPaidAmount] = useState('');
  const [paymentMethod, setPaymentMethod] = useState('cash');
  const [cashAccountId, setCashAccountId] = useState('');
  const [notes, setNotes] = useState('');

  const [selectedItem, setSelectedItem] = useState('');
  const [imei, setImei] = useState('');
  const [qty, setQty] = useState('1');
  const [unitCost, setUnitCost] = useState('');
  const [warehouseId, setWarehouseId] = useState('');

  const fetchData = async () => {
    const [p, su, it, wh, ca] = await Promise.all([
      window.api.invoke('purchases:list'),
      window.api.invoke('suppliers:list'),
      window.api.invoke('items:list', { search, isActive: 1 }),
      window.api.invoke('warehouses:list'),
      window.api.invoke('cashAccounts:list'),
    ]);
    setPurchases(p); setSuppliers(su); setItems(it); setWarehouses(wh); setCashAccounts(ca);
    if (wh.length > 0 && !warehouseId) setWarehouseId(wh[0].WarehouseID.toString());
  };

  useEffect(() => { fetchData(); }, [search]);

  const subtotal = cart.reduce((sum, item) => sum + item.Quantity * item.UnitCost, 0);
  const total = subtotal - (parseFloat(discount) || 0);

  const addToCart = () => {
    if (!selectedItem || !warehouseId) { showToast('error', 'اختر صنفاً ومخزناً'); return; }
    const item = items.find(i => i.ItemID === parseInt(selectedItem));
    if (!item) return;
    const newItem: PurchaseItem = { ItemID: item.ItemID, ItemName: item.ItemName, IMEI: imei || undefined, Quantity: parseInt(qty) || 1, UnitCost: parseFloat(unitCost) || 0, WarehouseID: parseInt(warehouseId) };
    setCart([...cart, newItem]);
    setSelectedItem(''); setImei(''); setQty('1'); setUnitCost('');
  };

  const handlePurchase = async () => {
    if (!supplierId) { showToast('error', 'اختر المورد'); return; }
    if (cart.length === 0) { showToast('error', 'السلة فارغة'); return; }
    const supplier = suppliers.find(s => s.SupplierID === parseInt(supplierId));
    if (supplier?.Status === 'suspended') { showToast('error', 'المورد موقوف'); return; }
    const activeFy = await window.api.invoke('fiscalYear:getActive');
    if (!activeFy) { showToast('error', 'لا توجد سنة مالية مفتوحة'); return; }

    const result = await window.api.invoke('purchases:create', {
      SupplierID: parseInt(supplierId),
      items: cart,
      Discount: parseFloat(discount) || 0,
      TaxAmount: 0,
      PaymentMethod: paymentMethod,
      PaidAmount: parseFloat(paidAmount) || 0,
      CashAccountID: cashAccountId ? parseInt(cashAccountId) : undefined,
      Notes: notes,
      userId: 1,
      fiscalYearId: activeFy.FiscalYearID,
    });
    if (result.success) {
      showToast('success', `تم إنشاء فاتورة الشراء - رقم: ${result.purchaseNumber}`);
      setShowModal(false);
      setCart([]); setSupplierId(''); setDiscount(''); setPaidAmount(''); setCashAccountId(''); setNotes('');
      fetchData();
    } else {
      showToast('error', result.message);
    }
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-bold text-slate-800 dark:text-white">المشتريات</h1>
        <Button onClick={() => setShowModal(true)} icon={<Plus size={16} />}>فاتورة شراء</Button>
      </div>

      <DataTable
        columns={[
          { key: 'PurchaseNumber', title: 'رقم الفاتورة', render: (row) => <span className="font-mono text-xs">{row.PurchaseNumber}</span> },
          { key: 'Date', title: 'التاريخ' },
          { key: 'SupplierName', title: 'المورد', render: (row) => <span className="font-medium">{row.SupplierName}</span> },
          { key: 'TotalAmount', title: 'الإجمالي', render: (row) => <span className="font-bold">{row.TotalAmount?.toFixed(2)}</span> },
          { key: 'PaidAmount', title: 'المدفوع', render: (row) => <span className="text-green-600">{row.PaidAmount?.toFixed(2)}</span> },
          { key: 'RemainingAmount', title: 'المتبقي', render: (row) => row.RemainingAmount > 0 ? <span className="text-red-600">{row.RemainingAmount?.toFixed(2)}</span> : '—' },
          { key: 'Status', title: 'الحالة', render: (row) => <Badge variant={row.Status === 'completed' ? 'green' : row.Status === 'partial' ? 'yellow' : 'red'}>{row.Status === 'completed' ? 'مكتملة' : row.Status === 'partial' ? 'جزئية' : 'غير مدفوعة'}</Badge> },
        ]}
        data={purchases}
        keyField="PurchaseID"
        emptyMessage="لا توجد فواتير شراء"
      />

      <Modal isOpen={showModal} onClose={() => setShowModal(false)} title="فاتورة شراء جديدة" size="xl"
        footer={<><Button variant="secondary" onClick={() => setShowModal(false)}>إلغاء</Button><Button onClick={handlePurchase}>حفظ</Button></>}
      >
        <div className="space-y-4">
          <div className="grid grid-cols-3 gap-3">
            <Select label="المورد" value={supplierId} onChange={(e) => setSupplierId(e.target.value)}>
              <option value="">— اختر —</option>
              {suppliers.map((s: any) => <option key={s.SupplierID} value={s.SupplierID}>{s.Name} (رصيد: {s.Balance?.toFixed(2)})</option>)}
            </Select>
            <Select label="المخزن المستلم فيه" value={warehouseId} onChange={(e) => setWarehouseId(e.target.value)}>
              {warehouses.map((w: any) => <option key={w.WarehouseID} value={w.WarehouseID}>{w.WarehouseName}</option>)}
            </Select>
            <Select label="الخزنة" value={cashAccountId} onChange={(e) => setCashAccountId(e.target.value)}>
              <option value="">— اختر —</option>
              {cashAccounts.map((ca: any) => <option key={ca.CashAccountID} value={ca.CashAccountID}>{ca.AccountName}</option>)}
            </Select>
          </div>

          <div className="bg-slate-50 dark:bg-slate-800/50 rounded-lg p-3 border border-slate-200 dark:border-slate-700">
            <div className="grid grid-cols-12 gap-2 items-end">
              <div className="col-span-4">
                <Select label="الصنف" value={selectedItem} onChange={(e) => { setSelectedItem(e.target.value); const it = items.find(i => i.ItemID === parseInt(e.target.value)); setUnitCost(it?.CostPrice?.toString() || ''); }}>
                  <option value="">— اختر —</option>
                  {items.map((it: any) => <option key={it.ItemID} value={it.ItemID}>{it.ItemName} {it.IsSerialized ? '(IMEI)' : ''}</option>)}
                </Select>
              </div>
              {items.find(i => i.ItemID === parseInt(selectedItem))?.IsSerialized && (
                <div className="col-span-3"><Input label="IMEI" value={imei} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setImei(e.target.value)} /></div>
              )}
              {!items.find(i => i.ItemID === parseInt(selectedItem))?.IsSerialized && (
                <div className="col-span-2"><Input label="الكمية" type="number" value={qty} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setQty(e.target.value)} /></div>
              )}
              <div className="col-span-2"><Input label="التكلفة" type="number" value={unitCost} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setUnitCost(e.target.value)} /></div>
              <div className="col-span-2"><Button onClick={addToCart} icon={<Plus size={14} />} size="sm">إضافة</Button></div>
            </div>
          </div>

          <div className="rounded-lg border border-slate-200 dark:border-slate-700 overflow-hidden">
            <table className="w-full text-sm">
              <thead><tr className="bg-slate-50 dark:bg-slate-800/50"><th className="px-3 py-2 text-right">الصنف</th><th className="px-3 py-2 text-right">IMEI</th><th className="px-3 py-2 text-right">كمية</th><th className="px-3 py-2 text-right">تكلفة</th><th className="px-3 py-2 text-right">إجمالي</th><th className="px-3 py-2"></th></tr></thead>
              <tbody>
                {cart.length === 0 ? <tr><td colSpan={6} className="px-3 py-4 text-center text-slate-400">السلة فارغة</td></tr> :
                  cart.map((item, idx) => (
                    <tr key={idx} className="border-t border-slate-100 dark:border-slate-700/50">
                      <td className="px-3 py-2 font-medium">{item.ItemName}</td>
                      <td className="px-3 py-2 font-mono text-xs">{item.IMEI || '—'}</td>
                      <td className="px-3 py-2">{item.Quantity}</td>
                      <td className="px-3 py-2">{item.UnitCost.toFixed(2)}</td>
                      <td className="px-3 py-2 font-bold">{(item.Quantity * item.UnitCost).toFixed(2)}</td>
                      <td className="px-3 py-2"><button onClick={() => setCart(cart.filter((_, i) => i !== idx))} className="text-red-500"><Trash2 size={14} /></button></td>
                    </tr>
                  ))
                }
              </tbody>
            </table>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <div className="flex justify-between text-sm"><span className="text-slate-500">الإجمالي الفرعي</span><span className="font-medium">{subtotal.toFixed(2)}</span></div>
              <div className="flex items-center gap-2"><span className="text-sm text-slate-500">خصم</span><input type="number" value={discount} onChange={(e) => setDiscount(e.target.value)} className="w-24 px-2 py-1 rounded border border-slate-300 dark:border-slate-600 bg-white dark:bg-slate-800 text-sm" /></div>
              <div className="flex justify-between text-lg font-bold border-t border-slate-200 dark:border-slate-700 pt-2"><span>الإجمالي</span><span className="text-primary-600">{total.toFixed(2)}</span></div>
            </div>
            <div className="space-y-3">
              <Select label="طريقة الدفع" value={paymentMethod} onChange={(e) => setPaymentMethod(e.target.value)}>
                <option value="cash">نقدي</option><option value="credit">آجل</option>
              </Select>
              <Input label="المبلغ المدفوع" type="number" value={paidAmount} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setPaidAmount(e.target.value)} />
            </div>
          </div>
        </div>
      </Modal>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Plus, DollarSign, FileText } from 'lucide-react';
import { Button } from '../../components/ui/Button';
import { Input, Select, Textarea } from '../../components/ui/Input';
import { Modal } from '../../components/ui/Modal';
import { Badge } from '../../components/ui/Badge';
import { DataTable } from '../../components/shared/DataTable';
import { useToastStore } from '../../components/ui/Toast';

export function PayrollPage() {
  const { showToast } = useToastStore();
  const [tab, setTab] = useState<'salaries' | 'advances' | 'deductions'>('salaries');
  const [salaries, setSalaries] = useState<any[]>([]);
  const [advances, setAdvances] = useState<any[]>([]);
  const [deductions, setDeductions] = useState<any[]>([]);
  const [employees, setEmployees] = useState<any[]>([]);
  const [cashAccounts, setCashAccounts] = useState<any[]>([]);
  const [items, setItems] = useState<any[]>([]);

  const [showSalaryModal, setShowSalaryModal] = useState(false);
  const [showAdvanceModal, setShowAdvanceModal] = useState(false);
  const [showDeductionModal, setShowDeductionModal] = useState(false);

  const [salaryForm, setSalaryForm] = useState({ EmployeeID: '', Month: new Date().toISOString().substring(0, 7), CashAccountID: '', PaidAmount: '' });
  const [advanceForm, setAdvanceForm] = useState({ EmployeeID: '', Amount: '', Reason: '', CashAccountID: '' });
  const [deductionForm, setDeductionForm] = useState({ EmployeeID: '', Amount: '', Reason: 'absence', DamagedItemID: '', DamageCostType: 'cost', Notes: '' });

  const fetchData = async () => {
    const [s, a, d, em, ca, it] = await Promise.all([
      window.api.invoke('salaries:list'),
      window.api.invoke('advances:list'),
      window.api.invoke('deductions:list'),
      window.api.invoke('employees:list', { isActive: 1 }),
      window.api.invoke('cashAccounts:list'),
      window.api.invoke('items:list', { isActive: 1 }),
    ]);
    setSalaries(s); setAdvances(a); setDeductions(d); setEmployees(em); setCashAccounts(ca); setItems(it);
  };

  useEffect(() => { fetchData(); }, []);

  const handlePaySalary = async () => {
    if (!salaryForm.EmployeeID) { showToast('error', 'اختر موظفاً'); return; }
    const activeFy = await window.api.invoke('fiscalYear:getActive');
    if (!activeFy) { showToast('error', 'لا توجد سنة مالية مفتوحة'); return; }
    const result = await window.api.invoke('salaries:create', {
      EmployeeID: parseInt(salaryForm.EmployeeID),
      Month: salaryForm.Month,
      CashAccountID: salaryForm.CashAccountID ? parseInt(salaryForm.CashAccountID) : undefined,
      PaidAmount: parseFloat(salaryForm.PaidAmount) || 0,
      userId: 1,
      fiscalYearId: activeFy.FiscalYearID,
    });
    if (result.success) {
      showToast('success', `صافي الراتب: ${result.netSalary?.toFixed(2)} - المدفوع: ${result.paidAmount?.toFixed(2)}`);
      setShowSalaryModal(false);
      setSalaryForm({ ...salaryForm, EmployeeID: '', PaidAmount: '' });
      fetchData();
    }
  };

  const handleAdvance = async () => {
    if (!advanceForm.EmployeeID || !advanceForm.Amount || !advanceForm.CashAccountID) { showToast('error', 'أكمل البيانات'); return; }
    const activeFy = await window.api.invoke('fiscalYear:getActive');
    if (!activeFy) { showToast('error', 'لا توجد سنة مالية مفتوحة'); return; }
    await window.api.invoke('advances:create', {
      EmployeeID: parseInt(advanceForm.EmployeeID),
      Amount: parseFloat(advanceForm.Amount),
      Reason: advanceForm.Reason,
      CashAccountID: parseInt(advanceForm.CashAccountID),
      userId: 1,
      fiscalYearId: activeFy.FiscalYearID,
    });
    showToast('success', 'تم صرف السلفية');
    setShowAdvanceModal(false);
    setAdvanceForm({ EmployeeID: '', Amount: '', Reason: '', CashAccountID: '' });
    fetchData();
  };

  const handleDeduction = async () => {
    if (!deductionForm.EmployeeID) { showToast('error', 'اختر موظفاً'); return; }
    const activeFy = await window.api.invoke('fiscalYear:getActive');
    if (!activeFy) { showToast('error', 'لا توجد سنة مالية مفتوحة'); return; }
    const result = await window.api.invoke('deductions:create', {
      EmployeeID: parseInt(deductionForm.EmployeeID),
      Amount: parseFloat(deductionForm.Amount) || 0,
      Reason: deductionForm.Reason,
      DamagedItemID: deductionForm.DamagedItemID ? parseInt(deductionForm.DamagedItemID) : undefined,
      DamageCostType: deductionForm.DamageCostType,
      Notes: deductionForm.Notes,
      userId: 1,
      fiscalYearId: activeFy.FiscalYearID,
    });
    if (result.success) {
      showToast('success', `تم تسجيل الخصم - المبلغ: ${result.amount?.toFixed(2)}`);
      setShowDeductionModal(false);
      setDeductionForm({ EmployeeID: '', Amount: '', Reason: 'absence', DamagedItemID: '', DamageCostType: 'cost', Notes: '' });
      fetchData();
    }
  };

  const deductionReasons = [
    { value: 'absence', label: 'غياب' },
    { value: 'negligence', label: 'تقصير في العمل' },
    { value: 'damage', label: 'إتلاف قطعة غيار' },
    { value: 'other', label: 'سبب آخر' },
  ];

  return (
    <div className="space-y-4">
      <h1 className="text-2xl font-bold text-slate-800 dark:text-white">الرواتب والسلفيات</h1>

      <div className="flex gap-2">
        <button onClick={() => setTab('salaries')} className={`px-4 py-2 rounded-lg text-sm font-medium ${tab === 'salaries' ? 'bg-primary-600 text-white' : 'bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-300'}`}>الرواتب</button>
        <button onClick={() => setTab('advances')} className={`px-4 py-2 rounded-lg text-sm font-medium ${tab === 'advances' ? 'bg-primary-600 text-white' : 'bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-300'}`}>السلفيات</button>
        <button onClick={() => setTab('deductions')} className={`px-4 py-2 rounded-lg text-sm font-medium ${tab === 'deductions' ? 'bg-primary-600 text-white' : 'bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-300'}`}>الخصومات</button>
      </div>

      {tab === 'salaries' && (
        <div className="space-y-4">
          <div className="flex justify-end"><Button onClick={() => setShowSalaryModal(true)} icon={<DollarSign size={16} />}>صرف راتب</Button></div>
          <DataTable
            columns={[
              { key: 'EmployeeName', title: 'الموظف', render: (row) => <span className="font-medium">{row.EmployeeName}</span> },
              { key: 'Month', title: 'الشهر' },
              { key: 'NetSalary', title: 'صافي الراتب', render: (row) => <span className="font-bold">{row.NetSalary?.toFixed(2)}</span> },
              { key: 'CommissionsTotal', title: 'العمولات', render: (row) => row.CommissionsTotal?.toFixed(2) || '0' },
              { key: 'DeductionsTotal', title: 'الخصومات', render: (row) => <span className="text-red-600">{row.DeductionsTotal?.toFixed(2) || '0'}</span> },
              { key: 'AdvancesTotal', title: 'السلف', render: (row) => <span className="text-orange-600">{row.AdvancesTotal?.toFixed(2) || '0'}</span> },
              { key: 'PaidAmount', title: 'المدفوع', render: (row) => <span className="text-green-600">{row.PaidAmount?.toFixed(2)}</span> },
              { key: 'Status', title: 'الحالة', render: (row) => <Badge variant={row.Status === 'paid' ? 'green' : row.Status === 'partial' ? 'yellow' : 'gray'}>{row.Status === 'paid' ? 'مدفوع' : row.Status === 'partial' ? 'جزئي' : 'معلق'}</Badge> },
            ]}
            data={salaries}
            keyField="SalaryID"
            emptyMessage="لا توجد رواتب"
          />
        </div>
      )}

      {tab === 'advances' && (
        <div className="space-y-4">
          <div className="flex justify-end"><Button onClick={() => setShowAdvanceModal(true)} icon={<Plus size={16} />}>سلفية جديدة</Button></div>
          <DataTable
            columns={[
              { key: 'EmployeeName', title: 'الموظف', render: (row) => <span className="font-medium">{row.EmployeeName}</span> },
              { key: 'Date', title: 'التاريخ' },
              { key: 'Amount', title: 'المبلغ', render: (row) => <span className="font-bold">{row.Amount?.toFixed(2)}</span> },
              { key: 'Reason', title: 'السبب' },
              { key: 'IsDeducted', title: 'مخصومة', render: (row) => <Badge variant={row.IsDeducted ? 'green' : 'yellow'}>{row.IsDeducted ? 'نعم' : 'لا'}</Badge> },
            ]}
            data={advances}
            keyField="AdvanceID"
            emptyMessage="لا توجد سلفيات"
          />
        </div>
      )}

      {tab === 'deductions' && (
        <div className="space-y-4">
          <div className="flex justify-end"><Button onClick={() => setShowDeductionModal(true)} icon={<Plus size={16} />}>خصم جديد</Button></div>
          <DataTable
            columns={[
              { key: 'EmployeeName', title: 'الموظف', render: (row) => <span className="font-medium">{row.EmployeeName}</span> },
              { key: 'Date', title: 'التاريخ' },
              { key: 'Amount', title: 'المبلغ', render: (row) => <span className="font-bold text-red-600">{row.Amount?.toFixed(2)}</span> },
              { key: 'Reason', title: 'السبب', render: (row) => { const labels: any = { absence: 'غياب', negligence: 'تقصير', damage: 'إتلاف', other: 'أخرى' }; return labels[row.Reason] || row.Reason; } },
              { key: 'DamagedItemName', title: 'الصنف المتلف', render: (row) => row.DamagedItemName || '—' },
              { key: 'IsDeducted', title: 'مخصوم', render: (row) => <Badge variant={row.IsDeducted ? 'green' : 'yellow'}>{row.IsDeducted ? 'نعم' : 'لا'}</Badge> },
            ]}
            data={deductions}
            keyField="DeductionID"
            emptyMessage="لا توجد خصومات"
          />
        </div>
      )}

      {/* Salary Modal */}
      <Modal isOpen={showSalaryModal} onClose={() => setShowSalaryModal(false)} title="صرف راتب"
        footer={<><Button variant="secondary" onClick={() => setShowSalaryModal(false)}>إلغاء</Button><Button onClick={handlePaySalary}>صرف</Button></>}
      >
        <div className="space-y-4">
          <Select label="الموظف" value={salaryForm.EmployeeID} onChange={(e) => setSalaryForm({ ...salaryForm, EmployeeID: e.target.value })}>
            <option value="">— اختر —</option>
            {employees.map((emp: any) => <option key={emp.EmployeeID} value={emp.EmployeeID}>{emp.Name} (رصيد: {emp.Balance?.toFixed(2)})</option>)}
          </Select>
          <Input label="الشهر" type="month" value={salaryForm.Month} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setSalaryForm({ ...salaryForm, Month: e.target.value })} />
          <Select label="الخزنة" value={salaryForm.CashAccountID} onChange={(e) => setSalaryForm({ ...salaryForm, CashAccountID: e.target.value })}>
            <option value="">— اختر —</option>
            {cashAccounts.map((ca: any) => <option key={ca.CashAccountID} value={ca.CashAccountID}>{ca.AccountName} ({ca.Balance?.toFixed(2)})</option>)}
          </Select>
          <Input label="المبلغ المدفوع (اتركه فارغاً لدفع كامل)" type="number" value={salaryForm.PaidAmount} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setSalaryForm({ ...salaryForm, PaidAmount: e.target.value })} />
        </div>
      </Modal>

      {/* Advance Modal */}
      <Modal isOpen={showAdvanceModal} onClose={() => setShowAdvanceModal(false)} title="صرف سلفية"
        footer={<><Button variant="secondary" onClick={() => setShowAdvanceModal(false)}>إلغاء</Button><Button onClick={handleAdvance}>صرف</Button></>}
      >
        <div className="space-y-4">
          <Select label="الموظف" value={advanceForm.EmployeeID} onChange={(e) => setAdvanceForm({ ...advanceForm, EmployeeID: e.target.value })}>
            <option value="">— اختر —</option>
            {employees.map((emp: any) => <option key={emp.EmployeeID} value={emp.EmployeeID}>{emp.Name}</option>)}
          </Select>
          <Input label="المبلغ" type="number" value={advanceForm.Amount} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setAdvanceForm({ ...advanceForm, Amount: e.target.value })} />
          <Input label="السبب" value={advanceForm.Reason} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setAdvanceForm({ ...advanceForm, Reason: e.target.value })} />
          <Select label="الخزنة" value={advanceForm.CashAccountID} onChange={(e) => setAdvanceForm({ ...advanceForm, CashAccountID: e.target.value })}>
            <option value="">— اختر —</option>
            {cashAccounts.map((ca: any) => <option key={ca.CashAccountID} value={ca.CashAccountID}>{ca.AccountName}</option>)}
          </Select>
        </div>
      </Modal>

      {/* Deduction Modal */}
      <Modal isOpen={showDeductionModal} onClose={() => setShowDeductionModal(false)} title="تسجيل خصم"
        footer={<><Button variant="secondary" onClick={() => setShowDeductionModal(false)}>إلغاء</Button><Button onClick={handleDeduction}>حفظ</Button></>}
      >
        <div className="space-y-4">
          <Select label="الموظف" value={deductionForm.EmployeeID} onChange={(e) => setDeductionForm({ ...deductionForm, EmployeeID: e.target.value })}>
            <option value="">— اختر —</option>
            {employees.map((emp: any) => <option key={emp.EmployeeID} value={emp.EmployeeID}>{emp.Name}</option>)}
          </Select>
          <Select label="سبب الخصم" value={deductionForm.Reason} onChange={(e) => setDeductionForm({ ...deductionForm, Reason: e.target.value, DamagedItemID: '' })}>
            {deductionReasons.map(r => <option key={r.value} value={r.value}>{r.label}</option>)}
          </Select>
          {deductionForm.Reason === 'damage' && (
            <>
              <Select label="الصنف المتلف" value={deductionForm.DamagedItemID} onChange={(e) => setDeductionForm({ ...deductionForm, DamagedItemID: e.target.value })}>
                <option value="">— اختر —</option>
                {items.map((it: any) => <option key={it.ItemID} value={it.ItemID}>{it.ItemName} (تكلفة: {it.CostPrice?.toFixed(2)} - بيع: {it.SalePrice?.toFixed(2)})</option>)}
              </Select>
              <Select label="نوع الخصم" value={deductionForm.DamageCostType} onChange={(e) => setDeductionForm({ ...deductionForm, DamageCostType: e.target.value })}>
                <option value="cost">بسعر التكلفة</option>
                <option value="sale">بسعر البيع</option>
                <option value="manual">يدوي</option>
              </Select>
            </>
          )}
          {(deductionForm.Reason !== 'damage' || deductionForm.DamageCostType === 'manual') && (
            <Input label="المبلغ" type="number" value={deductionForm.Amount} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setDeductionForm({ ...deductionForm, Amount: e.target.value })} />
          )}
          <Textarea label="ملاحظات" value={deductionForm.Notes} onChange={(e: React.ChangeEvent<HTMLTextAreaElement>) => setDeductionForm({ ...deductionForm, Notes: e.target.value })} />
        </div>
      </Modal>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Plus, DollarSign } from 'lucide-react';
import { Button } from '../../components/ui/Button';
import { Input, Select } from '../../components/ui/Input';
import { Modal } from '../../components/ui/Modal';
import { Badge } from '../../components/ui/Badge';
import { DataTable } from '../../components/shared/DataTable';
import { useToastStore } from '../../components/ui/Toast';

export function RentPage() {
  const { showToast } = useToastStore();
  const [rents, setRents] = useState<any[]>([]);
  const [payments, setPayments] = useState<any[]>([]);
  const [cashAccounts, setCashAccounts] = useState<any[]>([]);
  const [showModal, setShowModal] = useState(false);
  const [showPayModal, setShowPayModal] = useState(false);
  const [selectedPayment, setSelectedPayment] = useState<any>(null);
  const [payCashAccount, setPayCashAccount] = useState('');

  const [form, setForm] = useState({
    RentName: '', RentType: 'expense', Amount: '', Period: 'monthly',
    StartDate: new Date().toISOString().split('T')[0], PartyName: '', PartyPhone: '', Notes: '',
  });

  const fetchData = async () => {
    const [r, p, ca] = await Promise.all([
      window.api.invoke('rents:list'),
      window.api.invoke('rentPayments:list'),
      window.api.invoke('cashAccounts:list'),
    ]);
    setRents(r.filter((rent: any) => rent.IsActive === 1));
    setPayments(p);
    setCashAccounts(ca);
  };

  useEffect(() => { fetchData(); }, []);

  const handleCreate = async () => {
    if (!form.RentName || !form.Amount) { showToast('error', 'أكمل البيانات'); return; }
    await window.api.invoke('rents:create', { ...form, Amount: parseFloat(form.Amount) });
    showToast('success', 'تم إضافة الإيجار');
    setShowModal(false);
    setForm({ RentName: '', RentType: 'expense', Amount: '', Period: 'monthly', StartDate: new Date().toISOString().split('T')[0], PartyName: '', PartyPhone: '', Notes: '' });
    fetchData();
  };

  const handleGenerate = async (rentId: number) => {
    const activeFy = await window.api.invoke('fiscalYear:getActive');
    if (!activeFy) { showToast('error', 'لا توجد سنة مالية مفتوحة'); return; }
    await window.api.invoke('rents:generatePayments', rentId, 12, 1, activeFy.FiscalYearID);
    showToast('success', 'تم توليد دفعات الإيجار');
    fetchData();
  };

  const handlePay = async () => {
    if (!payCashAccount) { showToast('error', 'اختر الخزنة'); return; }
    const activeFy = await window.api.invoke('fiscalYear:getActive');
    if (!activeFy) { showToast('error', 'لا توجد سنة مالية مفتوحة'); return; }
    await window.api.invoke('rentPayments:pay', {
      RentPaymentID: selectedPayment.RentPaymentID,
      CashAccountID: parseInt(payCashAccount),
      userId: 1,
      fiscalYearId: activeFy.FiscalYearID,
    });
    showToast('success', 'تم دفع الإيجار');
    setShowPayModal(false);
    setSelectedPayment(null);
    setPayCashAccount('');
    fetchData();
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-bold text-slate-800 dark:text-white">إدارة الإيجارات</h1>
        <Button onClick={() => setShowModal(true)} icon={<Plus size={16} />}>إيجار جديد</Button>
      </div>

      {/* Rents */}
      <div className="space-y-2">
        {rents.map((rent: any) => (
          <div key={rent.RentID} className="bg-white dark:bg-slate-800 rounded-xl p-4 border border-slate-200 dark:border-slate-700 flex items-center justify-between">
            <div>
              <div className="flex items-center gap-2">
                <span className="font-medium text-slate-800 dark:text-white">{rent.RentName}</span>
                <Badge variant={rent.RentType === 'expense' ? 'red' : 'green'}>{rent.RentType === 'expense' ? 'علينا' : 'لنا'}</Badge>
              </div>
              <div className="text-sm text-slate-500 mt-1">
                {rent.Amount?.toFixed(2)} / {rent.Period === 'monthly' ? 'شهرياً' : 'سنوياً'}
                {rent.PartyName && ` - ${rent.PartyName}`}
              </div>
            </div>
            <Button size="sm" variant="secondary" onClick={() => handleGenerate(rent.RentID)}>توليد دفعات</Button>
          </div>
        ))}
        {rents.length === 0 && <p className="text-center text-slate-400 py-8">لا توجد إيجارات</p>}
      </div>

      {/* Payments */}
      <div className="mt-6">
        <h2 className="text-lg font-semibold text-slate-800 dark:text-white mb-3">دفعات الإيجار</h2>
        <DataTable
          columns={[
            { key: 'PeriodLabel', title: 'الفترة', render: (row) => <span className="font-medium">{row.PeriodLabel}</span> },
            { key: 'RentName', title: 'الإيجار' },
            { key: 'Amount', title: 'المبلغ', render: (row) => <span className="font-bold">{row.Amount?.toFixed(2)}</span> },
            { key: 'DueDate', title: 'تاريخ الاستحقاق' },
            { key: 'Status', title: 'الحالة', render: (row) => <Badge variant={row.Status === 'paid' ? 'green' : 'red'}>{row.Status === 'paid' ? 'مدفوع' : 'مستحق'}</Badge> },
            { key: 'actions', title: '', render: (row) => row.Status === 'pending' ? <button onClick={() => { setSelectedPayment(row); setShowPayModal(true); }} className="text-xs text-green-600 hover:underline">دفع</button> : null },
          ]}
          data={payments}
          keyField="RentPaymentID"
          emptyMessage="لا توجد دفعات"
        />
      </div>

      {/* Create Modal */}
      <Modal isOpen={showModal} onClose={() => setShowModal(false)} title="إيجار جديد"
        footer={<><Button variant="secondary" onClick={() => setShowModal(false)}>إلغاء</Button><Button onClick={handleCreate}>حفظ</Button></>}
      >
        <div className="grid grid-cols-2 gap-4">
          <Input label="اسم الإيجار" value={form.RentName} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setForm({ ...form, RentName: e.target.value })} />
          <Select label="النوع" value={form.RentType} onChange={(e) => setForm({ ...form, RentType: e.target.value })}>
            <option value="expense">إيجار علينا (مصروف)</option>
            <option value="income">إيجار لنا (إيراد)</option>
          </Select>
          <Input label="المبلغ" type="number" value={form.Amount} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setForm({ ...form, Amount: e.target.value })} />
          <Select label="الدورية" value={form.Period} onChange={(e) => setForm({ ...form, Period: e.target.value })}>
            <option value="monthly">شهري</option>
            <option value="yearly">سنوي</option>
          </Select>
          <Input label="تاريخ البداية" type="date" value={form.StartDate} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setForm({ ...form, StartDate: e.target.value })} />
          <Input label="اسم الطرف الآخر" value={form.PartyName} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setForm({ ...form, PartyName: e.target.value })} />
          <Input label="هاتف الطرف" value={form.PartyPhone} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setForm({ ...form, PartyPhone: e.target.value })} />
        </div>
      </Modal>

      {/* Pay Modal */}
      <Modal isOpen={showPayModal} onClose={() => setShowPayModal(false)} title="دفع إيجار" size="sm"
        footer={<><Button variant="secondary" onClick={() => setShowPayModal(false)}>إلغاء</Button><Button onClick={handlePay}>دفع</Button></>}
      >
        {selectedPayment && (
          <div className="space-y-4">
            <div className="bg-slate-50 dark:bg-slate-800/50 rounded-lg p-4 space-y-2 text-sm">
              <div className="flex justify-between"><span className="text-slate-500">الفترة:</span><span className="font-medium">{selectedPayment.PeriodLabel}</span></div>
              <div className="flex justify-between"><span className="text-slate-500">المبلغ:</span><span className="font-bold">{selectedPayment.Amount?.toFixed(2)}</span></div>
            </div>
            <Select label="الخزنة/البنك" value={payCashAccount} onChange={(e) => setPayCashAccount(e.target.value)}>
              <option value="">— اختر —</option>
              {cashAccounts.map((ca: any) => <option key={ca.CashAccountID} value={ca.CashAccountID}>{ca.AccountName} ({ca.Balance?.toFixed(2)})</option>)}
            </Select>
          </div>
        )}
      </Modal>
    </div>
  );
}

