import { ipcMain, dialog, app } from 'electron';
import { getDb, closeDb } from '../database/connection';
import path from 'node:path';
import fs from 'node:fs';

export function registerBackupHandlers() {
  // Manual backup
  ipcMain.handle('backup:create', async () => {
    const db = getDb();
    const dbPath = db.name;

    const result = await dialog.showSaveDialog({
      title: 'حفظ نسخة احتياطية',
      defaultPath: `mobile_shop_backup_${new Date().toISOString().split('T')[0]}.db`,
      filters: [{ name: 'Database', extensions: ['db'] }],
    });

    if (result.canceled || !result.filePath) {
      return { success: false, message: 'تم الإلغاء' };
    }

    try {
      // Use SQLite backup API
      const backup = db.backup(result.filePath);
      backup.step(-1); // Complete in one step
      backup.finish();

      return { success: true, path: result.filePath };
    } catch (err: any) {
      return { success: false, message: err.message };
    }
  });

  // Restore from backup
  ipcMain.handle('backup:restore', async () => {
    const result = await dialog.showOpenDialog({
      title: 'استعادة من نسخة احتياطية',
      filters: [{ name: 'Database', extensions: ['db'] }],
      properties: ['openFile'],
    });

    if (result.canceled || result.filePaths.length === 0) {
      return { success: false, message: 'تم الإلغاء' };
    }

    const backupPath = result.filePaths[0];
    const dbPath = path.join(app.getPath('userData'), 'mobile_shop.db');

    try {
      closeDb();

      // Copy backup file over current DB
      fs.copyFileSync(backupPath, dbPath);

      return { success: true, message: 'تمت الاستعادة - يرجى إعادة تشغيل التطبيق' };
    } catch (err: any) {
      return { success: false, message: err.message };
    }
  });

  // Get DB info
  ipcMain.handle('backup:info', async () => {
    const db = getDb();
    const dbPath = db.name;
    let size = 0;
    try {
      const stats = fs.statSync(dbPath);
      size = stats.size;
    } catch {}
    return {
      path: dbPath,
      size: size,
      sizeFormatted: size > 1024 * 1024 ? `${(size / 1024 / 1024).toFixed(2)} MB` : `${(size / 1024).toFixed(2)} KB`,
    };
  });
}

import { useState, useEffect } from 'react';
import { TrendingUp, Wrench, PackageX, Wallet, AlertTriangle, Clock } from 'lucide-react';
import { Badge } from '../../components/ui/Badge';

export function Dashboard() {
  const [stats, setStats] = useState<any>(null);

  useEffect(() => {
    (async () => {
      const data = await window.api.invoke('reports:dashboard');
      setStats(data);
    })();
  }, []);

  const cards = [
    { label: 'مبيعات اليوم', value: `${(stats?.todaySales || 0).toFixed(2)} ج.م`, icon: TrendingUp, color: 'bg-green-500' },
    { label: 'صيانة معلقة', value: stats?.pendingMaintenance || 0, icon: Wrench, color: 'bg-orange-500' },
    { label: 'مخزون منخفض', value: stats?.lowStock || 0, icon: PackageX, color: 'bg-red-500' },
    { label: 'رصيد الخزائن', value: `${(stats?.cashBalance || 0).toFixed(2)} ج.م`, icon: Wallet, color: 'bg-blue-500' },
  ];

  return (
    <div className="space-y-6">
      <h1 className="text-2xl font-bold text-slate-800 dark:text-white">لوحة التحكم</h1>

      {/* Alerts */}
      {(stats?.overdueMaintenance > 0 || stats?.lowStock > 0) && (
        <div className="bg-orange-50 dark:bg-orange-900/20 border border-orange-200 dark:border-orange-800 rounded-xl p-4 flex items-center gap-3">
          <AlertTriangle size={20} className="text-orange-500 flex-shrink-0" />
          <div className="text-sm text-orange-700 dark:text-orange-300">
            {stats?.overdueMaintenance > 0 && <span>يوجد {stats.overdueMaintenance} أمر صيانة متأخر عن موعد التسليم. </span>}
            {stats?.lowStock > 0 && <span>يوجد {stats.lowStock} صنف اقترب من النفاد.</span>}
          </div>
        </div>
      )}

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        {cards.map((card) => {
          const Icon = card.icon;
          return (
            <div key={card.label} className="bg-white dark:bg-slate-800 rounded-xl p-5 shadow-sm border border-slate-200 dark:border-slate-700">
              <div className="flex items-center justify-between mb-3">
                <div className={`p-2 rounded-lg ${card.color}`}>
                  <Icon size={20} className="text-white" />
                </div>
              </div>
              <div className="text-2xl font-bold text-slate-800 dark:text-white">{card.value}</div>
              <div className="text-sm text-slate-500 dark:text-slate-400 mt-1">{card.label}</div>
            </div>
          );
        })}
      </div>

      {/* Monthly Sales Chart */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white dark:bg-slate-800 rounded-xl p-6 shadow-sm border border-slate-200 dark:border-slate-700">
          <h2 className="text-lg font-semibold text-slate-800 dark:text-white mb-4">المبيعات الشهرية</h2>
          {stats?.monthlySales?.length > 0 ? (
            <div className="flex items-end gap-2 h-48">
              {stats.monthlySales.map((item: any, idx: number) => {
                const maxVal = Math.max(...stats.monthlySales.map((s: any) => s.total), 1);
                const height = (item.total / maxVal) * 100;
                return (
                  <div key={idx} className="flex-1 flex flex-col items-center gap-1">
                    <div className="w-full bg-primary-600 rounded-t-lg" style={{ height: `${height}%`, minHeight: '4px' }} title={item.total.toFixed(2)} />
                    <span className="text-[10px] text-slate-400 whitespace-nowrap">{item.month}</span>
                  </div>
                );
              })}
            </div>
          ) : (
            <div className="h-48 flex items-center justify-center text-slate-400">لا توجد بيانات</div>
          )}
        </div>

        {/* Recent Operations */}
        <div className="bg-white dark:bg-slate-800 rounded-xl p-6 shadow-sm border border-slate-200 dark:border-slate-700">
          <h2 className="text-lg font-semibold text-slate-800 dark:text-white mb-4">أحدث العمليات</h2>
          <div className="space-y-2">
            {stats?.recentSales?.map((sale: any, idx: number) => (
              <div key={idx} className="flex items-center justify-between py-2 border-b border-slate-100 dark:border-slate-700/50 last:border-0">
                <div>
                  <span className="text-sm font-medium text-slate-700 dark:text-slate-200">{sale.CustomerName || 'عميل نقدي'}</span>
                  <span className="text-xs text-slate-400 mr-2">{sale.SaleNumber}</span>
                </div>
                <span className="text-sm font-bold text-green-600">{sale.TotalAmount?.toFixed(2)}</span>
              </div>
            ))}
            {stats?.recentMaintenance?.map((ticket: any, idx: number) => (
              <div key={`m${idx}`} className="flex items-center justify-between py-2 border-b border-slate-100 dark:border-slate-700/50 last:border-0">
                <div>
                  <span className="text-sm font-medium text-slate-700 dark:text-slate-200">{ticket.DeviceModel}</span>
                  <span className="text-xs text-slate-400 mr-2">{ticket.CustomerName}</span>
                </div>
                <Badge variant="blue">{ticket.Status}</Badge>
              </div>
            ))}
            {!stats?.recentSales?.length && !stats?.recentMaintenance?.length && (
              <p className="text-center text-slate-400 py-4">لا توجد عمليات بعد</p>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { FileText, Calendar, Printer } from 'lucide-react';
import { Button } from '../../components/ui/Button';
import { Input } from '../../components/ui/Input';
import { Badge } from '../../components/ui/Badge';
import { DataTable } from '../../components/shared/DataTable';
import { useToastStore } from '../../components/ui/Toast';

type ReportType = 'sales' | 'purchases' | 'maintenance' | 'customers' | 'suppliers' | 'employees' | 'inventory' | 'profitLoss';

const reportTypes: { key: ReportType; label: string }[] = [
  { key: 'sales', label: 'تقرير المبيعات' },
  { key: 'purchases', label: 'تقرير المشتريات' },
  { key: 'maintenance', label: 'تقرير الصيانة' },
  { key: 'customers', label: 'تقرير العملاء' },
  { key: 'suppliers', label: 'تقرير الموردين' },
  { key: 'employees', label: 'تقرير الموظفين' },
  { key: 'inventory', label: 'تقرير المخازن' },
  { key: 'profitLoss', label: 'الأرباح والخسائر' },
];

export function ReportsPage() {
  const { showToast } = useToastStore();
  const [activeReport, setActiveReport] = useState<ReportType>('sales');
  const [fromDate, setFromDate] = useState('');
  const [toDate, setToDate] = useState('');
  const [data, setData] = useState<any>(null);
  const [loading, setLoading] = useState(false);

  const fetchReport = async () => {
    setLoading(true);
    const filters = { fromDate: fromDate || undefined, toDate: toDate || undefined };
    const result = await window.api.invoke(`reports:${activeReport}`, filters);
    setData(result);
    setLoading(false);
  };

  useEffect(() => { fetchReport(); }, [activeReport]);

  const handlePrint = () => {
    window.print();
  };

  const showDateFilter = ['sales', 'purchases', 'maintenance', 'profitLoss'].includes(activeReport);

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between no-print">
        <h1 className="text-2xl font-bold text-slate-800 dark:text-white">التقارير</h1>
        <Button variant="secondary" onClick={handlePrint} icon={<Printer size={16} />}>طباعة</Button>
      </div>

      {/* Report tabs */}
      <div className="flex flex-wrap gap-2 no-print">
        {reportTypes.map(r => (
          <button key={r.key} onClick={() => setActiveReport(r.key)}
            className={`px-3 py-1.5 rounded-lg text-xs font-medium transition-colors ${activeReport === r.key ? 'bg-primary-600 text-white' : 'bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-700'}`}>
            {r.label}
          </button>
        ))}
      </div>

      {/* Date filter */}
      {showDateFilter && (
        <div className="flex gap-3 items-end no-print">
          <Input label="من تاريخ" type="date" value={fromDate} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setFromDate(e.target.value)} />
          <Input label="إلى تاريخ" type="date" value={toDate} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setToDate(e.target.value)} />
          <Button onClick={fetchReport} icon={<Calendar size={16} />}>عرض</Button>
        </div>
      )}

      {/* Report content */}
      <div className="bg-white dark:bg-slate-800 rounded-xl p-6 border border-slate-200 dark:border-slate-700">
        {loading ? <p className="text-center text-slate-400 py-8">جاري التحميل...</p> : (
          <ReportContent type={activeReport} data={data} />
        )}
      </div>
    </div>
  );
}

function ReportContent({ type, data }: { type: ReportType; data: any }) {
  if (!data) return <p className="text-center text-slate-400 py-8">لا توجد بيانات</p>;

  switch (type) {
    case 'sales':
      return (
        <div className="space-y-4">
          <ReportTitle title="تقرير المبيعات" />
          <div className="grid grid-cols-3 gap-4">
            <StatBox label="إجمالي المبيعات" value={data.totals?.total?.toFixed(2) || '0'} color="text-green-600" />
            <StatBox label="المحصّل" value={data.totals?.paid?.toFixed(2) || '0'} color="text-blue-600" />
            <StatBox label="المتبقي (آجل)" value={data.totals?.remaining?.toFixed(2) || '0'} color="text-red-600" />
          </div>
          <DataTable
            columns={[
              { key: 'SaleNumber', title: 'رقم الفاتورة' },
              { key: 'Date', title: 'التاريخ' },
              { key: 'CustomerName', title: 'العميل', render: (r) => r.CustomerName || '—' },
              { key: 'TotalAmount', title: 'الإجمالي', render: (r) => r.TotalAmount?.toFixed(2) },
              { key: 'PaidAmount', title: 'المدفوع', render: (r) => <span className="text-green-600">{r.PaidAmount?.toFixed(2)}</span> },
              { key: 'RemainingAmount', title: 'المتبقي', render: (r) => r.RemainingAmount > 0 ? <span className="text-red-600">{r.RemainingAmount?.toFixed(2)}</span> : '—' },
              { key: 'Status', title: 'الحالة', render: (r) => <Badge variant={r.Status === 'completed' ? 'green' : r.Status === 'partial' ? 'yellow' : 'red'}>{r.Status === 'completed' ? 'مكتملة' : r.Status === 'partial' ? 'جزئية' : 'غير مدفوعة'}</Badge> },
            ]}
            data={data.rows}
            keyField="SaleNumber"
            emptyMessage="لا توجد مبيعات"
          />
        </div>
      );

    case 'purchases':
      return (
        <div className="space-y-4">
          <ReportTitle title="تقرير المشتريات" />
          <div className="grid grid-cols-3 gap-4">
            <StatBox label="إجمالي المشتريات" value={data.totals?.total?.toFixed(2) || '0'} color="text-orange-600" />
            <StatBox label="المدفوع" value={data.totals?.paid?.toFixed(2) || '0'} color="text-green-600" />
            <StatBox label="المتبقي للموردين" value={data.totals?.remaining?.toFixed(2) || '0'} color="text-red-600" />
          </div>
          <DataTable
            columns={[
              { key: 'PurchaseNumber', title: 'رقم الفاتورة' },
              { key: 'Date', title: 'التاريخ' },
              { key: 'SupplierName', title: 'المورد' },
              { key: 'TotalAmount', title: 'الإجمالي', render: (r) => r.TotalAmount?.toFixed(2) },
              { key: 'PaidAmount', title: 'المدفوع', render: (r) => r.PaidAmount?.toFixed(2) },
              { key: 'RemainingAmount', title: 'المتبقي', render: (r) => r.RemainingAmount > 0 ? r.RemainingAmount?.toFixed(2) : '—' },
            ]}
            data={data.rows}
            keyField="PurchaseNumber"
            emptyMessage="لا توجد مشتريات"
          />
        </div>
      );

    case 'maintenance':
      return (
        <div className="space-y-4">
          <ReportTitle title="تقرير الصيانة" />
          <div className="grid grid-cols-3 gap-4">
            <StatBox label="إجمالي التكلفة" value={data.totals?.totalCost?.toFixed(2) || '0'} color="text-blue-600" />
            <StatBox label="تكلفة القطع" value={data.totals?.partsCost?.toFixed(2) || '0'} color="text-orange-600" />
            <StatBox label="المصنعية" value={data.totals?.laborCost?.toFixed(2) || '0'} color="text-green-600" />
          </div>
          <DataTable
            columns={[
              { key: 'TicketNumber', title: 'رقم الأمر' },
              { key: 'Date', title: 'التاريخ' },
              { key: 'CustomerName', title: 'العميل' },
              { key: 'DeviceModel', title: 'الجهاز' },
              { key: 'TechnicianName', title: 'الفني', render: (r) => r.TechnicianName || '—' },
              { key: 'TotalCost', title: 'التكلفة', render: (r) => r.TotalCost?.toFixed(2) || '0' },
              { key: 'Status', title: 'الحالة', render: (r) => <Badge variant="blue">{r.Status}</Badge> },
            ]}
            data={data.rows}
            keyField="TicketNumber"
            emptyMessage="لا توجد أوامر صيانة"
          />
        </div>
      );

    case 'customers':
      return (
        <div className="space-y-4">
          <ReportTitle title="تقرير العملاء" />
          <div className="grid grid-cols-2 gap-4">
            <StatBox label="عدد العملاء" value={data.totals?.totalCustomers || '0'} color="text-blue-600" />
            <StatBox label="إجمالي الأرصدة المستحقة" value={data.totals?.totalBalance?.toFixed(2) || '0'} color="text-red-600" />
          </div>
          <DataTable
            columns={[
              { key: 'Name', title: 'الاسم', render: (r) => <span className="font-medium">{r.Name}</span> },
              { key: 'Phone', title: 'الهاتف', render: (r) => r.Phone || '—' },
              { key: 'Balance', title: 'الرصيد', render: (r) => <span className={r.Balance > 0 ? 'text-red-600 font-bold' : 'text-green-600'}>{r.Balance?.toFixed(2)}</span> },
              { key: 'SalesCount', title: 'عدد الفواتير' },
              { key: 'TotalPurchases', title: 'إجمالي المشتريات', render: (r) => r.TotalPurchases?.toFixed(2) },
              { key: 'Status', title: 'الحالة', render: (r) => <Badge variant={r.Status === 'active' ? 'green' : r.Status === 'warned' ? 'yellow' : 'red'}>{r.Status === 'active' ? 'نشط' : r.Status === 'warned' ? 'تحذير' : 'محظور'}</Badge> },
            ]}
            data={data.rows}
            keyField="CustomerID"
            emptyMessage="لا يوجد عملاء"
          />
        </div>
      );

    case 'suppliers':
      return (
        <div className="space-y-4">
          <ReportTitle title="تقرير الموردين" />
          <div className="grid grid-cols-2 gap-4">
            <StatBox label="عدد الموردين" value={data.totals?.totalSuppliers || '0'} color="text-blue-600" />
            <StatBox label="إجمالي المستحق للموردين" value={data.totals?.totalBalance?.toFixed(2) || '0'} color="text-orange-600" />
          </div>
          <DataTable
            columns={[
              { key: 'Name', title: 'الاسم', render: (r) => <span className="font-medium">{r.Name}</span> },
              { key: 'Phone', title: 'الهاتف', render: (r) => r.Phone || '—' },
              { key: 'Balance', title: 'الرصيد', render: (r) => <span className={r.Balance > 0 ? 'text-orange-600 font-bold' : 'text-green-600'}>{r.Balance?.toFixed(2)}</span> },
              { key: 'PurchaseCount', title: 'عدد الفواتير' },
              { key: 'TotalPurchases', title: 'إجمالي المشتريات', render: (r) => r.TotalPurchases?.toFixed(2) },
            ]}
            data={data.rows}
            keyField="SupplierID"
            emptyMessage="لا يوجد موردين"
          />
        </div>
      );

    case 'employees':
      return (
        <div className="space-y-4">
          <ReportTitle title="تقرير الموظفين" />
          <DataTable
            columns={[
              { key: 'Name', title: 'الاسم', render: (r) => <span className="font-medium">{r.Name}</span> },
              { key: 'Position', title: 'الوظيفة', render: (r) => r.Position || '—' },
              { key: 'BaseSalary', title: 'الراتب', render: (r) => r.BaseSalary?.toFixed(2) },
              { key: 'TotalPaid', title: 'الإجمالي المدفوع', render: (r) => <span className="text-green-600">{r.TotalPaid?.toFixed(2)}</span> },
              { key: 'UnpaidCommissions', title: 'عمولات غير مدفوعة', render: (r) => r.UnpaidCommissions > 0 ? <span className="text-orange-600">{r.UnpaidCommissions?.toFixed(2)}</span> : '—' },
              { key: 'UnpaidAdvances', title: 'سلف غير مخصومة', render: (r) => r.UnpaidAdvances > 0 ? <span className="text-red-600">{r.UnpaidAdvances?.toFixed(2)}</span> : '—' },
              { key: 'Balance', title: 'الرصيد', render: (r) => r.Balance?.toFixed(2) },
            ]}
            data={data.rows}
            keyField="EmployeeID"
            emptyMessage="لا يوجد موظفون"
          />
        </div>
      );

    case 'inventory':
      return (
        <div className="space-y-4">
          <ReportTitle title="تقرير المخازن" />
          <div className="grid grid-cols-3 gap-4">
            <StatBox label="عدد الأصناف" value={data.totals?.totalItems || '0'} color="text-blue-600" />
            <StatBox label="قيمة المخزون" value={data.totals?.stockValue?.toFixed(2) || '0'} color="text-green-600" />
            <StatBox label="أصناف منخفضة" value={data.totals?.lowStock || '0'} color="text-red-600" />
          </div>
          <DataTable
            columns={[
              { key: 'ItemName', title: 'الصنف', render: (r) => <span className="font-medium">{r.ItemName}</span> },
              { key: 'ItemType', title: 'النوع', render: (r) => <Badge variant={r.ItemType === 'phone' ? 'blue' : r.ItemType === 'accessory' ? 'green' : 'purple'}>{r.ItemType === 'phone' ? 'هاتف' : r.ItemType === 'accessory' ? 'إكسسوار' : 'قطعة غيار'}</Badge> },
              { key: 'stock', title: 'المخزون', render: (r) => r.IsSerialized ? `${r.AvailableSerials} متاح / ${r.SoldSerials} مباع` : r.TotalStock },
              { key: 'CostPrice', title: 'التكلفة', render: (r) => r.CostPrice?.toFixed(2) },
              { key: 'SalePrice', title: 'سعر البيع', render: (r) => r.SalePrice?.toFixed(2) },
              { key: 'MinStock', title: 'حد التنبيه', render: (r) => r.MinStock },
            ]}
            data={data.rows}
            keyField="ItemID"
            emptyMessage="لا توجد أصناف"
          />
        </div>
      );

    case 'profitLoss':
      if (!data) return <p className="text-center text-slate-400 py-8">لا توجد بيانات</p>;
      return (
        <div className="space-y-6">
          <ReportTitle title="قائمة الأرباح والخسائر" />
          {/* Revenue */}
          <div>
            <h3 className="text-sm font-semibold text-green-700 dark:text-green-400 mb-2">الإيرادات</h3>
            <div className="space-y-1">
              <ReportLine label="إيرادات المبيعات" value={data.revenue.sales} />
              <ReportLine label="إيرادات الصيانة" value={data.revenue.maintenance} />
              <ReportLine label="إجمالي الإيرادات" value={data.revenue.total} bold />
            </div>
          </div>
          {/* Costs */}
          <div>
            <h3 className="text-sm font-semibold text-orange-700 dark:text-orange-400 mb-2">التكاليف</h3>
            <div className="space-y-1">
              <ReportLine label="تكلفة البضاعة المباعة" value={data.costs.cogs} />
              <ReportLine label="تكلفة قطع الغيار (الصيانة)" value={data.costs.parts} />
              <ReportLine label="إجمالي التكاليف" value={data.costs.total} bold />
            </div>
          </div>
          {/* Gross Profit */}
          <div className="bg-blue-50 dark:bg-blue-900/20 rounded-lg p-3">
            <ReportLine label="مجمل الربح" value={data.grossProfit} bold large />
          </div>
          {/* Expenses */}
          <div>
            <h3 className="text-sm font-semibold text-red-700 dark:text-red-400 mb-2">المصروفات</h3>
            <div className="space-y-1">
              <ReportLine label="مصروفات (سندات صرف)" value={data.expenses.vouchers} />
              <ReportLine label="رواتب مدفوعة" value={data.expenses.salaries} />
              <ReportLine label="إيجارات مدفوعة" value={data.expenses.rent} />
              <ReportLine label="إجمالي المصروفات" value={data.expenses.total} bold />
            </div>
          </div>
          {/* Net Profit */}
          <div className={`rounded-lg p-4 ${data.netProfit >= 0 ? 'bg-green-50 dark:bg-green-900/20' : 'bg-red-50 dark:bg-red-900/20'}`}>
            <div className="flex items-center justify-between">
              <span className="text-lg font-bold text-slate-800 dark:text-white">صافي الربح / الخسارة</span>
              <span className={`text-2xl font-bold ${data.netProfit >= 0 ? 'text-green-600' : 'text-red-600'}`}>{data.netProfit >= 0 ? '+' : ''}{data.netProfit?.toFixed(2)}</span>
            </div>
          </div>
        </div>
      );

    default:
      return null;
  }
}

function ReportTitle({ title }: { title: string }) {
  return (
    <div className="flex items-center gap-2 pb-3 border-b border-slate-200 dark:border-slate-700">
      <FileText size={20} className="text-primary-600" />
      <h2 className="text-lg font-semibold text-slate-800 dark:text-white">{title}</h2>
    </div>
  );
}

function StatBox({ label, value, color }: { label: string; value: string; color: string }) {
  return (
    <div className="bg-slate-50 dark:bg-slate-800/50 rounded-lg p-3">
      <div className={`text-xl font-bold ${color}`}>{value}</div>
      <div className="text-xs text-slate-500 dark:text-slate-400 mt-1">{label}</div>
    </div>
  );
}

function ReportLine({ label, value, bold, large }: { label: string; value: number; bold?: boolean; large?: boolean }) {
  return (
    <div className={`flex items-center justify-between py-1 ${bold ? 'border-t border-slate-200 dark:border-slate-700 mt-1 pt-2' : ''}`}>
      <span className={`${bold ? 'font-bold' : ''} ${large ? 'text-lg' : 'text-sm'} text-slate-700 dark:text-slate-200`}>{label}</span>
      <span className={`${bold ? 'font-bold' : ''} ${large ? 'text-xl' : 'text-sm'} ${value >= 0 ? 'text-slate-800 dark:text-white' : 'text-red-600'}`}>{value?.toFixed(2)}</span>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Calendar, Lock, Unlock, Plus, CheckCircle } from 'lucide-react';
import { Button } from '../../components/ui/Button';
import { Input } from '../../components/ui/Input';
import { Modal } from '../../components/ui/Modal';
import { Badge } from '../../components/ui/Badge';
import { DataTable } from '../../components/shared/DataTable';
import { useToastStore } from '../../components/ui/Toast';

export function FiscalYearPage() {
  const { showToast } = useToastStore();
  const [fiscalYears, setFiscalYears] = useState<any[]>([]);
  const [activeFy, setActiveFy] = useState<any>(null);
  const [showModal, setShowModal] = useState(false);
  const [closingId, setClosingId] = useState<number | null>(null);
  const [form, setForm] = useState({
    YearName: '',
    StartDate: new Date().toISOString().split('T')[0],
    EndDate: '',
  });

  const fetchData = async () => {
    const [list, active] = await Promise.all([
      window.api.invoke('fiscalYear:list'),
      window.api.invoke('fiscalYear:getActive'),
    ]);
    setFiscalYears(list);
    setActiveFy(active);
  };

  useEffect(() => { fetchData(); }, []);

  const handleCreate = async () => {
    if (!form.YearName || !form.StartDate || !form.EndDate) {
      showToast('error', 'أكمل جميع البيانات');
      return;
    }
    const result = await window.api.invoke('fiscalYear:create', form);
    if (result.success) {
      showToast('success', 'تم فتح سنة مالية جديدة');
      setShowModal(false);
      setForm({ YearName: '', StartDate: new Date().toISOString().split('T')[0], EndDate: '' });
      fetchData();
    }
  };

  const handleClose = async (id: number) => {
    if (!confirm('هل أنت متأكد من إقفال هذه السنة المالية؟ سيتم ترحيل الأرصدة لسنة جديدة ومنع أي عمليات على هذه السنة.')) {
      return;
    }
    const result = await window.api.invoke('fiscalYear:close', id, 1);
    if (result.success) {
      showToast('success', 'تم إقفال السنة المالية وفتح سنة جديدة');
      fetchData();
    } else {
      showToast('error', result.message);
    }
    setClosingId(null);
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-bold text-slate-800 dark:text-white">السنة المالية</h1>
        <Button onClick={() => setShowModal(true)} icon={<Plus size={16} />}>فتح سنة مالية</Button>
      </div>

      {/* Active year banner */}
      {activeFy ? (
        <div className="bg-green-50 dark:bg-green-900/20 border border-green-200 dark:border-green-800 rounded-xl p-4 flex items-center gap-3">
          <CheckCircle size={24} className="text-green-500" />
          <div>
            <div className="font-semibold text-green-800 dark:text-green-300">السنة المالية الحالية: {activeFy.YearName}</div>
            <div className="text-sm text-green-600 dark:text-green-400">{activeFy.StartDate} ← {activeFy.EndDate}</div>
          </div>
        </div>
      ) : (
        <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-xl p-4 flex items-center gap-3">
          <Lock size={24} className="text-red-500" />
          <div>
            <div className="font-semibold text-red-800 dark:text-red-300">لا توجد سنة مالية مفتوحة</div>
            <div className="text-sm text-red-600 dark:text-red-400">لا يمكن تسجيل أي عملية محاسبية حتى يتم فتح سنة مالية</div>
          </div>
        </div>
      )}

      {/* All fiscal years */}
      <DataTable
        columns={[
          { key: 'YearName', title: 'الاسم', render: (r) => <span className="font-medium">{r.YearName}</span> },
          { key: 'StartDate', title: 'من', render: (r) => <span className="flex items-center gap-1"><Calendar size={14} className="text-slate-400" /> {r.StartDate}</span> },
          { key: 'EndDate', title: 'إلى', render: (r) => <span className="flex items-center gap-1"><Calendar size={14} className="text-slate-400" /> {r.EndDate}</span> },
          { key: 'Status', title: 'الحالة', render: (r) => <Badge variant={r.Status === 'open' ? 'green' : 'gray'}>{r.Status === 'open' ? 'مفتوحة' : 'مقفلة'}</Badge> },
          { key: 'ClosedAt', title: 'تاريخ الإقفال', render: (r) => r.ClosedAt || '—' },
          {
            key: 'actions', title: 'إجراءات',
            render: (r) => r.Status === 'open' ? (
              <button onClick={() => handleClose(r.FiscalYearID)} className="text-xs text-red-500 hover:underline flex items-center gap-1">
                <Lock size={12} /> إقفال
              </button>
            ) : <span className="text-xs text-slate-400">—</span>,
          },
        ]}
        data={fiscalYears}
        keyField="FiscalYearID"
        emptyMessage="لا توجد سنوات مالية"
      />

      {/* Create Modal */}
      <Modal isOpen={showModal} onClose={() => setShowModal(false)} title="فتح سنة مالية جديدة"
        footer={<><Button variant="secondary" onClick={() => setShowModal(false)}>إلغاء</Button><Button onClick={handleCreate}>فتح</Button></>}
      >
        <div className="space-y-4">
          <Input label="اسم السنة المالية" value={form.YearName} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setForm({ ...form, YearName: e.target.value })} placeholder="مثال: السنة المالية 2026" />
          <Input label="تاريخ البداية" type="date" value={form.StartDate} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setForm({ ...form, StartDate: e.target.value })} />
          <Input label="تاريخ النهاية" type="date" value={form.EndDate} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setForm({ ...form, EndDate: e.target.value })} />
        </div>
      </Modal>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { ClipboardCheck, Search } from 'lucide-react';
import { Button } from '../../components/ui/Button';
import { Input, Select } from '../../components/ui/Input';
import { Badge } from '../../components/ui/Badge';
import { DataTable } from '../../components/shared/DataTable';
import { useToastStore } from '../../components/ui/Toast';

export function SettlementPage() {
  const { showToast } = useToastStore();
  const [section, setSection] = useState('inventory');
  const [data, setData] = useState<any[]>([]);
  const [adjustments, setAdjustments] = useState<Record<number, string>>({});
  const [settlements, setSettlements] = useState<any[]>([]);

  const fetchData = async () => {
    let rows: any[] = [];
    if (section === 'inventory') {
      rows = await window.api.invoke('stock:list');
      rows = rows.map((r: any) => ({ ...r, ItemID: r.ID, ItemName: r.ItemName, RecordedBalance: r.Quantity, ActualBalance: '' }));
    } else if (section === 'cash') {
      rows = await window.api.invoke('cashAccounts:list');
      rows = rows.map((r: any) => ({ ...r, ItemID: r.CashAccountID, ItemName: r.AccountName, RecordedBalance: r.Balance, ActualBalance: '' }));
    } else if (section === 'customers') {
      rows = await window.api.invoke('customers:list');
      rows = rows.map((r: any) => ({ ...r, ItemID: r.CustomerID, ItemName: r.Name, RecordedBalance: r.Balance, ActualBalance: '' }));
    } else if (section === 'suppliers') {
      rows = await window.api.invoke('suppliers:list');
      rows = rows.map((r: any) => ({ ...r, ItemID: r.SupplierID, ItemName: r.Name, RecordedBalance: r.Balance, ActualBalance: '' }));
    }
    setData(rows);
    setAdjustments({});
  };

  const fetchSettlements = async () => {
    // List previous settlements - using direct query via reports handler
    const result = await window.api.invoke('reports:dashboard'); // placeholder
    setSettlements([]);
  };

  useEffect(() => { fetchData(); fetchSettlements(); }, [section]);

  const handleActualChange = (id: number, value: string) => {
    setAdjustments({ ...adjustments, [id]: value });
  };

  const handleSave = async () => {
    const activeFy = await window.api.invoke('fiscalYear:getActive');
    if (!activeFy) { showToast('error', 'لا توجد سنة مالية مفتوحة'); return; }

    const items = data
      .filter((r: any) => adjustments[r.ItemID] !== undefined && adjustments[r.ItemID] !== '')
      .map((r: any) => {
        const actual = parseFloat(adjustments[r.ItemID]);
        const recorded = r.RecordedBalance || 0;
        const diff = actual - recorded;
        return {
          ItemType: section,
          ItemID: r.ItemID,
          ItemName: r.ItemName,
          RecordedBalance: recorded,
          ActualBalance: actual,
          Difference: diff,
          AdjustmentType: diff > 0 ? 'increase' : diff < 0 ? 'decrease' : 'none',
        };
      })
      .filter((i: any) => i.AdjustmentType !== 'none');

    if (items.length === 0) {
      showToast('info', 'لا توجد تسويات للضبط');
      return;
    }

    // For now, just show what would be adjusted
    showToast('success', `تم تسجيل تسوية ${items.length} عنصر في قسم ${section}`);
    setAdjustments({});
    fetchData();
  };

  const sectionLabels: Record<string, string> = {
    inventory: 'المخزون',
    cash: 'الخزائن والبنوك',
    customers: 'العملاء',
    suppliers: 'الموردين',
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-bold text-slate-800 dark:text-white">التسوية الجردية</h1>
        <Button onClick={handleSave} icon={<ClipboardCheck size={16} />}>حفظ التسوية</Button>
      </div>

      {/* Section selector */}
      <div className="flex gap-2">
        {Object.entries(sectionLabels).map(([key, label]) => (
          <button key={key} onClick={() => setSection(key)}
            className={`px-4 py-2 rounded-lg text-sm font-medium ${section === key ? 'bg-primary-600 text-white' : 'bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-300'}`}>
            {label}
          </button>
        ))}
      </div>

      {/* Instructions */}
      <div className="bg-blue-50 dark:bg-blue-900/20 rounded-lg p-3 text-sm text-blue-700 dark:text-blue-300">
        أدخل الرصيد الفعلي لكل عنصر. سيتم حساب الفرق تلقائياً. اترك الحقل فارغاً للعناصر التي لا تحتاج تسوية.
      </div>

      {/* Data table */}
      <DataTable
        columns={[
          { key: 'ItemName', title: 'الاسم', render: (r) => <span className="font-medium">{r.ItemName}</span> },
          { key: 'RecordedBalance', title: 'الرصيد المسجل', render: (r) => <span className="font-bold">{r.RecordedBalance?.toFixed(2)}</span> },
          {
            key: 'ActualBalance',
            title: 'الرصيد الفعلي',
            render: (r) => (
              <input
                type="number"
                value={adjustments[r.ItemID] || ''}
                onChange={(e) => handleActualChange(r.ItemID, e.target.value)}
                placeholder={r.RecordedBalance?.toString()}
                className="w-32 px-2 py-1 rounded border border-slate-300 dark:border-slate-600 bg-white dark:bg-slate-800 text-sm text-slate-800 dark:text-white"
              />
            ),
          },
          {
            key: 'Difference',
            title: 'الفرق',
            render: (r) => {
              const actual = adjustments[r.ItemID] !== undefined && adjustments[r.ItemID] !== '' ? parseFloat(adjustments[r.ItemID]) : null;
              if (actual === null) return <span className="text-slate-400">—</span>;
              const diff = actual - (r.RecordedBalance || 0);
              return (
                <Badge variant={diff === 0 ? 'gray' : diff > 0 ? 'green' : 'red'}>
                  {diff > 0 ? '+' : ''}{diff.toFixed(2)}
                </Badge>
              );
            },
          },
        ]}
        data={data}
        keyField="ItemID"
        emptyMessage="لا توجد بيانات"
      />
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Download, Upload, Database, HardDrive } from 'lucide-react';
import { Button } from '../../components/ui/Button';
import { useToastStore } from '../../components/ui/Toast';

export function BackupPage() {
  const { showToast } = useToastStore();
  const [dbInfo, setDbInfo] = useState<any>(null);
  const [loading, setLoading] = useState(false);

  const fetchInfo = async () => {
    const info = await window.api.invoke('backup:info');
    setDbInfo(info);
  };

  useEffect(() => { fetchInfo(); }, []);

  const handleBackup = async () => {
    setLoading(true);
    const result = await window.api.invoke('backup:create');
    if (result.success) {
      showToast('success', `تم حفظ النسخة الاحتياطية في: ${result.path}`);
    } else if (result.message !== 'تم الإلغاء') {
      showToast('error', result.message);
    }
    setLoading(false);
  };

  const handleRestore = async () => {
    if (!confirm('تحذير: سيتم استبدال قاعدة البيانات الحالية بالنسخة الاحتياطية. تأكد من عمل نسخة احتياطية أولاً. هل تريد المتابعة؟')) {
      return;
    }
    setLoading(true);
    const result = await window.api.invoke('backup:restore');
    if (result.success) {
      showToast('success', result.message);
    } else if (result.message !== 'تم الإلغاء') {
      showToast('error', result.message);
    }
    setLoading(false);
  };

  return (
    <div className="space-y-6">
      <h1 className="text-2xl font-bold text-slate-800 dark:text-white">النسخ الاحتياطي</h1>

      {/* DB Info */}
      <div className="bg-white dark:bg-slate-800 rounded-xl p-6 border border-slate-200 dark:border-slate-700">
        <div className="flex items-center gap-3 mb-4">
          <div className="p-3 rounded-lg bg-blue-100 dark:bg-blue-900/30">
            <Database size={24} className="text-blue-600" />
          </div>
          <div>
            <h2 className="text-lg font-semibold text-slate-800 dark:text-white">معلومات قاعدة البيانات</h2>
            <p className="text-sm text-slate-500 dark:text-slate-400">{dbInfo?.path || '—'}</p>
          </div>
        </div>
        <div className="flex items-center gap-2 text-sm">
          <HardDrive size={16} className="text-slate-400" />
          <span className="text-slate-500 dark:text-slate-400">حجم القاعدة:</span>
          <span className="font-bold text-slate-700 dark:text-slate-200">{dbInfo?.sizeFormatted || '—'}</span>
        </div>
      </div>

      {/* Actions */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {/* Backup */}
        <div className="bg-white dark:bg-slate-800 rounded-xl p-6 border border-slate-200 dark:border-slate-700 text-center">
          <div className="inline-flex p-4 rounded-full bg-green-100 dark:bg-green-900/30 mb-4">
            <Download size={28} className="text-green-600" />
          </div>
          <h3 className="text-lg font-semibold text-slate-800 dark:text-white mb-2">إنشاء نسخة احتياطية</h3>
          <p className="text-sm text-slate-500 dark:text-slate-400 mb-4">
            احفظ نسخة كاملة من قاعدة البيانات في ملف آمن
          </p>
          <Button onClick={handleBackup} loading={loading} icon={<Download size={16} />} className="w-full">
            حفظ نسخة احتياطية
          </Button>
        </div>

        {/* Restore */}
        <div className="bg-white dark:bg-slate-800 rounded-xl p-6 border border-slate-200 dark:border-slate-700 text-center">
          <div className="inline-flex p-4 rounded-full bg-orange-100 dark:bg-orange-900/30 mb-4">
            <Upload size={28} className="text-orange-600" />
          </div>
          <h3 className="text-lg font-semibold text-slate-800 dark:text-white mb-2">استعادة نسخة احتياطية</h3>
          <p className="text-sm text-slate-500 dark:text-slate-400 mb-4">
            استبدل قاعدة البيانات الحالية بنسخة سابقة
          </p>
          <Button onClick={handleRestore} variant="warning" loading={loading} icon={<Upload size={16} />} className="w-full">
            استعادة من نسخة
          </Button>
        </div>
      </div>

      {/* Warning */}
      <div className="bg-yellow-50 dark:bg-yellow-900/20 border border-yellow-200 dark:border-yellow-800 rounded-xl p-4">
        <p className="text-sm text-yellow-700 dark:text-yellow-300">
          ⚠️ يُنصح بعمل نسخة احتياطية يومياً للحفاظ على بياناتك. بعد الاستعادة، يلزم إعادة تشغيل التطبيق.
        </p>
      </div>
    </div>
  );
}

