                <option value="transfer">تحويل</option>
                <option value="wallet">محفظة</option>
              </Select>
              <Input label="المبلغ المدفوع" type="number" value={paidAmount} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setPaidAmount(e.target.value)} hint={`الإجمالي: ${total.toFixed(2)}`} />
              <Select label="الخزنة/البنك" value={cashAccountId} onChange={(e) => setCashAccountId(e.target.value)}>
                <option value="">— اختر —</option>
                {cashAccounts.map((ca: any) => <option key={ca.CashAccountID} value={ca.CashAccountID}>{ca.AccountName} ({ca.Balance?.toFixed(2)})</option>)}
              </Select>
            </div>
          </div>
        </div>
      </Modal>
    </div>
  );
}

