/* ===== Dark mode fixes for native elements ===== */

/* Select dropdown options */
.dark select option {
  background-color: #1e293b;
  color: #f1f5f9;
}

.dark select option:checked {
  background-color: #2563eb;
  color: #ffffff;
}

/* Date inputs */
.dark input[type="date"]::-webkit-calendar-picker-indicator,
.dark input[type="month"]::-webkit-calendar-picker-indicator {
  filter: invert(1);
  opacity: 0.6;
  cursor: pointer;
}

.dark input[type="date"]::-webkit-calendar-picker-indicator:hover,
.dark input[type="month"]::-webkit-calendar-picker-indicator:hover {
  opacity: 1;
}

/* Number input spinners */
.dark input[type="number"]::-webkit-inner-spin-button,
.dark input[type="number"]::-webkit-outer-spin-button {
  filter: invert(1);
  opacity: 0.5;
}

/* Checkbox in dark mode */
.dark input[type="checkbox"] {
  accent-color: #3b82f6;
}

/* Focus outline in dark mode */
.dark input:focus,
.dark select:focus,
.dark textarea:focus {
  outline: none;
}

/* Placeholder color in dark mode */
.dark input::placeholder,
.dark textarea::placeholder {
  color: #64748b;
}

/* Toast slide-in animation */
@keyframes slide-in {
  from {
    transform: translateX(-100%);
    opacity: 0;
  }
  to {
    transform: translateX(0);
    opacity: 1;
  }
}

.animate-slide-in {
  animation: slide-in 0.3s ease-out;
}

/* Print styles */
@media print {
  .no-print {
    display: none !important;
  }
  body {
    background: white !important;
    color: black !important;
  }
}

