import { useState, useEffect } from 'react';
import { Wallet, Users, Truck, Package, Save, RefreshCw } from 'lucide-react';
import { Button } from '../../components/ui/Button';
import { Input } from '../../components/ui/Input';
import { Badge } from '../../components/ui/Badge';
import { DataTable } from '../../components/shared/DataTable';
import { useToastStore } from '../../components/ui/Toast';

type Tab = 'cash' | 'customers' | 'suppliers' | 'employees';

export function OpeningBalancePage() {
  const { showToast } = useToastStore();
  const [tab, setTab] = useState<Tab>('cash');
  const [data, setData] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [edits, setEdits] = useState<Record<number, string>>({});

  const fetchData = async () => {
    setLoading(true);
    const result = await window.api.invoke('openingBalances:overview');
    setData(result);
    setEdits({});
    setLoading(false);
  };

  useEffect(() => { fetchData(); }, []);

  const handleEdit = (id: number, value: string) => {
    setEdits({ ...edits, [id]: value });
  };

  const handleSave = async () => {
    const items = Object.entries(edits)
      .filter(([_, v]) => v !== '' && v !== null)
      .map(([id, v]) => ({ id: parseInt(id), balance: parseFloat(v) || 0 }));

    if (items.length === 0) {
      showToast('info', 'لا توجد تعديلات للحفظ');
      return;
    }

    setSaving(true);
    const payload: any = { cashAccounts: [], customers: [], suppliers: [], employees: [] };

    if (tab === 'cash') payload.cashAccounts = items;
    else if (tab === 'customers') payload.customers = items;
    else if (tab === 'suppliers') payload.suppliers = items;
    else if (tab === 'employees') payload.employees = items;

    const result = await window.api.invoke('openingBalances:batchUpdate', payload);
    if (result.success) {
      showToast('success', `تم تحديث ${items.length} رصيد`);
      fetchData();
    } else {
      showToast('error', 'فشل الحفظ');
    }
    setSaving(false);
  };

  if (loading || !data) {
    return <div className="text-slate-400 text-center py-8">جاري التحميل...</div>;
  }

  const tabs = [
    { key: 'cash' as Tab, label: 'الخزائن والبنوك', icon: Wallet, total: data.totals.totalCash },
    { key: 'customers' as Tab, label: 'العملاء', icon: Users, total: data.totals.totalCustomers },
    { key: 'suppliers' as Tab, label: 'الموردين', icon: Truck, total: data.totals.totalSuppliers },
    { key: 'employees' as Tab, label: 'الموظفين', icon: Package, total: data.totals.totalEmployees },
  ];

  const currentData = tab === 'cash' ? data.cashAccounts : tab === 'customers' ? data.customers : tab === 'suppliers' ? data.suppliers : data.employees;
  const idField = tab === 'cash' ? 'CashAccountID' : tab === 'customers' ? 'CustomerID' : tab === 'suppliers' ? 'SupplierID' : 'EmployeeID';

  const nameField = tab === 'cash' ? 'AccountName' : 'Name';
  const subField = tab === 'cash' ? 'AccountType' : tab === 'customers' ? 'Phone' : tab === 'suppliers' ? 'Phone' : 'Position';

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-bold text-slate-800 dark:text-white">الأرصدة الافتتاحية</h1>
        <div className="flex gap-2">
          <Button variant="secondary" onClick={fetchData} icon={<RefreshCw size={16} />}>تحديث</Button>
          <Button onClick={handleSave} loading={saving} icon={<Save size={16} />}>حفظ التعديلات</Button>
        </div>
      </div>

      {/* Summary cards */}
      <div className="grid grid-cols-2 md:grid-cols-5 gap-3">
        {tabs.map(t => {
          const Icon = t.icon;
          return (
            <button key={t.key} onClick={() => setTab(t.key)}
              className={`p-4 rounded-xl border-2 text-right transition-all ${tab === t.key ? 'border-primary-600 bg-primary-50 dark:bg-primary-900/20' : 'border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800'}`}>
              <div className="flex items-center gap-2 mb-2">
                <Icon size={16} className={tab === t.key ? 'text-primary-600' : 'text-slate-400'} />
                <span className={`text-xs font-medium ${tab === t.key ? 'text-primary-700 dark:text-primary-300' : 'text-slate-500 dark:text-slate-400'}`}>{t.label}</span>
              </div>
              <div className="text-lg font-bold text-slate-800 dark:text-white">{t.total?.toFixed(2)}</div>
            </button>
          );
        })}
        <div className="p-4 rounded-xl border-2 border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800">
          <div className="flex items-center gap-2 mb-2">
            <Package size={16} className="text-slate-400" />
            <span className="text-xs font-medium text-slate-500 dark:text-slate-400">قيمة المخزون</span>
          </div>
          <div className="text-lg font-bold text-green-600">{data.totals.totalInventory?.toFixed(2)}</div>
        </div>
      </div>

      {/* Edit table */}
      <div className="bg-white dark:bg-slate-800 rounded-xl p-4 border border-slate-200 dark:border-slate-700">
        <h2 className="text-sm font-semibold text-slate-700 dark:text-slate-200 mb-3">
          تعديل أرصدة: {tabs.find(t => t.key === tab)?.label}
        </h2>
        <p className="text-xs text-slate-400 mb-3">عدّل القيمة في عمود "الرصيد الجديد" ثم اضغط "حفظ التعديلات"</p>

        <DataTable
          columns={[
            { key: nameField, title: 'الاسم', render: (r) => <span className="font-medium text-slate-800 dark:text-white">{r[nameField]}</span> },
            { key: subField, title: tab === 'cash' ? 'النوع' : 'الهاتف', render: (r) => {
              if (tab === 'cash') return <Badge variant={r[subField] === 'safe' ? 'blue' : 'purple'}>{r[subField] === 'safe' ? 'خزنة' : 'بنك'}</Badge>;
              return r[subField] || '—';
            }},
            { key: 'Balance', title: 'الرصيد الحالي', render: (r) => <span className="font-bold text-slate-700 dark:text-slate-200">{r.Balance?.toFixed(2)}</span> },
            {
              key: 'newBalance',
              title: 'الرصيد الجديد',
              render: (r) => (
                <input
                  type="number"
                  value={edits[r[idField]] ?? ''}
                  onChange={(e) => handleEdit(r[idField], e.target.value)}
                  placeholder={r.Balance?.toString() || '0'}
                  className="w-32 px-2 py-1 rounded border border-slate-300 dark:border-slate-600 bg-white dark:bg-slate-800 text-slate-800 dark:text-white text-sm"
                />
              ),
            },
          ]}
          data={currentData}
          keyField={idField}
          emptyMessage="لا توجد بيانات"
        />
      </div>
    </div>
  );
}

