function TransferList({ warehouses, showToast }: { warehouses: any[]; showToast: (type: 'success' | 'error', msg: string) => void }) {
  const [transfers, setTransfers] = useState<any[]>([]);
  const [showModal, setShowModal] = useState(false);
  const [fromWh, setFromWh] = useState('');
  const [toWh, setToWh] = useState('');
  const [items] = useState<any[]>([]);
  const [selectedItems, setSelectedItems] = useState<any[]>([]);

  const fetchTransfers = async () => {
    const t = await window.api.invoke('transfers:list');
    setTransfers(t);
  };

  useEffect(() => { fetchTransfers(); }, []);

  const handleTransfer = async () => {
    if (!fromWh || !toWh || fromWh === toWh) { showToast('error', 'يرجى اختيار مخازن صحيحة'); return; }
    if (selectedItems.length === 0) { showToast('error', 'أضف أصنافاً للتحويل'); return; }
    const result = await window.api.invoke('transfers:create', {
      FromWarehouseID: parseInt(fromWh),
      ToWarehouseID: parseInt(toWh),
      items: selectedItems,
      userId: 1,
    });
    if (result.success) {
      showToast('success', `تم التحويل - رقم: ${result.transferNumber}`);
      setShowModal(false);
      setSelectedItems([]);
      fetchTransfers();
    }
  };

  return (
    <>
      <DataTable
        columns={[
          { key: 'TransferNumber', title: 'رقم التحويل', render: (row) => <span className="font-mono text-xs">{row.TransferNumber}</span> },
          { key: 'Date', title: 'التاريخ' },
          { key: 'FromWarehouse', title: 'من', render: (row) => row.FromWarehouse },
          { key: 'ToWarehouse', title: 'إلى', render: (row) => row.ToWarehouse },
          { key: 'Status', title: 'الحالة', render: (row) => <Badge variant={row.Status === 'completed' ? 'green' : 'gray'}>{row.Status === 'completed' ? 'مكتمل' : 'ملغي'}</Badge> },
        ]}
        data={transfers}
        keyField="TransferID"
        emptyMessage="لا توجد تحويلات"
      />
    </>
  );
}

