    const [it, wh, cat] = await Promise.all([
      window.api.invoke('items:list', { search, type: typeFilter, categoryId: parseInt(categoryFilter), isActive: 1 }),
      window.api.invoke('warehouses:list'),
      window.api.invoke('categories:list'),
    ]);
    setItems(it);
    setWarehouses(wh);
    setCategories(cat);
  };

  useEffect(() => { fetchData(); }, [search, typeFilter, categoryFilter]);

  const saveItem = async () => {
    if (!itemForm.ItemName) { showToast('error', 'يرجى إدخال اسم الصنف'); return; }
    const data = { ...itemForm, CategoryID: itemForm.CategoryID ? parseInt(itemForm.CategoryID) : null, SalePrice: parseFloat(itemForm.SalePrice) || 0, CostPrice: parseFloat(itemForm.CostPrice) || 0, MinStock: parseInt(itemForm.MinStock) || 0, IsSerialized: itemForm.ItemType === 'phone' ? 1 : 0 };
