import { useState, useEffect } from 'react';
import { Plus, Edit, Wallet, CreditCard, Smartphone } from 'lucide-react';
import { Button } from '../../components/ui/Button';
import { Input, Select } from '../../components/ui/Input';
import { Modal } from '../../components/ui/Modal';
import { Badge } from '../../components/ui/Badge';
import { DataTable } from '../../components/shared/DataTable';
import { useToastStore } from '../../components/ui/Toast';

export function AssetsPage() {
  const { showToast } = useToastStore();
  const [tab, setTab] = useState<'cash' | 'payment'>('cash');
  const [cashAccounts, setCashAccounts] = useState<any[]>([]);
  const [paymentMethods, setPaymentMethods] = useState<any[]>([]);
  const [showModal, setShowModal] = useState(false);
  const [editing, setEditing] = useState<any>(null);

  // Cash account form
  const [cashForm, setCashForm] = useState({ AccountName: '', AccountType: 'safe', Balance: '', BankName: '', AccountNumber: '', IsActive: 1 });
  // Payment method form
  const [pmForm, setPmForm] = useState({ MethodName: '', MethodType: 'pos_machine', Provider: '', PhoneNumber: '', IsActive: 1 });

  const fetchData = async () => {
    const [ca, pm] = await Promise.all([
      window.api.invoke('cashAccounts:list'),
      window.api.invoke('paymentMethods:list'),
    ]);
    setCashAccounts(ca);
    setPaymentMethods(pm);
  };

  useEffect(() => { fetchData(); }, []);

  const openCreateCash = () => {
    setEditing(null);
    setCashForm({ AccountName: '', AccountType: 'safe', Balance: '', BankName: '', AccountNumber: '', IsActive: 1 });
    setShowModal(true);
  };

  const openEditCash = (ca: any) => {
    setEditing(ca);
    setCashForm({ AccountName: ca.AccountName, AccountType: ca.AccountType, Balance: '', BankName: ca.BankName || '', AccountNumber: ca.AccountNumber || '', IsActive: ca.IsActive });
    setShowModal(true);
  };

  const openCreatePm = () => {
    setEditing({ isPayment: true });
    setPmForm({ MethodName: '', MethodType: 'pos_machine', Provider: '', PhoneNumber: '', IsActive: 1 });
    setShowModal(true);
  };

  const openEditPm = (pm: any) => {
    setEditing({ ...pm, isPayment: true });
    setPmForm({ MethodName: pm.MethodName, MethodType: pm.MethodType, Provider: pm.Provider || '', PhoneNumber: pm.PhoneNumber || '', IsActive: pm.IsActive });
    setShowModal(true);
  };

  const handleSaveCash = async () => {
    if (!cashForm.AccountName) { showToast('error', 'يرجى إدخال اسم الحساب'); return; }
    const data = { ...cashForm, Balance: parseFloat(cashForm.Balance) || 0 };
    if (editing) {
      await window.api.invoke('cashAccounts:update', editing.CashAccountID, data);
      showToast('success', 'تم تحديث الحساب');
    } else {
      await window.api.invoke('cashAccounts:create', data);
      showToast('success', 'تم إضافة الحساب');
    }
    setShowModal(false);
    fetchData();
  };

  const handleSavePm = async () => {
    if (!pmForm.MethodName) { showToast('error', 'يرجى إدخال اسم طريقة الدفع'); return; }
    if (editing?.PaymentMethodID) {
      await window.api.invoke('paymentMethods:update', editing.PaymentMethodID, pmForm);
      showToast('success', 'تم التحديث');
    } else {
      await window.api.invoke('paymentMethods:create', pmForm);
      showToast('success', 'تم الإضافة');
    }
    setShowModal(false);
    fetchData();
  };

  return (
    <div className="space-y-4">
      <h1 className="text-2xl font-bold text-slate-800 dark:text-white">الأصول النقدية</h1>

      {/* Tabs */}
      <div className="flex gap-2">
        <button onClick={() => setTab('cash')} className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-medium transition-colors ${tab === 'cash' ? 'bg-primary-600 text-white' : 'bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-300'}`}>
          <Wallet size={16} /> البنوك والخزائن
        </button>
        <button onClick={() => setTab('payment')} className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-medium transition-colors ${tab === 'payment' ? 'bg-primary-600 text-white' : 'bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-300'}`}>
          <CreditCard size={16} /> ماكينات وأنظمة الدفع
        </button>
      </div>

      {tab === 'cash' && (
        <div className="space-y-4">
          <div className="flex justify-end">
            <Button onClick={openCreateCash} icon={<Plus size={16} />}>حساب جديد</Button>
          </div>
          <DataTable
            columns={[
              { key: 'AccountName', title: 'الاسم', render: (row) => <span className="font-medium">{row.AccountName}</span> },
              { key: 'AccountType', title: 'النوع', render: (row) => <Badge variant={row.AccountType === 'safe' ? 'blue' : 'purple'}>{row.AccountType === 'safe' ? 'خزنة' : 'بنك'}</Badge> },
              { key: 'Balance', title: 'الرصيد', render: (row) => <span className="font-bold text-green-600">{row.Balance?.toFixed(2)}</span> },
              { key: 'BankName', title: 'البنك', render: (row) => row.BankName || '—' },
              { key: 'AccountNumber', title: 'رقم الحساب', render: (row) => row.AccountNumber || '—' },
              { key: 'actions', title: '', render: (row) => <button onClick={() => openEditCash(row)} className="text-xs text-primary-600 hover:underline flex items-center gap-1"><Edit size={12} /> تعديل</button> },
            ]}
            data={cashAccounts}
            keyField="CashAccountID"
            emptyMessage="لا توجد حسابات"
          />
        </div>
      )}

      {tab === 'payment' && (
        <div className="space-y-4">
          <div className="flex justify-end">
            <Button onClick={openCreatePm} icon={<Plus size={16} />}>طريقة دفع جديدة</Button>
          </div>
          <DataTable
            columns={[
              { key: 'MethodName', title: 'الاسم', render: (row) => <span className="font-medium">{row.MethodName}</span> },
              { key: 'MethodType', title: 'النوع', render: (row) => <Badge variant={row.MethodType === 'pos_machine' ? 'blue' : row.MethodType === 'digital_wallet' ? 'green' : 'purple'}>{row.MethodType === 'pos_machine' ? 'ماكينة' : row.MethodType === 'digital_wallet' ? 'محفظة' : 'تحويل'}</Badge> },
              { key: 'Provider', title: 'المزوّد', render: (row) => row.Provider || '—' },
              { key: 'PhoneNumber', title: 'رقم المحفظة', render: (row) => row.PhoneNumber || '—' },
