            data={paymentMethods}
            keyField="PaymentMethodID"
            emptyMessage="لا توجد طرق دفع"
          />
        </div>
      )}

      {/* Modal */}
      <Modal isOpen={showModal} onClose={() => setShowModal(false)} title={editing?.isPayment ? (editing?.PaymentMethodID ? 'تعديل طريقة دفع' : 'طريقة دفع جديدة') : (editing ? 'تعديل حساب' : 'حساب جديد')}
        footer={<><Button variant="secondary" onClick={() => setShowModal(false)}>إلغاء</Button><Button onClick={editing?.isPayment ? handleSavePm : handleSaveCash}>حفظ</Button></>}
      >
        {editing?.isPayment ? (
          <div className="grid grid-cols-2 gap-4">
            <Input label="الاسم" value={pmForm.MethodName} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setPmForm({ ...pmForm, MethodName: e.target.value })} />
            <Select label="النوع" value={pmForm.MethodType} onChange={(e) => setPmForm({ ...pmForm, MethodType: e.target.value })}>
              <option value="pos_machine">ماكينة دفع</option>
              <option value="digital_wallet">محفظة إلكترونية</option>
              <option value="transfer">تحويل</option>
            </Select>
            <Input label="المزوّد" value={pmForm.Provider} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setPmForm({ ...pmForm, Provider: e.target.value })} hint="فودافون، أورانج، اتصالات، إنستا باي..." />
            <Input label="رقم المحفظة" value={pmForm.PhoneNumber} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setPmForm({ ...pmForm, PhoneNumber: e.target.value })} />
          </div>
        ) : (
          <div className="grid grid-cols-2 gap-4">
