import { useState, useEffect } from 'react';
import { ArrowRight, Printer, FileText } from 'lucide-react';
import { Button } from '../../components/ui/Button';
import { Input } from '../../components/ui/Input';
import { Badge } from '../../components/ui/Badge';
import { useToastStore } from '../../components/ui/Toast';

export function CustomerStatementPage() {
  const { showToast } = useToastStore();
  const [customerId, setCustomerId] = useState<number | null>(null);
  const [customers, setCustomers] = useState<any[]>([]);
  const [data, setData] = useState<any>(null);
  const [loading, setLoading] = useState(false);
  const [fromDate, setFromDate] = useState('');
  const [toDate, setToDate] = useState('');

  useEffect(() => {
    (async () => {
      const list = await window.api.invoke('customers:list');
      setCustomers(list);
    })();
  }, []);

  const fetchStatement = async (id: number) => {
    setCustomerId(id);
    setLoading(true);
    const result = await window.api.invoke('customerStatement:get', id, {
      fromDate: fromDate || undefined,
      toDate: toDate || undefined,
    });
    if (result.success) {
      setData(result);
    } else {
      showToast('error', result.message);
    }
    setLoading(false);
  };

  const opTypeLabels: Record<string, { label: string; variant: string }> = {
    sale: { label: 'فاتورة بيع', variant: 'blue' },
    sale_return: { label: 'مرتجع مبيعات', variant: 'green' },
    maintenance_delivery: { label: 'تسليم صيانة', variant: 'purple' },
    voucher_receipt: { label: 'سند قبض', variant: 'green' },
    voucher_payment: { label: 'سند صرف', variant: 'red' },
  };

  const customer = data?.customer;

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between no-print">
        <h1 className="text-2xl font-bold text-slate-800 dark:text-white">كشف حساب عميل</h1>
        {data && <Button variant="secondary" onClick={() => window.print()} icon={<Printer size={16} />}>طباعة</Button>}
      </div>

      {/* Customer selector */}
      <div className="flex gap-3 items-end no-print">
        <div className="flex-1 max-w-xs">
          <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">اختر العميل</label>
          <select
            value={customerId ?? ''}
            onChange={(e) => e.target.value ? fetchStatement(parseInt(e.target.value)) : null}
            className="w-full px-3 py-2 rounded-lg border border-slate-300 dark:border-slate-600 bg-white dark:bg-slate-800 text-slate-800 dark:text-white text-sm"
          >
            <option value="">— اختر عميلاً —</option>
            {customers.map((c: any) => (
              <option key={c.CustomerID} value={c.CustomerID}>{c.Name} ({c.Phone || '—'}) — رصيد: {c.Balance?.toFixed(2)}</option>
            ))}
          </select>
        </div>
        <Input label="من تاريخ" type="date" value={fromDate} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setFromDate(e.target.value)} />
        <Input label="إلى تاريخ" type="date" value={toDate} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setToDate(e.target.value)} />
        {customerId && <Button onClick={() => fetchStatement(customerId)}>تحديث</Button>}
      </div>

      {loading && <p className="text-center text-slate-400 py-8">جاري التحميل...</p>}

      {!loading && data && customer && (
        <div className="space-y-4">
          {/* Customer info header */}
          <div className="bg-white dark:bg-slate-800 rounded-xl p-5 border border-slate-200 dark:border-slate-700">
            <div className="grid grid-cols-4 gap-4">
              <div>
                <div className="text-xs text-slate-400">الاسم</div>
                <div className="font-bold text-slate-800 dark:text-white">{customer.Name}</div>
              </div>
              <div>
                <div className="text-xs text-slate-400">الهاتف</div>
                <div className="text-slate-700 dark:text-slate-200">{customer.Phone || '—'}</div>
              </div>
              <div>
                <div className="text-xs text-slate-400">العنوان</div>
                <div className="text-slate-700 dark:text-slate-200">{customer.Address || '—'}</div>
              </div>
              <div>
                <div className="text-xs text-slate-400">الرصيد الحالي</div>
                <div className={`font-bold ${customer.Balance > 0 ? 'text-red-600' : 'text-green-600'}`}>
                  {customer.Balance?.toFixed(2)} {customer.Balance > 0 ? 'مدين' : 'دائن'}
                </div>
              </div>
            </div>
          </div>

          {/* Summary cards */}
          <div className="grid grid-cols-3 gap-3">
            <div className="bg-red-50 dark:bg-red-900/20 rounded-lg p-3">
              <div className="text-xs text-slate-500 dark:text-slate-400">إجمالي مدين (له عليه)</div>
              <div className="text-lg font-bold text-red-600">{data.totals.totalDebit?.toFixed(2)}</div>
            </div>
            <div className="bg-green-50 dark:bg-green-900/20 rounded-lg p-3">
              <div className="text-xs text-slate-500 dark:text-slate-400">إجمالي دائن (سدد)</div>
              <div className="text-lg font-bold text-green-600">{data.totals.totalCredit?.toFixed(2)}</div>
            </div>
            <div className="bg-blue-50 dark:bg-blue-900/20 rounded-lg p-3">
              <div className="text-xs text-slate-500 dark:text-slate-400">صافي الرصيد</div>
              <div className={`text-lg font-bold ${data.totals.netBalance >= 0 ? 'text-red-600' : 'text-green-600'}`}>
                {Math.abs(data.totals.netBalance).toFixed(2)} {data.totals.netBalance >= 0 ? 'مدين' : 'دائن'}
              </div>
            </div>
          </div>

          {/* Operations table */}
          <div className="overflow-x-auto rounded-lg border border-slate-200 dark:border-slate-700">
            <table className="w-full text-sm">
              <thead>
                <tr className="bg-slate-50 dark:bg-slate-800/50 border-b border-slate-200 dark:border-slate-700">
                  <th className="px-3 py-3 text-right font-semibold text-slate-600 dark:text-slate-300">التاريخ</th>
                  <th className="px-3 py-3 text-right font-semibold text-slate-600 dark:text-slate-300">النوع</th>
                  <th className="px-3 py-3 text-right font-semibold text-slate-600 dark:text-slate-300">المرجع</th>
                  <th className="px-3 py-3 text-right font-semibold text-slate-600 dark:text-slate-300">البيان</th>
                  <th className="px-3 py-3 text-right font-semibold text-slate-600 dark:text-slate-300">مدين</th>
                  <th className="px-3 py-3 text-right font-semibold text-slate-600 dark:text-slate-300">دائن</th>
                  <th className="px-3 py-3 text-right font-semibold text-slate-600 dark:text-slate-300">الرصيد</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100 dark:divide-slate-700/50">
                {data.operations.length === 0 ? (
                  <tr><td colSpan={7} className="px-3 py-8 text-center text-slate-400">لا توجد عمليات</td></tr>
                ) : (
                  data.operations.map((op: any, idx: number) => {
                    const typeInfo = opTypeLabels[op.OpType] || { label: op.OpType, variant: 'gray' };
                    return (
                      <tr key={idx} className="bg-white dark:bg-slate-800 hover:bg-slate-50 dark:hover:bg-slate-700/50">
                        <td className="px-3 py-2.5 text-slate-600 dark:text-slate-300">{op.Date}</td>
                        <td className="px-3 py-2.5">
                          <Badge variant={typeInfo.variant as any}>{typeInfo.label}</Badge>
                        </td>
                        <td className="px-3 py-2.5 font-mono text-xs text-slate-600 dark:text-slate-300">{op.RefNumber}</td>
                        <td className="px-3 py-2.5 text-slate-700 dark:text-slate-200">{op.Description}</td>
                        <td className="px-3 py-2.5 font-bold text-red-600">{op.Debit ? op.Debit.toFixed(2) : '—'}</td>
                        <td className="px-3 py-2.5 font-bold text-green-600">{op.Credit ? op.Credit.toFixed(2) : '—'}</td>
                        <td className="px-3 py-2.5 font-bold text-slate-800 dark:text-white">{op.Balance?.toFixed(2)}</td>
                      </tr>
                    );
                  })
                )}
              </tbody>
              {data.operations.length > 0 && (
                <tfoot>
                  <tr className="bg-slate-50 dark:bg-slate-800/50 border-t-2 border-slate-200 dark:border-slate-700 font-bold">
                    <td colSpan={4} className="px-3 py-3 text-slate-700 dark:text-slate-200">الإجمالي</td>
                    <td className="px-3 py-3 text-red-600">{data.totals.totalDebit.toFixed(2)}</td>
                    <td className="px-3 py-3 text-green-600">{data.totals.totalCredit.toFixed(2)}</td>
                    <td className="px-3 py-3 text-slate-800 dark:text-white">{data.totals.netBalance.toFixed(2)}</td>
                  </tr>
                </tfoot>
              )}
            </table>
          </div>
        </div>
      )}

      {!loading && !data && (
        <div className="text-center py-12">
          <FileText size={48} className="mx-auto text-slate-300 dark:text-slate-600 mb-3" />
          <p className="text-slate-400">اختر عميلاً لعرض كشف الحساب</p>
        </div>
      )}
    </div>
  );
}

