const [showQuickAdd, setShowQuickAdd] = useState(false);
const [quickAddForm, setQuickAddForm] = useState({ Barcode: '', ItemName: '', CostPrice: '', SalePrice: '', ItemType: 'accessory' });

const typeLabels: Record<string, string> = { phone: 'هاتف', accessory: 'إكسسوار', spare_part: 'قطعة غيار' };

// Barcode scan: find existing or prompt to create
const handleBarcodeScan = async () => {
  if (!barcodeSearch.trim()) return;
  const item = await window.api.invoke('items:findByBarcode', barcodeSearch.trim());
  if (item) {
    // Found - open edit
    setEditingItem(item);
    setItemForm({ ItemName: item.ItemName, CategoryID: item.CategoryID?.toString() || '', Barcode: item.Barcode || '', ItemType: item.ItemType, IsSerialized: item.IsSerialized, SalePrice: item.SalePrice?.toString() || '', CostPrice: item.CostPrice?.toString() || '', MinStock: item.MinStock?.toString() || '', Unit: item.Unit || 'قطعة', IsActive: item.IsActive });
    setShowItemModal(true);
  } else {
    // Not found - open quick add with barcode pre-filled
    setQuickAddForm({ Barcode: barcodeSearch.trim(), ItemName: '', CostPrice: '', SalePrice: '', ItemType: 'accessory' });
    setShowQuickAdd(true);
  }
  setBarcodeSearch('');
};

// Enter key on barcode field triggers scan
const onBarcodeKeyDown = (e: React.KeyboardEvent) => {
  if (e.key === 'Enter') {
    e.preventDefault();
    handleBarcodeScan();
  }
};

const handleQuickAdd = async () => {
  if (!quickAddForm.Barcode) { showToast('error', 'أدخل الباركود'); return; }
  const result = await window.api.invoke('items:quickCreate', {
    Barcode: quickAddForm.Barcode,
    ItemName: quickAddForm.ItemName || undefined,
    ItemType: quickAddForm.ItemType,
    CostPrice: quickAddForm.CostPrice ? parseFloat(quickAddForm.CostPrice) : 0,
    SalePrice: quickAddForm.SalePrice ? parseFloat(quickAddForm.SalePrice) : 0,
  });
  if (result.success) {
    showToast('success', 'تم إضافة الصنف بالباركود');
    setShowQuickAdd(false);
    setQuickAddForm({ Barcode: '', ItemName: '', CostPrice: '', SalePrice: '', ItemType: 'accessory' });
    fetchData();
  } else if (result.item) {
    showToast('info', 'الباركود موجود بالفعل - تم فتح الصنف');
    const item = result.item;
    setEditingItem(item);
    setItemForm({ ItemName: item.ItemName, CategoryID: item.CategoryID?.toString() || '', Barcode: item.Barcode || '', ItemType: item.ItemType, IsSerialized: item.IsSerialized, SalePrice: item.SalePrice?.toString() || '', CostPrice: item.CostPrice?.toString() || '', MinStock: item.MinStock?.toString() || '', Unit: item.Unit || 'قطعة', IsActive: item.IsActive });
    setShowItemModal(true);
    setShowQuickAdd(false);
  } else {
    showToast('error', result.message);
  }
};

