// Profit & Loss report - comprehensive and accurate
ipcMain.handle('reports:profitLoss', async (_event, filters: { fromDate?: string; toDate?: string }) => {
  const db = getDb();
  const params: any[] = [];
  let dateFilter = '';
  if (filters.fromDate) { dateFilter += ' AND Date >= ?'; params.push(filters.fromDate); }
  if (filters.toDate) { dateFilter += ' AND Date <= ?'; params.push(filters.toDate); }

  // ===== REVENUE (الإيرادات) =====

  // 1. Net Sales = Sales - Sale Returns
  const salesGross = db.prepare(`SELECT COALESCE(SUM(TotalAmount),0) as total FROM sales WHERE 1=1 ${dateFilter}`).get(...params) as any;
  const salesReturns = db.prepare(`
    SELECT COALESCE(SUM(r.TotalAmount),0) as total
    FROM sale_returns r
    JOIN sales s ON r.SaleID = s.SaleID
    WHERE 1=1 ${dateFilter.replace('Date', 'r.Date')}
  `).get(...params) as any;
  const netSales = salesGross.total - salesReturns.total;

  // 2. Maintenance Revenue (Labor + Parts markup + Additional - but we count TotalCost as revenue)
  const maintenanceRevenue = db.prepare(`
    SELECT COALESCE(SUM(TotalCost),0) as total FROM maintenance_deliveries WHERE 1=1 ${dateFilter}
  `).get(...params) as any;

  // 3. Other Income (voucher receipts that are general, not customer/supplier payments)
  const otherIncome = db.prepare(`
    SELECT COALESCE(SUM(Amount),0) as total FROM vouchers
    WHERE VoucherType = 'receipt' AND (PartyType = 'general' OR PartyType IS NULL)
    ${dateFilter}
  `).get(...params) as any;

  // 4. Rent Income (rent we receive - property we own/rent out)
  const rentIncome = db.prepare(`
    SELECT COALESCE(SUM(rp.Amount),0) as total
    FROM rent_payments rp
    JOIN rents r ON rp.RentID = r.RentID
    WHERE rp.Status = 'paid' AND r.RentType = 'income'
    ${filters.fromDate ? 'AND rp.PaidDate >= ?' : ''} ${filters.toDate ? 'AND rp.PaidDate <= ?' : ''}
  `).get(...(filters.fromDate ? [filters.fromDate] : []), ...(filters.toDate ? [filters.toDate] : [])) as any;

  const totalRevenue = netSales + maintenanceRevenue.total + otherIncome.total + rentIncome.total;

  // ===== DIRECT COSTS (التكاليف المباشرة) =====

  // 1. Cost of Goods Sold (from sale_details - actual cost of items sold)
  const cogs = db.prepare(`
    SELECT COALESCE(SUM(sd.UnitCost * sd.Quantity),0) as total
    FROM sale_details sd
    JOIN sales s ON sd.SaleID = s.SaleID
    WHERE 1=1 ${dateFilter.replace('Date', 's.Date')}
  `).get(...params) as any;

  // 2. Maintenance Parts Cost (cost of parts used in maintenance)
  const partsCost = db.prepare(`
    SELECT COALESCE(SUM(mp.TotalCost),0) as total
    FROM maintenance_parts mp
    JOIN maintenance_tickets t ON mp.TicketID = t.TicketID
    WHERE 1=1 ${dateFilter.replace('Date', 't.Date')}
  `).get(...params) as any;

  // 3. Purchase Returns value (items returned to supplier - reduces our stock value)
  const purchaseReturnsCost = db.prepare(`
    SELECT COALESCE(SUM(r.TotalAmount),0) as total
    FROM purchase_returns r
    JOIN purchases p ON r.PurchaseID = p.PurchaseID
    WHERE 1=1 ${dateFilter.replace('Date', 'r.Date')}
  `).get(...params) as any;

  const totalDirectCosts = cogs.total + partsCost.total;

  // Gross Profit = Revenue - Direct Costs
  const grossProfit = totalRevenue - totalDirectCosts;

  // ===== OPERATING EXPENSES (المصروفات التشغيلية) =====

  // 1. General Expenses (voucher payments that are general - electricity, rent, etc.)
  // NOTE: Payments to suppliers/customers are NOT expenses - they are debt payments
  const generalExpenses = db.prepare(`
    SELECT COALESCE(SUM(Amount),0) as total FROM vouchers
    WHERE VoucherType = 'payment' AND (PartyType = 'general' OR PartyType IS NULL OR PartyType = 'rent')
    ${dateFilter}
  `).get(...params) as any;

  // 2. Salaries Paid (actual cash out for salaries)
  const salariesPaid = db.prepare(`
    SELECT COALESCE(SUM(PaidAmount),0) as total FROM salaries
    WHERE 1=1 ${filters.fromDate ? 'AND PaymentDate >= ?' : ''} ${filters.toDate ? 'AND PaymentDate <= ?' : ''}
  `).get(...(filters.fromDate ? [filters.fromDate] : []), ...(filters.toDate ? [filters.toDate] : [])) as any;

  // 3. Employee Advances (cash given to employees - not yet deducted from salary)
  const employeeAdvances = db.prepare(`
    SELECT COALESCE(SUM(Amount),0) as total FROM employee_advances
    WHERE 1=1 ${dateFilter}
  `).get(...params) as any;

  // 4. Rent Expenses (rent we pay - shop rent, equipment rent)
  const rentExpenses = db.prepare(`
    SELECT COALESCE(SUM(rp.Amount),0) as total
    FROM rent_payments rp
    JOIN rents r ON rp.RentID = r.RentID
    WHERE rp.Status = 'paid' AND r.RentType = 'expense'
    ${filters.fromDate ? 'AND rp.PaidDate >= ?' : ''} ${filters.toDate ? 'AND rp.PaidDate <= ?' : ''}
  `).get(...(filters.fromDate ? [filters.fromDate] : []), ...(filters.toDate ? [filters.toDate] : [])) as any;

  // 5. Employee Deductions (damages, absences - actual loss to business)
  const employeeDeductions = db.prepare(`
    SELECT COALESCE(SUM(Amount),0) as total FROM employee_deductions
    WHERE 1=1 ${dateFilter}
  `).get(...params) as any;

  const totalExpenses = generalExpenses.total + salariesPaid.total + employeeAdvances.total + rentExpenses.total + employeeDeductions.total;

  // Net Profit = Gross Profit - Operating Expenses
  const netProfit = grossProfit - totalExpenses;

  return {
    revenue: {
      netSales,
      salesGross: salesGross.total,
      salesReturns: salesReturns.total,
      maintenance: maintenanceRevenue.total,
      otherIncome: otherIncome.total,
      rentIncome: rentIncome.total,
      total: totalRevenue,
    },
    costs: {
      cogs: cogs.total,
      parts: partsCost.total,
      total: totalDirectCosts,
    },
    grossProfit,
    expenses: {
      general: generalExpenses.total,
      salaries: salariesPaid.total,
      advances: employeeAdvances.total,
      rent: rentExpenses.total,
      deductions: employeeDeductions.total,
      total: totalExpenses,
    },
    netProfit,
  };
});

