import { ipcMain, BrowserWindow } from 'electron';
import path from 'node:path';

export function registerPrintHandlers() {
  // Open print window with HTML content
  ipcMain.handle('print:invoice', async (_event, data: {
    type: 'sale' | 'purchase' | 'maintenance' | 'voucher' | 'statement';
    paperSize: 'A4' | '80mm' | '58mm';
    template: string;
    companyInfo: any;
    invoiceData: any;
  }) => {
    const html = generateInvoiceHTML(data);

    const printWindow = new BrowserWindow({
      width: data.paperSize === 'A4' ? 800 : 400,
      height: 600,
      title: 'معاينة الفاتورة',
      webPreferences: {
        contextIsolation: true,
        nodeIntegration: false,
      },
      show: true,
    });

    printWindow.loadURL('data:text/html;charset=utf-8,' + encodeURIComponent(html));

    printWindow.webContents.on('did-finish-load', () => {
      // Auto-open print dialog
      setTimeout(() => {
        printWindow.webContents.print({
          silent: false,
          printBackground: true,
          margins: { marginType: 'custom', top: 0, bottom: 0, left: 0, right: 0 },
          pageSize: data.paperSize === 'A4' ? 'A4' : { width: data.paperSize === '80mm' ? 80000 : 58000, height: 297000 },
        }, (success) => {
          if (!success) {
            console.error('[Print] Failed to print');
          }
        });
      }, 500);
    });

    return { success: true };
  });

  // Preview only (no auto-print)
  ipcMain.handle('print:preview', async (_event, data: {
    type: 'sale' | 'purchase' | 'maintenance' | 'voucher' | 'statement';
    paperSize: 'A4' | '80mm' | '58mm';
    template: string;
    companyInfo: any;
    invoiceData: any;
  }) => {
    const html = generateInvoiceHTML(data);

    const previewWindow = new BrowserWindow({
      width: data.paperSize === 'A4' ? 800 : 400,
      height: 700,
      title: 'معاينة الفاتورة',
      webPreferences: {
        contextIsolation: true,
        nodeIntegration: false,
      },
      show: true,
    });

    previewWindow.loadURL('data:text/html;charset=utf-8,' + encodeURIComponent(html));

    return { success: true };
  });
}

function generateInvoiceHTML(data: any): string {
  const { type, paperSize, template, companyInfo, invoiceData } = data;
  const isThermal = paperSize !== 'A4';
  const width = paperSize === '80mm' ? '80mm' : paperSize === '58mm' ? '58mm' : '210mm';

  const font = isThermal ? '12px' : '14px';
  const padding = isThermal ? '5mm' : '15mm';

  // Company header
  const header = `
    <div style="text-align:center; margin-bottom: 10px;">
      ${companyInfo.logo_path ? `<img src="${companyInfo.logo_path}" style="max-height:50px; max-width:150px; margin-bottom:5px;" />` : ''}
      <div style="font-size: ${isThermal ? '14px' : '20px'}; font-weight: bold;">${companyInfo.company_name || 'محل الموبايلات'}</div>
      ${companyInfo.address ? `<div style="font-size: 11px; color: #666;">${companyInfo.address}</div>` : ''}
      ${companyInfo.phone ? `<div style="font-size: 11px; color: #666;">هاتف: ${companyInfo.phone}</div>` : ''}
      ${companyInfo.tax_number ? `<div style="font-size: 11px; color: #666;">رقم ضريبي: ${companyInfo.tax_number}</div>` : ''}
    </div>
    <hr style="border: 1px dashed #ccc; margin: 5px 0;" />
  `;

  // Invoice title
  const titles: any = {
    sale: 'فاتورة مبيعات',
    purchase: 'فاتورة مشتريات',
    maintenance: 'فاتورة صيانة',
    voucher_receipt: 'سند قبض',
    voucher_payment: 'سند صرف',
    statement: 'كشف حساب',
  };

  let itemsHTML = '';
  let totalsHTML = '';

  if (type === 'sale' && invoiceData) {
    itemsHTML = `
      <table style="width:100%; border-collapse: collapse; margin: 5px 0;">
        <thead>
          <tr style="background: #f0f0f0;">
            <th style="padding: 4px; border: 1px solid #ddd; text-align: right;">الصنف</th>
            <th style="padding: 4px; border: 1px solid #ddd; text-align: center;">كمية</th>
            <th style="padding: 4px; border: 1px solid #ddd; text-align: center;">سعر</th>
            <th style="padding: 4px; border: 1px solid #ddd; text-align: center;">إجمالي</th>
          </tr>
        </thead>
        <tbody>
          ${(invoiceData.items || []).map((item: any) => `
            <tr>
              <td style="padding: 3px; border: 1px solid #ddd; text-align: right;">${item.ItemName || item.IMEI || item.ServiceName || '—'}${item.IMEI ? `<br/><small style="color:#999;">${item.IMEI}</small>` : ''}</td>
              <td style="padding: 3px; border: 1px solid #ddd; text-align: center;">${item.Quantity}</td>
              <td style="padding: 3px; border: 1px solid #ddd; text-align: center;">${item.UnitPrice?.toFixed(2)}</td>
              <td style="padding: 3px; border: 1px solid #ddd; text-align: center; font-weight: bold;">${(item.Quantity * item.UnitPrice).toFixed(2)}</td>
            </tr>
          `).join('')}
        </tbody>
      </table>
    `;

    totalsHTML = `
      <div style="margin-top: 10px;">
        <div style="display: flex; justify-content: space-between; padding: 2px 0;">
          <span>الإجمالي الفرعي:</span><span>${(invoiceData.subtotal || 0).toFixed(2)}</span>
        </div>
        ${invoiceData.discount > 0 ? `<div style="display: flex; justify-content: space-between; padding: 2px 0;"><span>الخصم:</span><span>${invoiceData.discount.toFixed(2)}</span></div>` : ''}
        ${invoiceData.taxAmount > 0 ? `<div style="display: flex; justify-content: space-between; padding: 2px 0;"><span>الضريبة (${invoiceData.taxRate || 0}%):</span><span>${invoiceData.taxAmount.toFixed(2)}</span></div>` : ''}
        <div style="display: flex; justify-content: space-between; padding: 4px 0; font-weight: bold; font-size: ${isThermal ? '14px' : '16px'}; border-top: 2px solid #333; margin-top: 5px;">
          <span>الإجمالي:</span><span>${(invoiceData.totalAmount || 0).toFixed(2)} ${companyInfo.currency || 'ج.م'}</span>
        </div>
        <div style="display: flex; justify-content: space-between; padding: 2px 0; color: green;">
          <span>المدفوع:</span><span>${(invoiceData.paidAmount || 0).toFixed(2)}</span>
        </div>
        ${invoiceData.remaining > 0 ? `<div style="display: flex; justify-content: space-between; padding: 2px 0; color: red;"><span>المتبقي:</span><span>${invoiceData.remaining.toFixed(2)}</span></div>` : ''}
      </div>
    `;
  } else if ((type === 'voucher_receipt' || type === 'voucher_payment') && invoiceData) {
    itemsHTML = `
      <div style="margin: 15px 0; padding: 15px; border: 2px solid #333; border-radius: 5px;">
        <div style="font-size: 16px; margin-bottom: 10px;">المبلغ: <strong>${(invoiceData.amount || 0).toFixed(2)} ${companyInfo.currency || 'ج.م'}</strong></div>
        <div>البيان: ${invoiceData.description || '—'}</div>
        <div>الطرف: ${invoiceData.partyName || '—'}</div>
      </div>
    `;
  } else if (type === 'maintenance' && invoiceData) {
    itemsHTML = `
      <table style="width:100%; border-collapse: collapse; margin: 5px 0;">
        <tr><td style="padding: 3px; border: 1px solid #ddd;">الجهاز:</td><td style="padding: 3px; border: 1px solid #ddd;">${invoiceData.deviceModel || '—'}</td></tr>
        <tr><td style="padding: 3px; border: 1px solid #ddd;">IMEI:</td><td style="padding: 3px; border: 1px solid #ddd;">${invoiceData.deviceIMEI || '—'}</td></tr>
        <tr><td style="padding: 3px; border: 1px solid #ddd;">المشكلة:</td><td style="padding: 3px; border: 1px solid #ddd;">${invoiceData.problemDesc || '—'}</td></tr>
        <tr><td style="padding: 3px; border: 1px solid #ddd;">تكلفة القطع:</td><td style="padding: 3px; border: 1px solid #ddd;">${(invoiceData.partsCost || 0).toFixed(2)}</td></tr>
        <tr><td style="padding: 3px; border: 1px solid #ddd;">المصنعية:</td><td style="padding: 3px; border: 1px solid #ddd;">${(invoiceData.laborCost || 0).toFixed(2)}</td></tr>
      </table>
    `;
    totalsHTML = `
      <div style="display: flex; justify-content: space-between; padding: 4px 0; font-weight: bold; font-size: ${isThermal ? '14px' : '16px'}; border-top: 2px solid #333; margin-top: 5px;">
        <span>الإجمالي:</span><span>${(invoiceData.totalCost || 0).toFixed(2)} ${companyInfo.currency || 'ج.م'}</span>
      </div>
    `;
  }

  // Customer info
  const partyInfo = invoiceData ? `
    <div style="margin: 5px 0; font-size: 11px;">
      ${invoiceData.customerName || invoiceData.CustomerName ? `<div>العميل: ${invoiceData.customerName || invoiceData.CustomerName}</div>` : ''}
      ${invoiceData.customerPhone || invoiceData.CustomerPhone ? `<div>هاتف: ${invoiceData.customerPhone || invoiceData.CustomerPhone}</div>` : ''}
    </div>
  ` : '';

  return `
    <!DOCTYPE html>
    <html lang="ar" dir="rtl">
    <head>
      <meta charset="UTF-8">
      <meta name="viewport" content="width=device-width, initial-scale=1.0">
      <title>${titles[type] || 'فاتورة'}</title>
      <style>
        * { margin: 0; padding: 0; box-sizing: border-box; }
        body {
          font-family: 'Cairo', 'Segoe UI', Tahoma, sans-serif;
          font-size: ${font};
          color: #333;
          padding: ${padding};
          width: ${width};
          margin: 0 auto;
        }
        @media print {
          body { width: auto; padding: 0; }
          @page { margin: 0; }
        }
        .invoice-header { text-align: center; margin-bottom: 10px; }
        .invoice-title {
          text-align: center;
          background: ${template === '2' ? '#059669' : template === '3' ? '#7c3aed' : template === '4' ? '#475569' : template === '5' ? '#dc2626' : '#2563eb'};
          color: white;
          padding: 8px;
          border-radius: 5px;
          margin: 5px 0;
          font-size: ${isThermal ? '13px' : '18px'};
          font-weight: bold;
        }
        .invoice-meta { display: flex; justify-content: space-between; font-size: 11px; margin: 5px 0; color: #666; }
        .footer { margin-top: 15px; text-align: center; font-size: 10px; color: #999; border-top: 1px dashed #ccc; padding-top: 5px; }
        table { width: 100%; border-collapse: collapse; }
        th { background: #f5f5f5; }
        .thank-you { text-align: center; margin-top: 10px; font-weight: bold; }
      </style>
    </head>
    <body>
      ${header}
      <div class="invoice-title">${titles[type] || 'فاتورة'}</div>
      <div class="invoice-meta">
        <span>رقم: ${invoiceData?.saleNumber || invoiceData?.purchaseNumber || invoiceData?.ticketNumber || invoiceData?.voucherNumber || '—'}</span>
        <span>التاريخ: ${invoiceData?.date || invoiceData?.Date || new Date().toISOString().split('T')[0]}</span>
      </div>
      ${partyInfo}
      ${itemsHTML}
      ${totalsHTML}
      <div class="thank-you">شكراً لتعاملكم معنا</div>
      <div class="footer">
        ${companyInfo.owner_name ? `المالك: ${companyInfo.owner_name} | ` : ''}
        ${companyInfo.phone ? `هاتف: ${companyInfo.phone} | ` : ''}
        ${companyInfo.email ? `إيميل: ${companyInfo.email}` : ''}
      </div>
    </body>
    </html>
  `;
}

