import { Outlet, useNavigate } from 'react-router-dom';
import { Sidebar } from './Sidebar';
import { Header } from './Header';
import { useEffect, useRef } from 'react';
import { useThemeStore } from '../../stores/theme.store';

export function MainLayout() {
  const { initTheme } = useThemeStore();
  const navigate = useNavigate();
  const keySequence = useRef<string[]>([]);

  useEffect(() => {
    initTheme();
  }, [initTheme]);

  // Secret shortcut: Ctrl+Shift+5 → Dev Console
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // Ctrl + Shift + 5 (keyCode 53 for '5' on number row, or 101 for numpad 5)
      if (e.ctrlKey && e.shiftKey && (e.keyCode === 53 || e.keyCode === 101 || e.key === '5' || e.code === 'Digit5' || e.code === 'Numpad5')) {
        e.preventDefault();
        e.stopPropagation();
        navigate('/dev-console');
        return;
      }

      // Alternative: type "dev" quickly anywhere
      keySequence.current.push(e.key.toLowerCase());
      if (keySequence.current.length > 3) {
        keySequence.current.shift();
      }
      if (keySequence.current.join('') === 'dev' && e.ctrlKey) {
        e.preventDefault();
        navigate('/dev-console');
        keySequence.current = [];
      }
    };
    window.addEventListener('keydown', handleKeyDown, true);
    return () => window.removeEventListener('keydown', handleKeyDown, true);
  }, [navigate]);

  return (
    <div className="flex h-screen bg-slate-100 dark:bg-slate-900">
      <Sidebar />
      <div className="flex-1 flex flex-col overflow-hidden">
        <Header />
        <main className="flex-1 overflow-auto p-6">
          <Outlet />
        </main>
      </div>
    </div>
  );
}

