              <div
                className="rounded-lg p-3 mb-3"
                style={{ backgroundColor: tmpl.colors.bg, color: tmpl.colors.text }}
              >
                <div className="h-2 rounded-full mb-2" style={{ backgroundColor: tmpl.colors.primary, width: '40%' }} />
                <div className="h-1.5 rounded-full mb-1 bg-slate-200" style={{ width: '100%' }} />
                <div className="h-1.5 rounded-full mb-1 bg-slate-200" style={{ width: '80%' }} />
                <div className="h-1.5 rounded-full bg-slate-200" style={{ width: '60%' }} />
                <div className="mt-2 h-3 rounded" style={{ backgroundColor: tmpl.colors.primary, width: '30%' }} />
              </div>
              <div className="flex items-center justify-between">
                <span className="text-sm font-medium text-slate-700 dark:text-slate-200">{tmpl.name}</span>
                {selectedTemplate === tmpl.id && (
                  <span className="text-xs text-primary-600 font-medium">مُختار</span>
                )}
              </div>
            </button>
          ))}
        </div>
      </div>

      {/* Options */}
      <div className="bg-white dark:bg-slate-800 rounded-xl p-6 border border-slate-200 dark:border-slate-700">
        <h2 className="text-lg font-semibold text-slate-800 dark:text-white mb-4">خيارات الطباعة</h2>
        <div className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">حجم الورق</label>
            <select
              value={paperSize}
              onChange={(e) => setPaperSize(e.target.value)}
              className="w-full max-w-xs px-3 py-2 rounded-lg border border-slate-300 dark:border-slate-600 bg-white dark:bg-slate-800 text-slate-800 dark:text-white text-sm"
            >
              <option value="A4">A4 (عادي)</option>
              <option value="80mm">حراري 80mm</option>
              <option value="58mm">حراري 58mm</option>
            </select>
          </div>

          <label className="flex items-center gap-3 cursor-pointer">
            <input
              type="checkbox"
              checked={showCustomerInfo}
              onChange={(e) => setShowCustomerInfo(e.target.checked)}
              className="w-4 h-4 rounded text-primary-600 focus:ring-primary-500"
            />
            <span className="text-sm text-slate-700 dark:text-slate-200">إظهار بيانات العميل في الفاتورة</span>
          </label>

          <label className="flex items-center gap-3 cursor-pointer">
            <input
              type="checkbox"
              checked={showShopInfo}
              onChange={(e) => setShowShopInfo(e.target.checked)}
              className="w-4 h-4 rounded text-primary-600 focus:ring-primary-500"
            />
            <span className="text-sm text-slate-700 dark:text-slate-200">إظهار بيانات المحل في الفاتورة</span>
          </label>
        </div>
      </div>

      <div className="flex justify-end">
        <Button onClick={handleSave} icon={<Save size={16} />}>
          حفظ إعدادات الطباعة
        </Button>
      </div>
    </div>
  );
}

