import { ipcMain, BrowserWindow } from 'electron';

export function registerPrintHandlers() {
  // Preview invoice - shows preview window with print button
  ipcMain.handle('print:preview', async (_event, data: {
    type: string;
    paperSize: string;
    template: string;
    companyInfo: any;
    invoiceData: any;
  }) => {
    const html = generateInvoiceHTML(data, false);

    const previewWindow = new BrowserWindow({
      width: data.paperSize === 'A4' ? 820 : 420,
      height: 750,
      title: 'معاينة الفاتورة',
      webPreferences: {
        contextIsolation: true,
        nodeIntegration: false,
      },
      show: true,
    });

    previewWindow.loadURL('data:text/html;charset=utf-8,' + encodeURIComponent(html));
    return { success: true };
  });

  // Print directly - opens print dialog
  ipcMain.handle('print:invoice', async (_event, data: {
    type: string;
    paperSize: string;
    template: string;
    companyInfo: any;
    invoiceData: any;
  }) => {
    const html = generateInvoiceHTML(data, false);

    const printWindow = new BrowserWindow({
      width: data.paperSize === 'A4' ? 820 : 420,
      height: 750,
      title: 'طباعة الفاتورة',
      webPreferences: {
        contextIsolation: true,
        nodeIntegration: false,
      },
      show: true,
    });

    printWindow.loadURL('data:text/html;charset=utf-8,' + encodeURIComponent(html));

    printWindow.webContents.on('did-finish-load', () => {
      setTimeout(() => {
        printWindow.webContents.print({
          silent: false,
          printBackground: true,
          margins: { marginType: 'custom', top: 0, bottom: 0, left: 0, right: 0 },
          pageSize: getPageSize(data.paperSize),
        }, () => {});
      }, 500);
    });

    return { success: true };
  });
}

function getPageSize(paperSize: string) {
  if (paperSize === 'A4') return 'A4';
  if (paperSize === 'A5') return 'A5';
  if (paperSize === '80mm') return { width: 80000, height: 297000 };
  if (paperSize === '58mm') return { width: 58000, height: 297000 };
  return 'A4';
}

function generateInvoiceHTML(data: any, autoPrint: boolean): string {
  const { type, paperSize, template, companyInfo, invoiceData } = data;
  const isThermal = paperSize === '80mm' || paperSize === '58mm';
  const isA5 = paperSize === 'A5';
  const width = paperSize === '80mm' ? '80mm' : paperSize === '58mm' ? '58mm' : paperSize === 'A5' ? '148mm' : '210mm';
  const font = isThermal ? '12px' : isA5 ? '13px' : '14px';
  const padding = isThermal ? '5mm' : isA5 ? '8mm' : '15mm';

  const titles: any = {
    sale: 'فاتورة مبيعات', purchase: 'فاتورة مشتريات',
    maintenance: 'فاتورة صيانة', voucher_receipt: 'سند قبض',
    voucher_payment: 'سند صرف', statement: 'كشف حساب',
  };

  const showCustomer = companyInfo.invoice_show_customer !== '0';
  const showShop = companyInfo.invoice_show_shop !== '0';

  const header = showShop ? `
    <div class="invoice-header">
      ${companyInfo.logo_path ? `<img src="${companyInfo.logo_path}" class="logo" />` : ''}
      <div class="company-name">${companyInfo.company_name || 'محل الموبايلات'}</div>
      ${companyInfo.address ? `<div class="info-line">${companyInfo.address}</div>` : ''}
      ${companyInfo.phone ? `<div class="info-line">هاتف: ${companyInfo.phone}</div>` : ''}
      ${companyInfo.tax_number ? `<div class="info-line">رقم ضريبي: ${companyInfo.tax_number}</div>` : ''}
    </div>
    <hr class="divider" />
  ` : '';

  let itemsHTML = '';
  let totalsHTML = '';

  if (type === 'sale' && invoiceData) {
    itemsHTML = `
      <table class="items-table">
        <thead><tr>
          <th>الصنف</th><th>كمية</th><th>سعر</th><th>إجمالي</th>
        </tr></thead>
        <tbody>
          ${(invoiceData.items || []).map((item: any) => `
            <tr>
              <td>${item.ItemName || item.IMEI || item.ServiceName || '—'}${item.IMEI ? `<br/><small class="imei">${item.IMEI}</small>` : ''}</td>
              <td class="center">${item.Quantity}</td>
              <td class="center">${item.UnitPrice?.toFixed(2)}</td>
              <td class="center bold">${(item.Quantity * item.UnitPrice).toFixed(2)}</td>
            </tr>
          `).join('')}
        </tbody>
      </table>
    `;
    totalsHTML = `
      <div class="totals">
        <div class="total-row"><span>الإجمالي الفرعي:</span><span>${(invoiceData.subtotal || 0).toFixed(2)}</span></div>
        ${invoiceData.discount > 0 ? `<div class="total-row"><span>الخصم:</span><span>${invoiceData.discount.toFixed(2)}</span></div>` : ''}
        ${invoiceData.taxAmount > 0 ? `<div class="total-row"><span>الضريبة (${invoiceData.taxRate || 0}%):</span><span>${invoiceData.taxAmount.toFixed(2)}</span></div>` : ''}
        <div class="total-row grand"><span>الإجمالي:</span><span>${(invoiceData.totalAmount || 0).toFixed(2)} ${companyInfo.currency || 'ج.م'}</span></div>
        <div class="total-row paid"><span>المدفوع:</span><span>${(invoiceData.paidAmount || 0).toFixed(2)}</span></div>
        ${invoiceData.remaining > 0 ? `<div class="total-row remaining"><span>المتبقي:</span><span>${invoiceData.remaining.toFixed(2)}</span></div>` : ''}
      </div>
    `;
  } else if ((type === 'voucher_receipt' || type === 'voucher_payment') && invoiceData) {
    itemsHTML = `
      <div class="voucher-box">
        <div class="voucher-amount">المبلغ: <strong>${(invoiceData.amount || 0).toFixed(2)} ${companyInfo.currency || 'ج.م'}</strong></div>
        <div class="voucher-desc">البيان: ${invoiceData.description || '—'}</div>
        <div class="voucher-party">الطرف: ${invoiceData.partyName || '—'}</div>
      </div>
    `;
  } else if (type === 'maintenance' && invoiceData) {
    itemsHTML = `
      <table class="items-table">
        <tr><td>الجهاز:</td><td>${invoiceData.deviceModel || '—'}</td></tr>
        <tr><td>IMEI:</td><td>${invoiceData.deviceIMEI || '—'}</td></tr>
        <tr><td>المشكلة:</td><td>${invoiceData.problemDesc || '—'}</td></tr>
        <tr><td>تكلفة القطع:</td><td>${(invoiceData.partsCost || 0).toFixed(2)}</td></tr>
        <tr><td>المصنعية:</td><td>${(invoiceData.laborCost || 0).toFixed(2)}</td></tr>
      </table>
    `;
    totalsHTML = `
      <div class="totals">
        <div class="total-row grand"><span>الإجمالي:</span><span>${(invoiceData.totalCost || 0).toFixed(2)} ${companyInfo.currency || 'ج.م'}</span></div>
      </div>
    `;
  }

  const partyInfo = showCustomer && invoiceData ? `
    <div class="party-info">
      ${invoiceData.customerName || invoiceData.CustomerName ? `<div>العميل: ${invoiceData.customerName || invoiceData.CustomerName}</div>` : ''}
      ${invoiceData.customerPhone || invoiceData.CustomerPhone ? `<div>هاتف: ${invoiceData.customerPhone || invoiceData.CustomerPhone}</div>` : ''}
    </div>
  ` : '';

  const primaryColor = template === '2' ? '#059669' : template === '3' ? '#7c3aed' : template === '4' ? '#475569' : template === '5' ? '#dc2626' : '#2563eb';

  return `
    <!DOCTYPE html>
    <html lang="ar" dir="rtl">
    <head>
      <meta charset="UTF-8">
      <meta name="viewport" content="width=device-width, initial-scale=1.0">
      <title>${titles[type] || 'فاتورة'}</title>
      <style>
        * { margin: 0; padding: 0; box-sizing: border-box; }
        body { font-family: 'Cairo', 'Segoe UI', Tahoma, sans-serif; font-size: ${font}; color: #333; padding: ${padding}; width: ${width}; margin: 0 auto; }
        @media print { body { width: auto; padding: 0; } @page { margin: 0; size: ${width} auto; } .no-print { display: none !important; } }
        .invoice-header { text-align: center; margin-bottom: 8px; }
        .logo { max-height: 50px; max-width: 150px; margin-bottom: 5px; }
        .company-name { font-size: ${isThermal ? '14px' : '20px'}; font-weight: bold; }
        .info-line { font-size: 11px; color: #666; }
        .divider { border: none; border-top: 1px dashed #ccc; margin: 5px 0; }
        .invoice-title { text-align: center; background: ${primaryColor}; color: white; padding: 8px; border-radius: 5px; margin: 5px 0; font-size: ${isThermal ? '13px' : '18px'}; font-weight: bold; }
        .invoice-meta { display: flex; justify-content: space-between; font-size: 11px; margin: 5px 0; color: #666; }
        .party-info { margin: 5px 0; font-size: 11px; }
        .items-table { width: 100%; border-collapse: collapse; margin: 5px 0; }
        .items-table th { background: #f5f5f5; padding: 4px; border: 1px solid #ddd; text-align: right; }
        .items-table td { padding: 3px; border: 1px solid #ddd; }
        .items-table .center { text-align: center; }
        .items-table .bold { font-weight: bold; }
        .imei { color: #999; font-size: 10px; }
        .totals { margin-top: 8px; }
        .total-row { display: flex; justify-content: space-between; padding: 2px 0; }
        .total-row.grand { font-weight: bold; font-size: ${isThermal ? '14px' : '16px'}; border-top: 2px solid #333; margin-top: 5px; padding-top: 4px; }
        .total-row.paid { color: green; }
        .total-row.remaining { color: red; }
        .voucher-box { margin: 15px 0; padding: 15px; border: 2px solid #333; border-radius: 5px; }
        .voucher-amount { font-size: 16px; margin-bottom: 8px; }
        .thank-you { text-align: center; margin-top: 10px; font-weight: bold; }
        .footer { margin-top: 10px; text-align: center; font-size: 10px; color: #999; border-top: 1px dashed #ccc; padding-top: 5px; }
        .print-btn { position: fixed; bottom: 20px; left: 50%; transform: translateX(-50%); background: ${primaryColor}; color: white; padding: 10px 30px; border: none; border-radius: 8px; font-size: 16px; cursor: pointer; font-family: inherit; box-shadow: 0 2px 8px rgba(0,0,0,0.2); }
        .print-btn:hover { opacity: 0.9; }
      </style>
    </head>
    <body>
      ${header}
      <div class="invoice-title">${titles[type] || 'فاتورة'}</div>
      <div class="invoice-meta">
        <span>رقم: ${invoiceData?.saleNumber || invoiceData?.purchaseNumber || invoiceData?.ticketNumber || invoiceData?.voucherNumber || '—'}</span>
        <span>التاريخ: ${invoiceData?.date || invoiceData?.Date || new Date().toISOString().split('T')[0]}</span>
      </div>
      ${partyInfo}
      ${itemsHTML}
      ${totalsHTML}
      <div class="thank-you">شكراً لتعاملكم معنا</div>
      <div class="footer">
        ${companyInfo.owner_name ? `المالك: ${companyInfo.owner_name} | ` : ''}
        ${companyInfo.phone ? `هاتف: ${companyInfo.phone}` : ''}
      </div>
      <button class="print-btn no-print" onclick="window.print()">🖨️ طباعة</button>
    </body>
    </html>
  `;
}

import { useState, useEffect } from 'react';
import { Save } from 'lucide-react';
import { Button } from '../../components/ui/Button';
import { useToastStore } from '../../components/ui/Toast';

const templates = [
  { id: '1', name: 'القالب الكلاسيكي', colors: { primary: '#2563eb', bg: '#ffffff' } },
  { id: '2', name: 'القالب العصري', colors: { primary: '#059669', bg: '#f0fdf4' } },
  { id: '3', name: 'القالب الأنيق', colors: { primary: '#7c3aed', bg: '#faf5ff' } },
  { id: '4', name: 'القالب البسيط', colors: { primary: '#475569', bg: '#f8fafc' } },
  { id: '5', name: 'القالب الملوّن', colors: { primary: '#dc2626', bg: '#fef2f2' } },
];

const paperSizes = [
  { value: '80mm', label: 'حراري 80mm', desc: 'ماكينة حرارية صغيرة' },
  { value: '58mm', label: 'حراري 58mm', desc: 'ماكينة حرارية صغيرة جداً' },
  { value: 'A5', label: 'A5', desc: 'نصف صفحة A4' },
  { value: 'A4', label: 'A4', desc: 'صفحة كاملة عادية' },
];

export function PrintSettings() {
  const { showToast } = useToastStore();
  const [selectedTemplate, setSelectedTemplate] = useState('1');
  const [showCustomerInfo, setShowCustomerInfo] = useState(true);
  const [showShopInfo, setShowShopInfo] = useState(true);
  const [paperSize, setPaperSize] = useState('80mm');
  const [defaultAction, setDefaultAction] = useState('preview');

  useEffect(() => {
    (async () => {
      const settings = await window.api.invoke('settings:getAll');
      setSelectedTemplate(settings.default_invoice_template || '1');
      setShowCustomerInfo(settings.invoice_show_customer !== '0');
      setShowShopInfo(settings.invoice_show_shop !== '0');
      setPaperSize(settings.paper_size || '80mm');
      setDefaultAction(settings.print_default_action || 'preview');
    })();
  }, []);

  const handleSave = async () => {
    await window.api.invoke('settings:setMany', {
      default_invoice_template: selectedTemplate,
      invoice_show_customer: showCustomerInfo ? '1' : '0',
      invoice_show_shop: showShopInfo ? '1' : '0',
      paper_size: paperSize,
      print_default_action: defaultAction,
    });
    showToast('success', 'تم حفظ إعدادات الطباعة');
  };

  return (
    <div className="max-w-3xl space-y-6">
      {/* Paper Size */}
      <div className="bg-white dark:bg-slate-800 rounded-xl p-6 border border-slate-200 dark:border-slate-700">
        <h2 className="text-lg font-semibold text-slate-800 dark:text-white mb-4">حجم الورق الافتراضي</h2>
        <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
          {paperSizes.map(ps => (
            <button key={ps.value} onClick={() => setPaperSize(ps.value)}
              className={`p-4 rounded-xl border-2 text-center transition-all ${paperSize === ps.value ? 'border-primary-600 bg-primary-50 dark:bg-primary-900/20' : 'border-slate-200 dark:border-slate-700 hover:border-slate-300'}`}>
              <div className={`font-bold text-sm ${paperSize === ps.value ? 'text-primary-700 dark:text-primary-300' : 'text-slate-700 dark:text-slate-200'}`}>{ps.label}</div>
              <div className="text-[10px] text-slate-400 mt-1">{ps.desc}</div>
            </button>
          ))}
        </div>
      </div>

      {/* Default Action */}
      <div className="bg-white dark:bg-slate-800 rounded-xl p-6 border border-slate-200 dark:border-slate-700">
        <h2 className="text-lg font-semibold text-slate-800 dark:text-white mb-4">سلوك زر الطباعة</h2>
        <p className="text-xs text-slate-400 mb-3">عند الضغط على زر الطباعة في الفاتورة، ماذا يحدث؟</p>
        <div className="flex gap-3">
          <button onClick={() => setDefaultAction('preview')}
            className={`flex-1 p-4 rounded-xl border-2 text-center transition-all ${defaultAction === 'preview' ? 'border-primary-600 bg-primary-50 dark:bg-primary-900/20' : 'border-slate-200 dark:border-slate-700'}`}>
            <div className="font-bold text-sm text-slate-700 dark:text-slate-200">معاينة أولاً</div>
            <div className="text-[10px] text-slate-400 mt-1">يفتح معاينة + زر طباعة</div>
          </button>
          <button onClick={() => setDefaultAction('print')}
            className={`flex-1 p-4 rounded-xl border-2 text-center transition-all ${defaultAction === 'print' ? 'border-primary-600 bg-primary-50 dark:bg-primary-900/20' : 'border-slate-200 dark:border-slate-700'}`}>
            <div className="font-bold text-sm text-slate-700 dark:text-slate-200">طباعة مباشرة</div>
            <div className="text-[10px] text-slate-400 mt-1">يفتح نافذة الطباعة مباشرة</div>
          </button>
        </div>
      </div>

      {/* Templates */}
      <div className="bg-white dark:bg-slate-800 rounded-xl p-6 border border-slate-200 dark:border-slate-700">
        <h2 className="text-lg font-semibold text-slate-800 dark:text-white mb-4">قوالب الفاتورة</h2>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {templates.map((tmpl) => (
            <button key={tmpl.id} onClick={() => setSelectedTemplate(tmpl.id)}
              className={`p-4 rounded-xl border-2 transition-all text-right ${selectedTemplate === tmpl.id ? 'border-primary-600 ring-2 ring-primary-200' : 'border-slate-200 dark:border-slate-700 hover:border-slate-300'}`}>
              <div className="rounded-lg p-3 mb-3" style={{ backgroundColor: tmpl.colors.bg }}>
                <div className="h-2 rounded-full mb-2" style={{ backgroundColor: tmpl.colors.primary, width: '40%' }} />
                <div className="h-1.5 rounded-full mb-1 bg-slate-200" style={{ width: '100%' }} />
                <div className="h-1.5 rounded-full mb-1 bg-slate-200" style={{ width: '80%' }} />
                <div className="h-1.5 rounded-full bg-slate-200" style={{ width: '60%' }} />
                <div className="mt-2 h-3 rounded" style={{ backgroundColor: tmpl.colors.primary, width: '30%' }} />
              </div>
              <div className="flex items-center justify-between">
                <span className="text-sm font-medium text-slate-700 dark:text-slate-200">{tmpl.name}</span>
                {selectedTemplate === tmpl.id && <span className="text-xs text-primary-600 font-medium">مُختار</span>}
              </div>
            </button>
          ))}
        </div>
      </div>

      {/* Options */}
      <div className="bg-white dark:bg-slate-800 rounded-xl p-6 border border-slate-200 dark:border-slate-700">
        <h2 className="text-lg font-semibold text-slate-800 dark:text-white mb-4">خيارات العرض</h2>
        <div className="space-y-3">
          <label className="flex items-center gap-3 cursor-pointer">
            <input type="checkbox" checked={showCustomerInfo} onChange={(e) => setShowCustomerInfo(e.target.checked)} className="w-4 h-4 rounded text-primary-600 focus:ring-primary-500" />
            <span className="text-sm text-slate-700 dark:text-slate-200">إظهار بيانات العميل</span>
          </label>
