    ? deliverForm.AdditionalCosts.split('\n').filter((l: string) => l.trim()).map((line: string) => {
        const [desc, amount] = line.split('|');
        return { Description: desc?.trim() || 'تكلفة إضافية', Amount: parseFloat(amount?.trim() || '0') || 0 };
      })
    : [];

  const result = await window.api.invoke('maintenance:deliver', {
    TicketID: parseInt(selectedTicket),
    CustomerID: ticket?.CustomerID,
    CustomerName: ticket?.CustomerName,
    LaborCost: parseFloat(deliverForm.LaborCost) || 0,
    AdditionalCosts: additionalCosts,
    PaymentMethod: deliverForm.PaymentMethod,
    PaidAmount: parseFloat(deliverForm.PaidAmount) || 0,
    CashAccountID: deliverForm.CashAccountID ? parseInt(deliverForm.CashAccountID) : undefined,
    userId: 1, fiscalYearId: activeFy.FiscalYearID,
  });

  if (result.success) {
    let msg = `تم تسليم الجهاز - الإجمالي: ${result.totalCost?.toFixed(2)}`;
    if (result.remaining > 0) msg += ` | المتبقي على العميل: ${result.remaining.toFixed(2)}`;
    showToast('success', msg);
    setShowDeliver(false);
    setSelectedTicket('');
    setDeliverForm({ LaborCost: '', AdditionalCosts: '', PaidAmount: '', CashAccountID: '', PaymentMethod: 'cash' });
    setTicketDetails(null);
    fetchData();
  }
};

